(window.GIM_TS=window.GIM_TS||{})["Sukkah.3"]={"from":72,"a":[["\u0003שירי מצוה מעכבין את הפורענות.\u0004 שאפילו חלק המצוה שאיננו עיקרי והוא רק כשיריים שלה — אף הוא כוחו יפה לעכב הפורענות. \u0003שהרי תנופה שירי מצוה היא,\u0004 שכן אם לא הניף — יצא ידי חובה, ובכל זאת אמרנו ש\u0003עוצרת רוחות וטללים רעים. ואמר רבא: וכן\u0004 צריך לנהוג גם \u0003בלולב\u0004 (מוליך ומביא, מעלה ומוריד) ומאותם הטעמים. מסופר: \u0003רב אחא בר יעקב ממטי ליה ומייתי ליה\u0004 \u0005[היה מוליך ומביא אותו]\u0006 את הלולב ו\u0003אמר\u0004 באותה שעה: \u0003דין גירא בעיניה דסטנא\u0004 \u0005[זה חץ בעיניו של השטן,\u0006 יצר הרע\u0005]\u0006 שאנו מקיימים את המצוה ושמחים בה. ומעירים: \u0003ולאו מלתא היא\u0004 \u0005[ואין זה דבר],\u0006 כלומר: אין ראוי לומר כן, \u0003משום דאתי לאיגרויי ביה\u0004 \u0005[שעשוי\u0006 השטן \u0005להתגרות בו],\u0006 שאם הוא מדגיש את נצחונו על יצר הרע יבוא להתגרות בו ביותר.","\u0003מי שבא בדרך ולא היה בידו לולב ליטול — לכשיכנס לביתו\u0004 לאכול, \u0003יטול על שלחנו,\u0004 כלומר: יפסיק סעודתו ויטול לולב. \u0003לא נטל\u0004 את הלולב \u0003שחרית — יטול בין הערבים, שכל היום\u0004 כולו \u0003כשר ללולב.\u0004","בלשון המשנה מדקדקים: \u0003אמרת\u0004 במשנה שאם לא נטל את הלולב לפני הסעודה, \u0003נוטלו על שלחנו; למימרא\u0004 \u0005[לומר]\u0006 מכאן שהוא \u0003מפסיק,\u0004 שאם נזכר שלא נטל הרי הוא מפסיק אפילו באמצע הסעודה ונוטל, ואחר כך ממשיך בסעודתו, \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקור אחר, שאמרו שיש להתפלל תפילת מנחה לפני הסעודה, אבל \u0003אם התחילו\u0004 בסעודה — \u0003אין מפסיקין,\u0004 הרי שאף לצורך מצוה אין מפסיקים בסעודה! \u0003אמר רב ספרא: לא קשיא\u0004 \u0005[קשה],\u0006 ואפשר לתרץ כי \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאין מפסיקים — \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שהות ביום\u0004 להתפלל אחר כך, \u0003הא\u0004 \u0005[זו]\u0006 ששנינו שמפסיקים — \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שהות ביום,\u0004 ולכן ראוי לו להזדרז ולעשות את המצוה, שמא לא יספיק מאוחר יותר לעשותה.","\u0003אמר רבא: מאי קושיא\u0004 \u0005[מה הקושיה]?\u0006 שמתחילה לא היה מקום לקושיה, כי \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 מצות הלולב \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 ולכן מפסיק בסעודתו כדי לקיימה, \u0003הא\u0004 \u0005[זו]\u0006 תפילת המנחה \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ולכן אינו צריך להפסיק לצורך קיומה. \u0003אלא אמר רבא:\u0004 יש לחזור משאלה זו, ו\u0003אי קשיא הא קשיא\u0004 \u0005[\u0006ו\u0005אם קשה\u0006 בענין זה של הפסקה \u0005זה הוא הקשה];\u0006 ששנינו: \u0003לכשיכנס לביתו\u0004 — \u0003נוטלו על שלחנו, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מפסיק, והדר תני\u0004 \u0005[חזר ושנה]:\u0006 \u0003לא נטל שחרית — יטול בין הערבים. אלמא\u0004 \u0005[מכאן]\u0006 שהוא \u0003לא מפסיק\u0004 בסעודתו, אלא דוחה את נטילת הלולב לשעה מאוחרת יותר!","ועל כך \u0003אמר רב ספרא: לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שאינו מפסיק — \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שהות ביום\u0004 לקיים את המצווה מאוחר יותר, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמפסיק — \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שהות ביום\u0004 ולכך צריך להפסיק.","\u0003אמר ר' זירא: מאי קושיא\u0004 \u0005[מה הקושיה]\u0006 והסתירה שמצא רבא? \u0003דלמא\u0004 \u0005[שמא]\u0006 פירוש הדבר כך הוא: אכן ה\u0003מצוה\u0004 היא \u0003לאפסוקי\u0004 \u0005[להפסיק]\u0006 מסעודתו, אלא \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא פסיק\u0004 \u0005[הפסיק]\u0006 כמצותו — \u0003יטול בין הערבים, שכל היום כשר ללולב.\u0004 ואין איפוא קושי עוד. \u0003אלא אמר ר' זירא: לעולם\u0004 יש להקשות \u0003כדאמרינן מעיקרא\u0004 \u0005[כפי שאמרנו מתחילה]\u0006 בסתירה מדין לולב לדין תפילה, \u0003ודקשיא לך\u0004 \u0005[ומה שהיה קשה לך]\u0006 מדוע אין לתרץ סתירה זו באופן זה; \u0003הא דאורייתא\u0004 \u0005[זו\u0006 מצות הלולב \u0005מן התורה]\u0006 \u0003הא דרבנן\u0004 \u0005[זו\u0006 תפלת מנחה \u0005מדברי סופרים]\u0006 — צריך לומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ביום טוב שני\u0004 (חול המועד) שמצות לולב בו היא \u0003דרבנן עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ולכן אפשר להקשות מדין תפילה לדין לולב, לפי ששניהם מדברי סופרים.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן\u0006 כך\u0005]\u0006 מלשון המשנה, שמדובר ביום טוב שני, כלומר: בחול המועד. וההוכחה לכך, \u0003מדקתני\u0004 \u0005[ממה ששנינו]\u0006 בה: \u0003מי שבא בדרך ואין בידו לולב. דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שמדובר \u0003ביום טוב ראשון מי שרי\u0004 \u0005[האם מותר]\u0006 ללכת בדרך רחוקה ביום זה? אלא ודאי הכוונה היא לימי חול המועד, ומדוייק כדברי ר' זירא.","\u0003מי שהיה עבד או אשה או קטן מקרין אותו\u0004 (מקריאין לפניו את נוסח ההלל) והוא \u0003עונה אחריהן מה שהן אומרין\u0004 מלה במלה. ומעירים: \u0003ותבא לו מאירה\u0004 (קללה), שהוא בור ועם הארץ הנזקק לכך. \u0003אם היה גדול מקרא אותו —\u0004 אינו צריך לחזור אחריו, משום שהגדול מוציאו ידי חובתו באמירתו, אלא \u0003עונה אחריו \"הללויה\"\u0004 על כל דבר שהוא אומר. ומעירים: \u0003מקום שנהגו לכפול\u0004 פסוקים מסויימים ולאומרם פעמיים — \u0003יכפול,\u0004 ואם נהגו \u0003לפשוט,\u0004 כלומר: לאומרם כמות שהם — \u0003יפשוט,\u0004 מקום שנהגו \u0003לברך\u0004 לפני אמירת ההלל — \u0003יברך, והכל כמנהג המדינה\u0004 בענין זה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003באמת אמרו בן מברך לאביו\u0004 ברכת המזון, שכיון שהוא חייב בה מדברי סופרים, יכול לברך גם עבור אביו. \u0003ו\u0004כן \u0003עבד\u0004 כנעני \u0003מברך לרבו\u0004 (אדוניו), \u0003ואשה מברכת לבעלה, אבל אמרו חכמים: תבא מאירה\u0004 (קללה) \u0003לאדם\u0004 שנזקק לכך \u0003שאשתו ובניו מברכין לו\u0004 והוא עצמו אינו יודע.","\u0003אמר רבא:\u0004"],["\u0003הלכתא גיברתא איכא למשמע ממנהגא דהלילא\u0004 \u0005[הלכות גדולות אפשר ללמוד ממנהג ההלל]\u0006 כפי שהיו נוהגים לקרותו. שבמנהג זה רמוזים כמה וכמה ענייני הלכה ומנהגים שתיקנו בהלל לצורך השעה, ואף שעכשיו אין צורך בכל אלה, שרבו יודעי קרוא וכתוב, והכל יודעים לקרוא נוסח ההלל, מכל מקום נשמרו ומתקיימים עדיין מנהגים עתיקים הללו. ואלו הם, \u0003הוא\u0004 החזן \u0003אומר: \"הללויה\"\u0004 (תהלים קיב, א), \u0003והן\u0004 שאר המתפללים \u0003אומרים: \"הללויה\" — מכאן\u0004 למדנו \u0003שמצוה לענות \"הללויה\".\u0004","\u0003הוא\u0004 החזן \u0003אומר: \"הללו עבדי ה'\"\u0004 (תהלים קיב, א), \u0003והן אומרין \"הללויה\" — מכאן\u0004 רואים מה שלמדנו במשנתנו: \u0003שאם היה\u0004 ה\u0003גדול מקרא אותו — עונה אחריו \"הללויה\". הוא אומר: \"הודו לה'\"\u0004 (תהלים קיח, א) \u0003והן\u0004 עונין אחריו: \u0003\"הודו לה'\" — מכאן שמצוה לענות\u0004 על כל פנים ב\u0003ראשי הפרקים,\u0004 כלומר: באותם הדברים עצמם, ולא באמירת \"הללויה\". \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר רב חנן בר רבא: מצוה לענות ראשי פרקים.\u0004","ועוד אמר רבא: המנהג כי \u0003הוא\u0004 החזן \u0003אומר: \"אנא ה' הושיעה נא\"\u0004 (תהלים קיח, כה) \u0003והן אומרים\u0004 וחוזרים: \u0003\"אנא ה' הושיעה נא\"\u0004 (תהלים קיח, כה) — \u0003מכאן\u0004 רמז למה ששנינו \u0003שאם היה קטן מקרא אותו\u0004 דבר שאינו מראשי הפרקים — \u0003עונין אחריו\u0004 בדיוק \u0003מה שהוא אומר.\u0004","\u0003הוא אומר: \"אנא ה' הצליחה נא\" והן\u0004 חוזרים ו\u0003אומרים: \"אנא ה' הצליחה נא\" — מכאן\u0004 רמז להלכה \u0003שאם\u0004 רוצה ו\u0003בא לכפול\u0004 פסוק מסויים בהלל — \u0003כופל. הוא\u0004 החזן \u0003אומר: \"ברוך הבא\"\u0004 (תהלים קיח, כו) \u0003והן אומרים\u0004 את המשך הפסוק: \u0003\"בשם ה'\"\u0004 (תהלים קיח, כו) — \u0003מכאן לשומע כעונה,\u0004 שהרי אין העונים צריכים לחזור על הפסוק כולו, וכיון ששמעוהו מפי החזן הרי זה כאילו אמרוהו הם עצמם.","באותו נושא \u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003ר' חייא בר אבא: שמע ולא ענה מהו,\u0004 היוצא הוא ידי חובתו בכך? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003חכימיא וספריא ורישי עמא ודרשיא\u0004 \u0005[החכמים ומלמדי התינוקות וראשי העם והדרשנים]\u0006 \u0003אמרו: שמע ולא ענה — יצא\u0004 ידי חובה.","\u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003אמר ר' שמעון בן פזי אמר ר' יהושע בן לוי משום בר קפרא: מנין לשומע\u0004 שהוא \u0003כעונה\u0004 וכאילו הוא עצמו אומר את הדברים — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"את הדברים אשר קרא יאשיהו\u0004 את כל דברי הספר אשר קרא מלך יהודה\u0003\"\u0004 (מלכים ב' כב, טז), \u0003וכי יאשיהו\u0004 עצמו \u0003קראן? והלא שפן קראן, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ויקראהו שפן לפני המלך\"\u0004 (מלכים ב' כב, י)! \u0003אלא מכאן לשומע כעונה,\u0004 וכאילו יאשיהו בעצמו קרא את הדברים. ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003בתר דקראנהו\u0004","\u0005[אחר שקרא אותם]\u0006 \u0003שפן\u0004 חזר ו\u0003קרא\u0004 אותם \u0003יאשיהו? אמר רב אחא בר יעקב: לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"יען רך לבבך ותכנע לפני ה' בשמעך\"\u0004 (מלכים ב' כב, יט), ונדייק בלשון: נאמר \u0003\"בשמעך\" ולא \"בקראך\",\u0004 כלומר: שמיד כששמע את הדבר שלח לחולדה הנביאה, לפני שקראו בעצמו, הרי ששומע כעונה.","כיון שאמר רבא כמה הלכות בהלל הוסיף ו\u0003אמר רבא: לא לימא איניש\u0004 \u0005[יאמר אדם]\u0006 \u0003\"ברוך הבא\" והדר\u0004 \u0005[ואחר כך]\u0006 יפסיק משהו ויאמר \u0003\"בשם ה'\", אלא\u0004 יאמר \u0003\"ברוך הבא בשם ה'\"\u0004 (תהלים קיח, כו) \u0003בהדדי\u0004 \u0005[ביחד]\u0006 ובלא כל הפסקה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא\u0004 לרבא:"],["\u0003משה\u0004 כלומר, אדם גדול כמוך שהוא כמשה בדורו, \u0003שפיר קאמרת\u0004 \u0005[\u0006וכי \u0005יפה אמרת]?!\u0006 אין הדבר כן, \u0003אלא התם והכא\u0004 \u0005[שם וכאן]\u0006 בכל אופן שעושה \u0003אסוקי מילתא היא ולית לן בה\u0004 \u0005[גמר הדבר הוא ואין לנו בו]\u0006 כל חשש גם אם מפסיק מעט, שהרי ברורה כוונתו לומר \"ברוך הבא בשם ה'\". בדומה לזה \u0003אמר רבא: לא לימא איניש\u0004 \u0005[יאמר אדם]\u0006 בנוסח הקדיש \u0003\"יהא שמיה רבא\" והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"מברך\" אלא\u0004 יאמר \u0003\"יהא שמיה רבא מברך\" בהדדי\u0004 \u0005[יחד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא\u0004 לרבא: \u0003משה, שפיר קאמרת\u0004 \u0005[\u0006וכי \u0005יפה אמרת]?!\u0006 אין הדבר כן \u0003אלא, התם והכא אסוקי מילתא היא ולית לן בה\u0004 \u0005[שם וכאן גמר הדבר הוא ואין לנו בו\u0006 כל חשש\u0005].\u0006","שנינו במשנה בענין מנהגי אמירת ההלל, ש\u0003במקום שנהגו לכפול\u0004 — כופל. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003רבי\u0004 היה \u0003כופל בה דברים\u0004 באמירת ההלל. \u0003ר' אלעזר בן פרטא\u0004 היה \u0003מוסיף בה דברים.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מוסיף? אמר אביי:\u0004 היה \u0003מוסיף לכפול מ\"אודך\"\u0004 (תהלים קיח, כא) \u0003ולמטה,\u0004 שהיה כופל כל הפסוקים עד סוף הפרק כדרך שנוהגים אנחנו.","עוד שנינו במשנה: מקום שנהגו \u0003לברך\u0004 על אמירת ההלל — \u0003יברך. אמר אביי: לא שנו\u0004 חילוק מנהגים זה \u0003אלא לאחריו, אבל לפניו —\u0004 בודאי \u0003מצוה לברך.\u0004 ש\u0003אמר רב יהודה אמר שמואל: כל המצות כולן, מברך עליהן עובר\u0004 \u0005[קודם]\u0006 \u0003לעשייתן.\u0004 אגב הלכה זו שואלים על לשונה: \u0003ומאי משמע\u0004 \u0005[ומהיכן שומעים אנו]\u0006 \u0003דהאי\u0004 \u0005[ש\u0006ביטוי \u0005זה]\u0006 \u0003\"עובר\", לישנא דאקדומי\u0004 \u0005[לשון הקדמה]\u0006 \u0003הוא?\u0004 ש\u0003אמר רב נחמן בר יצחק; דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וירץ אחימעץ דרך הככר ויעבר את הכושי\"\u0004 (שמואל ב' יח, כג), כלומר: הקדים אותו. \u0003אביי אמר: מהכא\u0004 \u0005[מכאן]\u0006 למדים זאת, שנאמר: \u0003\"והוא עבר לפניהם\"\u0004 (בראשית לג, ג). \u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור\u0006 כי \u0005מכאן]\u0006 למדים, שנאמר: \u0003\"ויעבר מלכם לפניהם וה' בראשם\"\u0004 (מיכה ב, יג), שבכל המקראות הללו \"עובר\" משמעו עובר ומקדים.","חבר \u0003הלוקח\u0004 (הקונה) \u0003לולב מחבירו\u0004 עם הארץ \u0003בשביעית\u0004 (בשנת השמיטה) — \u0003נותן לו\u0004 המוכר אגב כך \u0003אתרוג במתנה, לפי שאין רשאי ללוקחו\u0004 (לקנותו) \u0003בשביעית,\u0004 שהרי אסור לעשות מסחר בפירות בשנת השמיטה.","שואלים: אם על אף בקשתו \u0003לא רצה\u0004 המוכר \u0003ליתן לו\u0004 אתרוג \u0003במתנה מהו?\u0004 מה הדין, מה יעשה הקונה? \u0003אמר רב הונא: מבליע ליה\u0004 \u0005[לו]\u0006 את \u0003דמי\u0004 ה\u0003אתרוג בלולב.\u0004 כלומר: יקנה ממנו את הלולב ביוקר עד שבמחיר הלולב יכלל גם מחירו של האתרוג. ושואלים: אם כן \u0003וליתיב ליה בהדיא\u0004 \u0005[ושיתן לו במישרין]\u0006 ומה לו להערים באופן זה?","ומשיבים: \u0003לפי שאין מוסרין דמי פירות שביעית לעם הארץ,\u0004 שמא לא ינהג בהם בכל דיני קדושת שביעית כראוי להם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מוסרין דמי פרות שביעית לעם הארץ יותר מ\u0004כדי מחיר \u0003מזון שלש סעודות,\u0004 שאז יש להניח שיאכל מיד מזון כנגד כסף זה. \u0003ואם מסר\u0004 יותר, \u0003יאמר: הרי מעות הללו\u0004 שמסרתי \u0003יהו\u0004 (יהיו) \u0003מחוללין על פרות\u0004 סתם, שאינם של שביעית \u0003שיש לי בתוך ביתי\u0004"],["\u0003ובא\u0004 בעל הפירות \u0003ואוכלן בקדושת שביעית —\u0004 באופן ובזמן שבו מותר לאכול פירות שביעית.","ומוסיפים שם: \u0003במה דברים אמורים\u0004 שמוסרים דמי פירות שביעית כדי מזון שלוש סעודות לעם הארץ — זהו דווקא \u0003בלוקח\u0004 (בקונה) \u0003מן\u0004 השדה \u0003המופקר\u0004 שעם הארץ ליקט משדה שידוע שהופקר כדינו בשביעית, ושכרו הוא איפוא שכר לקיטה בלבד. \u0003אבל בלוקח מן\u0004 השדה \u0003המשומר\u0004 שלא הופקר אלא היה שמור על ידי בעליו (באמצעות גדר ופתח נעול) כבכל שנה, \u0003אפילו\u0004 קנה ממנו \u0003בכחצי איסר\u0004 (מטבע קטנה) — \u0003אסור\u0004 לתת לו, שאין להשתמש בפירות שנשמרו בשביעית.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב ששת: ומן המופקר\u0004 מותר לקנות רק כדי מזון \u0003שלש סעודות ותו לא\u0004 \u0005[ולא עוד]?\u0006 \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה במסכת שביעית: \u0003הפיגם והירבוזין\u0004 שהם מיני עשבים ומיני הירק, כגון \u0003השיטים וחלגלוגות והכוסבר ש\u0004צומח \u0003בהרים, והכרפס ש\u0004צומח \u0003בנהרות, והגרגיר של אפר\u0004 (שדה) כל אלה — \u0003פטורין מן המעשר\u0004 בכל השנים, \u0003וניקחין\u0004 (נקנים) \u0003מכל אדם בשביעית, לפי שאין כיוצא בהן נשמר.\u0004 משום שצמחים אלה אינם גידולי תרבות, כרגיל, ומן הסתם גדלים בר במקומותיהם ואינם אלא הפקר. ועל כל פנים למדנו שצמחים הגדלים בר מותר לקנות אף מעם הארץ בכל כמות ואין הגבלה דווקא לכדי מזון שלוש סעודות!","וממשיכים: \u0003הוא\u0004 רב ששת \u0003מותיב\u0004 \u0005[היה מקשה]\u0006 \u0003לה\u0004 קושיה זו \u0003והוא\u0004 גם \u0003מפרק לה\u0004 \u0005[פתר אותה]\u0006 והיה אומר: \u0003בכדי מן\u0004 \u0005[מזון]\u0006 \u0003שנו,\u0004 כלומר: אכן, מה שהתירו לקנות פירות מצמחי בר, הריהו בכשיעור מזונו של אדם שהוא כאמור כדי מזון שלוש סעודות ולא יותר. \u0003וכן אמר רבה בר בר חנה אמר ר' יוחנן: בכדי מן\u0004 \u0005[מזון]\u0006 \u0003שנו\u0004 ולא יותר. ומעירים: \u0003מאי משמע דהאי \"מן\" לישנא דמזוני\u0004 \u0005[מה משמעות,\u0006 מהיכן נובע \u0005ש\"מן\" זה לשון מזון]\u0006 \u0003הוא\u0004 — שנאמר: \u0003\"וימן להם המלך\u0004 דבר יום ביומו מפת-בג המלך ומיין משתיו\".","לעיקר ההלכה שואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאסור לתת לעם הארץ דמי שביעית שמא לא ישתמש בהם כראוי להם, דמי \u0003לולב\u0004 הנקנה ממנו בשביעית \u0003נמי\u0004 \u0005[גם כן]\u0006 יהא אסור לתת לו! ומשיבים: ב\u0003לולב בר\u0004 \u0005[בן]\u0006 השנה ה\u0003ששית הנכנס לשביעית הוא\u0004 שמדובר כאן, שהרי גדל בשנה השישית המותרת, ואף אם נקצץ בשנה השביעית, הרי בשל הימים המעטים שמראש השנה עד סוכות אינו נחשב כשייך לשנה השביעית. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אתרוג נמי\u0004 \u0005[גם כן]\u0006 יש לומר ש\u0003בת ששית הנכנס לשביעית היא\u0004 ואף אתרוג יהיה מותר! ומשיבים: לגבי \u0003אתרוג,\u0004 בניגוד לשאר פירות האילן, \u0003בתר\u0004 \u0005[אחר]\u0006 זמן ה\u0003לקיטה אזלינן\u0004 \u0005[הולכים אנו]\u0006 ולא אחר הזמן שבו גדל בפועל, שהשנה בה נלקט היא הנחשבת לענין שביעית.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בין רבן גמליאל ובין ר' אליעזר\u0004 שנחלקו בדינו של אתרוג לענין מעשר, כבן איזו שנה יש להחשיבו אחר שגדל בשנה אחת ונלקט בשלאחריה, אבל \u0003לענין שביעית\u0004 מסכימים שניהם כי \u0003אתרוג בתר\u0004 \u0005[אחר]\u0006 \u0003חנטה\u0004 שהיא יצירת צורת הפרי \u0003אזלינן\u0004 \u0005[הולכים אנו]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אתרוג שוה לאילן\u0004 סתם \u0003בשלש דרכים, ולירק\u0004 שוה \u0003בדרך אחד.\u0004","ומפרטים: \u0003שוה לאילן בשלשה דרכים: ל\u0004ענין \u0003ערלה,\u0004 שאסור לאכול מפירותיו בשלוש שנים ראשונות כאילן, ו\u0003ל\u0004ענין נטע \u0003רבעי\u0004 שאסור להשתמש בפירותיו בשנה הרביעית בלא חילול כשאר אילן, ולענין השנה ה\u0003שביעית\u0004 שנת השמיטה, שהולכים לאחר זמן חניטת הפרי כמו באילן. \u0003ולירק\u0004 שוה האתרוג \u0003בדרך אחד:\u0004"],["\u0003שבשעת לקיטתו עישורו,\u0004 כלומר: נוהגים בו לענין מעשר כדין השנה שבה נלקט, ולמשל אם נלקט בשנה השניה לשמיטה — מפרישים ממנו מעשר שני — אף שגמר הפרי היה בשנה שעברה, אלו \u0003דברי רבן גמליאל. ר' אליעזר אומר: אתרוג שוה לאילן לכל דבר.\u0004 ומכל מקום לענייננו משמע שלענין שביעית, אתרוג של השנה השישית שנקטף בשביעית דנים אותו כבן השישית!","ומשיבים: \u0003הוא\u0004 ש\u0003אמר\u0004 את דבריו \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה];\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יוסי:\u0004 החכם \u0003אבטולמוס העיד משום חמשה זקנים: אתרוג\u0004 הולך \u0003אחר\u0004 זמן ה\u0003לקיטה למעשר, ורבותינו נמנו\u0004 (הצביעו והחליטו) על כך \u0003באושא ואמרו\u0004 שאתרוג הולך אחר לקיטה \u0003בין למעשר בין לשביעית.\u0004","על לשון הברייתא תוהים: \u0003שביעית מאן דכר שמיה\u0004 \u0005[מי הזכיר את שמה]\u0006 קודם, שמוסיפים ואומרים כי רבותינו נמנו בענין שביעית? ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך יש לשנותה]:\u0006 \u0003אתרוג — אחר לקיטה למעשר, ואחר חנטה לשביעית. ורבותינו נמנו באושא ואמרו: אתרוג בתר\u0004 \u0005[אחר]\u0006 \u0003לקיטה, בין למעשר בין לשביעית.\u0004","שוב חוזרים אנו ודנים בהלכה שבמשנה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא מפני ש\u0003לולב בר\u0004 \u0005[בן]\u0006 השנה \u0003הששית הנכנס לשביעית הוא, הא\u0004 \u0005[הרי]\u0006 אם היה זה לולב של השנה ה\u0003שביעית\u0004 — \u0003קדוש\u0004 הוא בקדושת שמיטה, \u0003אמאי\u0004 \u0005[ומדוע]?\u0006 והלא \u0003עצים בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא ועצים אין בהן משום קדושת שביעית\u0004 כלל! \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עלי קנים, ועלי גפנים שגבבן\u0004 \u0005[שכנסם]\u0006 \u0003לחובה\u0004 (למקום מחבוא) \u0003על פני השדה,\u0004 אם \u0003לקטן ל\u0004צורך \u0003אכילה\u0004 (למאכל בהמה) — \u0003יש בהן משום קדושת שביעית,\u0004 ואם \u0003לקטן לעצים,\u0004 כגון להסיק בהם — \u0003אין בהן משום קדושת שביעית.\u0004 הרי שעצים וכל שאינו משמש לאכילה אין בו קדושת שביעית!","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בעלים אלה שלקטם לעצים \u0003דאמר קרא\u0004 \u0005[ש\u0006כן \u0005אמר הכתוב]:\u0006 \u0003\"\u0004והיתה שבת הארץ \u0003לכם לאכלה\"\u0004 (ויקרא כה, ו). \u0003\"לכם\"\u0004 שאמר \u0003דומיא\u0004 \u0005[בדומה]\u0006 למה שאמר \u0003\"לאכלה\".\u0004 לומר לנו: על מה חלה קדושת שביעית — על \u0003מי שהנאתו וביעורו שוה.\u0004 דבר שבשעה שנהנים ממנו, הרי יחד עם הנאה זו הריהו מתבער מן העולם, כגון דברים העשויים לסיכה, לאכילה, או להדלקת הנר, \u0003יצאו עצים שהנאתן אחר ביעורן.\u0004 שהרי עצי הסקה שאופים ומסיקים בהם עיקר שימושם בגחליהם או בתנור שהתחמם כתוצאה משריפתם, ואלה מצויים לאחר שנתבער כבר העץ עצמו. ומטעם זה אין קדושת שביעית חלה עליהם.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003עצים דמשחן\u0004 \u0005[עצים של שמן]\u0006 העשויים למאור, שבשעה שהם בוערים הם משמשים כאבוקות ונמצא ש\u0003הנאתן וביעורן שוה! אמר רבא\u0004 מכל מקום \u0003סתם עצים\u0004 של היסק, \u0003להסקה הן עומדין\u0004 והנאתם לאחר ביעורם.","ומעירים: ועצם ההלכה בדבר קדושת שביעית של \u0003עצים להסקה\u0004 שהנאתן לאחר ביעורן, \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מוסרין פירות שביעית\u0004 כגון יין \u0003לא למשרה\u0004 (לשרות בהם פשתן כדי להכשירו לטויה) שההנאה מן הפשתן הוא לאחר שרייתו \u0003ולא לכבוסה\u0004 (לכבס) בהם, ואף בזה עיקר ההנאה היא בלבישת הבגדים הבאה לאחר הכביסה. ושריית הפשתן והכביסה ביין הם עצמם נחשבים כביעור לאותו יין, שעל ידי הכנסת הפשתן או הבגדים המלוכלכים ליין, בכך הוא נפסל. \u0003ר' יוסי אומר: מוסרין.\u0004","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003תנא קמא\u0004 \u0005[התנא הראשון]?\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 על פירות שביעית: \u0003\"לאכלה\",\u0004 ומשמע דווקא לצורך זה נתנו פירות שביעית \u0003ולא למשרה, ולא לכבוסה. מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוסי\u0004 המתיר? \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לכם\"\u0004 והוא למד מכאן \u0003\"לכם\" — לכל צרכיכם, ואפילו למשרה ולכבוסה.\u0004 ושואלים: \u0003ותנא קמא\u0004 \u0005[והתנא הראשון],\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"לכם\"\u0004 וכיצד מפרש הוא מלה זו? ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003\"לכם\"\u0004 שנאמר, \u0003דומיא\u0004 \u0005[בדומה]\u0006 למה שנאמר \u0003\"לאכלה\",\u0004 כלומר: מותר להשתמש בפירות שביעית לצורך אדם, אבל שימוש זה מוגבל דווקא ל\u0003מי שהנאתו וביעורו שוה, יצאו משרה וכבוסה שהנאתן אחר ביעורן.\u0004","ושואלים: \u0003ור' יוסי,\u0004 מה משיב הוא על כך, \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"לאכלה\"\u0004 ומשמע שלא לצורך אחר! ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו]\u0006 ללמדנו: \u0003\"לאכלה\" ולא למלוגמא\u0004 \u0005[לרפואה].\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"לאכלה\"\u0004 משמעו \u0003ולא למלוגמא, אתה אומר\u0004 כי \u0003\"לאכלה\"\u0004 בא ללמד \u0003ולא למלוגמא, או אינו\u0004 בא ללמד \u0003אלא ולא לכבוסה? כשהוא אומר \"לכם\" — הרי לכבוסה אמור,\u0004 ש\"לכם\" משמעו לצורך גופכם ולא לכל דבר אחר, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 במה שנאמר \u0003\"לאכלה\"\u0004 — \u0003לאכלה ולא למלוגמא.\u0004 ואם תאמר כי \u0003מה ראית לרבות את הכבוסה\u0004 בכלל השימושים המותרים בשביעית \u0003ולהוציא את המלוגמא\u0004 —"],["\u0003מרבה אני את הכבוסה ששוה בכל אדם\u0004 שהרי הכל נזקקין לה, \u0003ומוציא את המלוגמא\u0004 \u0005[הרפואה]\u0006 \u0003שאינה שוה לכל אדם\u0004 אלא לחולים בלבד.","ומעירים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי\u0006 הוא \u0005התנא ששנה\u0006 ברייתא \u0005זו ששנו חכמים]\u0006 בענין פירות שביעית: \u0003\"לאכלה\"\u0004 (ויקרא כה, ו) — \u0003ולא למלוגמא, \"לאכלה\" — ולא לזילוף,\u0004 כלומר: להתיז יין בתוך הבית לריח טוב, \u0003\"לאכלה\" — ולא לעשות ממנה אפיקטויזין\u0004 (סם הקאה), \u0003כמאן\u0004 \u0005[כמי\u0006 היא\u0005] —\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי. דאי רבנן\u0004 \u0005[שאם\u0006 תאמר שהיא כדעת \u0005חכמים]\u0006 \u0003הא איכא נמי\u0004 \u0005[הרי יש גם כן]\u0006 \u0003משרה וכבוסה,\u0004 שלדעתם אסור להשתמש בפירות שביעית לצורך זה.","\u0003אמר ר' אלעזר: אין שביעית מתחללת אלא דרך מקח.\u0004 שקדושת פירות שביעית אינה חלה על דמיהם, אלא אם כן חיללם בדרך מקח וממכר, וכגון שמכרן לחבירו וקיבל כסף תמורתן. אבל חילול כדרך שמחללים הקדש, וכגון שנוטל מעות ואומר שתהא קדושת החפץ מחוללת על המעות הללו והחפץ עצמו נותר בידו — אופן חילול זה אינו מועיל לענין שביעית. \u0003ר' יוחנן אמר: בין דרך מקח בין דרך חילול\u0004 (החלפה) מועילה לענין פירות שביעית.","ושואלים \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' אלעזר? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בשנת היובל הזאת\"\u0004 (ויקרא כה, יג) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 נאמר: \u0003\"וכי תמכרו ממכר\"\u0004 (ויקרא כה, יד), ומהשוואה זו הוא למד שגם בשנת היובל (וקדושת פירות שווה בשביעית וביובל) אין החלפה אלא \u0003דרך מקח, ולא דרך חילול.\u0004 ושואלים: \u0003ור' יוחנן מאי טעמיה\u0004 \u0005[מה טעמו]?\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי יובל היא קדש\u0004 תהיה לכם\u0003\"\u0004 (ויקרא כה, יב) ומכאן למדים: \u0003מה קדש\u0004 יכולים להמיר את קדושתו \u0003בין דרך מקח, בין דרך חילול, אף שביעית\u0004 שקדושת פירותיה כקדושת פירות היובל — \u0003בין דרך מקח בין דרך חילול.\u0004","ושואלים: \u0003ור' יוחנן האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"וכי תמכרו ממכר\", מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו],\u0006 מה לומד הוא ממנו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך\u0006 הוא \u0005לו]\u0006 לכפי שאמר \u0003ר' יוסי בר חנינא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי בר חנינא: בוא וראה כמה קשה אבקה של שביעית,\u0004 שאף איסור סחורה שאינו מן האיסורים העיקריים בשביעית כמה חמור עונשו. \u0003אדם\u0004 עובר עבירה, \u0003נושא ונותן בפירות שביעית — לסוף,\u0004 כעונש, הוא יורד מנכסיו עד אשר \u0003מוכר את מטלטליו ואת כליו, שנאמר: \"בשנת היובל הזאת תשבו איש אל אחזתו\"\u0004 (ויקרא כה, יג) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הכתוב: \u0003\"וכי תמכרו ממכר לעמיתך\".\u0004","ושואלים עוד: \u0003ור' אלעזר, האי קרא\u0004 \u0005[כתוב זה]\u0006 ש\u0003ר' יוחנן\u0004 משתמש בו \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[זקוק\u0006 הוא \u0005לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר: \u0003\"כי יובל היא קדש\u0004 תהיה לכם\u0003\"\u0004 (ויקרא כה, יב), בא ללמד: \u0003מה קדש תופס את דמיו,\u0004 שכאשר פודים דבר מוקדש חלה אותה קדושה על הדמים, הכסף, שבו פדו או קנו אותו, והוא עצמו יוצא לחולין — \u0003אף שביעית תופסת את דמיה\u0004 שקדושת שביעית חלה על הדבר הקנוי והפירות עצמם יוצאים לחולין.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אלעזר ותניא כוותיה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן.\u0004 ומפרטים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אלעזר;\u0004 ששנינו: \u0003שביעית תופסת את דמיה,\u0004 שעל ידי חילול מתקדשים הם בקדושת שביעית, \u0003שנאמר: \"כי יובל היא קדש תהיה לכם\"\u0004 (ויקרא כה, יב), \u0003מה קדש\u0004 שחיללו על מעות, הריהו \u0003תופס את דמיו ואסור\u0004 להשתמש לחולין במה שקנה בדמי הקודש — \u0003אף שביעית תופסת את דמיה ואסורה.\u0004","\u0003אי\u0004 \u0005[או]\u0006 \u0003מה\u0004 הדין בדבר \u0003קדש תפס\u0004 את \u0003דמיו\u0004 שהם נעשים כהקדש והוא עצמו \u0003יוצא לחולין\u0004 על ידי כך, \u0003אף שביעית\u0004 תהא \u0003תופסת את דמיה\u0004 וייעשו הם קדושים בקדושתה ואילו היא עצמה \u0003יוצאת\u0004 על ידי כך \u0003לחולין — תלמוד לומר: \"תהיה\",\u0004 לומר: \u0003בהוייתה תהא,\u0004 שעל אף חלות קדושת שביעית על המעות המתקבלים מן המכירה כתמורה לפירות, עדיין קדושת השביעית נשארת בפירות עצמם.","ומסבירים: \u0003הא כיצד? לקח\u0004 (קנה) \u0003בפירות שביעית בשר — אלו ואלו\u0004 גם הפירות וגם הבשר \u0003מתבערין בשביעית,\u0004 שצריך לנהוג אף בבשר כאילו היה פירות שביעית ולסיים אכילתו כל זמן שעדיין מותר לאכול פירות שביעית. אבל אם הוסיף ו\u0003לקח בבשר\u0004 שנקנה בדמי פירות שביעית \u0003דגים — יצא בשר\u0004 זה מקדושת שביעית \u0003ונכנסו דגים,\u0004 הוסיף ו\u0003לקח בדגים יין — יצאו דגים ונכנס יין, לקח ביין שמן — יצא יין ונכנס שמן.\u0004","\u0003הא כיצד\u0004 באופן כללי: \u0003אחרון אחרון נכנס\u0004 בקדושת \u0003שביעית, ופרי\u0004 של שביעית \u0003עצמו\u0004 נשאר \u0003אסור\u0004 ואינו יוצא מקדושת שביעית. ומעירים: \u0003מדקתני\u0004 \u0005[\u0006ממה \u0005ששנה]\u0006 באותה ברייתא לשון \u0003\"לקח\" \"לקח\"\u0004 (\"לקח בשר\" ו\"לקח בבשר דגים\" וכו') \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003דרך מקח — אין\u0004 \u0005[כן]\u0006 גורמת לחילול קדושת שביעית, אולם \u0003דרך חילול\u0004 בלבד — \u0003לא.\u0004","וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן.\u0004 וכך שנינו בה: \u0003אחד שביעית ואחד מעשר שני מתחללין על בהמה חיה ועוף, בין\u0004 היו אלה \u0003חיין בין\u0004 היו \u0003שחוטין,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: על שחוטין — מתחללין, על חיין — אין מתחללין.\u0004 והטעם הוא: \u0003גזירה שמא יגדל מהן עדרים,\u0004 כלומר: שמא לא ישחטו בהמות אלה שיש בהן קדושת מעשר ויתרבו עד שיהיה עדר שלם ועשויות להגרם בעיות חמורות כתוצאה מהשימוש בהן, שהרי קדושות הן בקדושת מעשר.","\u0003אמר רבא: מחלוקת\u0004 זו בין ר' מאיר וחכמים, היא דווקא"],["\u0003בזכרים\u0004 שאין יולדים ולדות \u0003אבל בנקבות — דברי הכל: על שחוטין — מתחללין, על חיין — אין מתחללין, גזרה שמא יגדל מהן עדרים,\u0004 שהרי מן הסתם יולדות ולדות. ואילו בזכרים לא אסרו אלא משום גזירה. ומתוך הלשון \"מתחללין\" האמור כמה פעמים בברייתא זו, למדנו איפוא שיש דין חילול בשביעית.","\u0003אמר רב אשי: מחלוקת\u0004 זו בפירות שביעית אם מתחללים או נמכרים היא רק \u0003בפרי ראשון\u0004 כלומר, בפירות השביעית עצמם, \u0003אבל בפרי שני\u0004 שהוא כל מה שנקנה בדמי שביעית — \u0003דברי הכל: בין דרך מקח בין דרך חילול. והא דקתני\u0004 \u0005[ומה ששנינו]\u0006 בברייתא המסייעת לשיטת ר' אלעזר לשון \u0003\"לקח\" \"לקח\"\u0004 החוזרת על עצמה כמה פעמים גם מהפרי השני והלאה ולא הזכיר לשון חילול, אינו מוכיח שזו הדרך היחידה, אלא \u0003איידי דתנא רישא\u0004 \u0005[על ידי ששנה בתחילה]\u0006 לשון \u0003\"לקח\" תנא נמי סיפא\u0004 \u0005[שנה גם כן בסוף]\u0006 לשון \u0003\"לקח\",\u0004 ואין זו אלא גרירת הלשון.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרב אשי:\u0004 שנינו, \u0003מי שיש לו סלע\u0004 (מטבע) \u0003של שביעית וביקש ליקח\u0004 (לקנות) \u0003בו חלוק,\u0004 ומאחר והתורה התירה רק \"לאכלה\" ולא לסחורה, אם כן \u0003כיצד יעשה? ילך אצל חנוני\u0004 שהוא \u0003רגיל אצלו\u0004 שבודאי יעשה כרצונו, \u0003ואומר לו: תן לי בסלע\u0004 זה \u0003פירות, ונותן לו\u0004 החנווני פירות, \u0003וחוזר ואומר לו\u0004 לחנווני: \u0003הרי פירות הללו\u0004 שמכרת לי ונעשו בשל כך קדושים בקדושת שביעית \u0003נתונים לך במתנה,\u0004 ומשקבלם החנווני הרי הם שלו ואוכלם בשביעית. \u0003והוא\u0004 החנוני \u0003אומר לו: הא לך סלע זו\u0004 שיצאה לחולין \u0003במתנה, והלה לוקח בהן מה שירצה,\u0004 שהרי הם חולין ויכול לקנות בהם כאוות נפשו. ומדייק רבינא: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003פרי שני הוא,\u0004 שהרי סלע זה הוא דבר מחילופי שביעית, \u0003וקתני\u0004 \u0005[ושנינו]\u0006 בכל זאת בלשון המורה כי אם היה זה ב\u0003דרך מקח\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אולם ב\u0003דרך חילול\u0004 — \u0003לא!\u0004","\u0003אלא אמר רב אשי:\u0004 יש לחזור ממה שאמרנו, ו\u0003מחלוקת\u0004 זו היא דוקא \u0003בפרי שני, אבל בפרי ראשון — דברי הכל דרך מקח\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 \u0003דרך חילול\u0004 — \u0003לא. והא דקתני\u0004 \u0005[וזה ששנינו]\u0006 בברייתא המסייעת לשיטת ר' יוחנן \u0003אחד שביעית ואחד מעשר שני\u0004 מתחללים, והרי שאף לענין פירות שביעית די בחילול — \u0003מאי\u0004\u0005 [מה פירוש]\u0006 \u0003שביעית — דמי שביעית\u0004 ולא פירות, אבל בפירות שביעית אכן אין די בחילול. וכן הכוונה גם למעשר האמור בברייתא זו.","\u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר\u0006 ותפרש \u0005כך]\u0006 אלא תאמר ש\u0003מעשר\u0004 האמור שם \u0003מעשר ממש\u0004 בעצמו הוא? \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 במעשר שני: \"ונתתה בכסף \u0003וצרת הכסף בידך...\u0004 והלכת אל המקום אשר יבחר ה' אלהיך בו ונתתה הכסף בכל אשר תאוה נפשך בבקר ובצאן וביין ובשכר ובכל אשר תשאלך נפשך\" (דברים יד, כה — כו), לומר שאין מחללים מעשר שני אלא על כסף בלבד, ובאותו כסף ניתן לקנות דברים אחרים. \u0003אלא\u0004 בהכרח יש לומר שהכוונה היא ל\u0003דמי מעשר\u0004 שני — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר ב\u0003דמי שביעית,\u0004 ולא בפירות שביעית עצמם.","\u0003בראשונה\u0004 בזמן הבית \u0003היה לולב ניטל במקדש\u0004 בלבד \u0003שבעה\u0004 ימים, \u0003ובמדינה\u0004 חוץ למקדש רק \u0003יום אחד. משחרב בית המקדש, התקין רבן יוחנן בן זכאי שיהא לולב ניטל במדינה שבעה\u0004 ימים כדי לעשות \u0003זכר למקדש.\u0004","ומטעמים דומים התקין \u0003שיהא יום הנף\u0004 העומר, \u0003כולו אסור\u0004 באכילת תבואה חדשה. כי אסור לאכול מן התבואה החדשה עד שהוקרב והונף העומר, ויום הנפת העומר הוא יום ששה עשר בניסן. זמן הנפת העומר הוא בבוקר, אך כיון שהיה יכול לקרות שתתאחר ההקרבה, אסרו לאכול מן התבואה החדשה עד שיהא ברור שכבר הוקרב העומר ולמעשה היה איפוא יום הנף אסור, ומותרת התבואה החדשה רק מיום שבעה עשר. ולאחר שחרב הבית חזרה ההלכה לקדמותה, שמששה עשר בניסן מותר לאכול מן התבואה החדשה. ובכל זאת הנהיג רב יוחנן שימשיכו להחזיק באיסור של אכילת התבואה החדשה ביום ששה עשר. זכר למקדש.","שואלים: \u0003מנא לן דעבדינן\u0004 \u0005[מניין לנו שאנו עושים]\u0006 \u0003זכר למקדש? אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי אעלה ארכה לך וממכותיך ארפאך נאם ה' כי נדחה קראו לך ציון היא דרש אין לה\"\u0004 (ירמיה ל, יז) ומדברי תלונת הנביא \u0003\"דרש אין לה\", מכלל\u0004 הדברים אתה למד \u0003דבעיא\u0004 \u0005[ש\u0006היא \u0005צריכה]\u0006 \u0003דרישה\u0004 לאמור שיוסיפו לחשוב ולזכור אותה, וזה טעם תקנת רבן יוחנן.","שנינו במשנה שהנהיג רבן יוחנן \u0003שיהא יום הנף\u0004 כולו אסור. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? משום ש\u0003מהרה יבנה בית המקדש, ויאמרו\u0004 אנשים: \u0003אשתקד\u0004 \u0005[בשנה שעברה]\u0006 כשעדיין היה בית המקדש בחורבנו \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אכלנו\u0004 מיד \u0003בהאיר\u0004 ה\u0003מזרח,\u0004 שהרי התבואה החדשה היתה מותרת מיד שהאיר מזרח בבוקר יום ששה עשר, \u0003השתא נמי ניכול\u0004 \u0005[עכשיו גם כן נאכל]\u0006 משעה זו. \u0003ואינהו לא ידעי\u0004 \u0005[והם אינם יודעים]\u0006 \u0003דאשתקד דלא הוה\u0004 \u0005[בשנה שעברה שלא היה]\u0006 \u0003בית המקדש\u0004 בנוי, כיון ש\u0003האיר\u0004 ה\u0003מזרח\u0004 ביום ששה עשר, מיד \u0003התיר.\u0004 אולם \u0003השתא דאיכא\u0004 \u0005[עכשיו שיש]\u0006 \u0003בית המקדש\u0004 — ה\u0003עומר\u0004 הוא ש\u0003מתיר\u0004 וכל עוד לא הונף העומר, לא הותרה התבואה החדשה.","אגב כך שואלים בבירור הענין: \u0003דאיבני אימת\u0004 \u0005[שנבנה\u0006 בית המקדש \u0005מתי]?\u0006 \u0003אילימא דאיבני בשיתסר\u0004 \u0005[אם תאמר שנבנה בששה עשר]\u0006 בניסן עצמו, כיון שבבוקר יום הששה עשר עדיין לא עמד המקדש על מכונו, \u0003הרי התיר האיר מזרח,\u0004 שכיון שלא יכלו לקיים עדיין את מצות הנפת העומר ממילא הותר לאכול מן החדש מיד עם האיר היום. \u0003אלא דאיבני בחמיסר\u0004 \u0005[שנבנה בחמישה עשר]\u0006 בניסן או קודם, שבהאיר המזרח לא הותר לאכול מן החדש, אולם אז \u0003מחצות היום ולהלן תשתרי\u0004 \u0005[תותר]\u0006 אכילת חדש, \u0003דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006 במסכת מנחות: \u0003הרחוקים\u0004 מירושלים, מתוך שאינם יכולים לדעת את השעה המדוייקת בה הוקרב העומר, \u0003מותרין\u0004 לאכול את החדש \u0003מחצות היום ולהלן\u0004 (והלאה), \u0003לפי שאין בית דין מתעצלין בו\u0004 לאחר את הקרבתו יותר מחצות היום, ויכולים לסמוך שכבר הוקרב!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 \u0003דאיבני בליליא\u0004 \u0005[\u0006כגון \u0005שנבנה\u0006 בית המקדש \u0005בלילה]\u0006 ערב לששה עשר ולא הספיקו לקצור את העומר בלילה שלפניו \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 שנבנה ביום חמישה עשר \u0003סמוך לשקיעת החמה\u0004 וכיון שכן ברור הדבר שלא יספיקו לעשות את כל ההכנות הדרושות להקרבתו עד לחצות היום ולכן קבע ר' יוחנן שיהיה אסור יום הששה עשר כולו. \u0003רב נחמן בר יצחק אמר:\u0004 לא זה הטעם, אלא \u0003רבן יוחנן בן זכאי בשיטת ר' יהודה אמרה,\u0004 ש\u0003אמר: מן התורה הוא אסור\u0004 לאכול מן החדש עד יום שבעה עשר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006"],["\u0003\"ולחם וקלי וכרמל לא תאכלו עד עצם היום הזה\"\u0004 (ויקרא כג, יד), משמע \u0003עד עיצומו של יום,\u0004 וכל יום הששה עשר נקרא \"עיצומו של יום\", \u0003וקסבר\u0004 \u0005[וסבר]\u0006 שלשון \u0003\"עד\"\u0004 משמע: \u0003ועד בכלל\u0004 ומכאן שאף היום הזה, יום ששה עשר, אסור כולו באכילת תבואה מן החדש.","ושואלים: \u0003ומי סבר ליה כוותיה\u0004 \u0005[והאם סבר\u0006 רבן יוחנן \u0005כשיטתו\u0006 של ר' יהודה\u0005]?\u0006 \u0003והא מפליג פליג עליה\u0004 \u0005[והרי חולק הוא עליו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003משחרב בית המקדש התקין רבן יוחנן בן זכאי שיהא יום הנף כולו אסור. אמר לו ר' יהודה: הלא מן התורה הוא אסור, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עד עצם היום הזה\" — עד עיצומו של יום,\u0004 משמע שהן שתי דעות חלוקות!","ומשיבים: \u0003ר' יהודה הוא דקא טעי\u0004 \u0005[שטעה],\u0006 כי \u0003הוא סבר\u0004 שרבן יוחנן בן זכאי \u0003מדרבנן קאמר\u0004 \u0005[מדברי סופרים\u0006 הוא ש\u0005אמר]\u0006 וקבע תקנה זו. \u0003ולא היא,\u0004 כי אכן \u0003מדאורייתא קאמר\u0004 \u0005[מן התורה\u0006 הוא ש\u0005אמר]\u0006 שהוא אסור. ושואלים: איך תאמר שלדברי רבן יוחנן הוא אסור מן התורה, \u0003והא\u0004 \u0005[והרי]\u0006 לשון \u0003\"התקין\" אמר,\u0004 משמע שהיא תקנת סופרים בלבד! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"התקין\"\u0004 — \u0003דרש\u0004 את האמור בתורה \u0003והתקין\u0004 תקנה לרבים לנהוג כך.","\u0003יום טוב הראשון של חג שחל להיות בשבת, כל העם מוליכין את לולביהן לבית הכנסת\u0004 בערב שבת, שהרי אסור לטלטל ברשות הרבים בשבת. \u0003למחרת\u0004 בשבת היו \u0003משכימין ובאין, כל אחד ואחד מכיר את\u0004 לולבו \u0003שלו ונוטלו.\u0004 וההדגשה הזו ש\"כל אחד ואחד מכיר את שלו ונוטלו\" היא \u0003מפני שאמרו חכמים: אין אדם יוצא ידי חובתו ביום טוב הראשון\u0004 של חג \u0003בלולבו של חבירו.\u0004 אבל ב\u0003שאר ימות החג אדם יוצא ידי חובתו בלולבו של חבירו. ר' יוסי אומר: יום טוב הראשון של חג שחל להיות בשבת, ושכח והוציא את הלולב לרשות הרבים — פטור\u0004 מלהביא קרבן חטאת על שגגה זו \u0003מפני שהוציאו ברשות\u0004 כיון שהיה טרוד במצוה והוציאו בטעות. ולדעת ר' יוסי, אף ששגג בדבר שיש בו כרת, כיון שמקור טעותו הוא בטירדת מצוה — הריהו פטור מלהביא על כך קרבן.","\u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שאין אדם יוצא בלולבו של חבירו ביום טוב ראשון? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים];\u0006 נאמר: \u0003\"ולקחתם\u0004 לכם ביום הראשון פרי עץ הדר...\u0003\"\u0004 (ויקרא כג, מ), \"ולקחתם\" משמעו: \u0003שתהא לקיחה ביד כל אחד ואחד. \"לכם\"\u0004 משמעו: \u0003משלכם\u0004 — \u0003להוציא את\u0004 הלולב \u0003השאול ואת הגזול. מכאן אמרו חכמים: אין אדם יוצא ידי חובתו ביום טוב הראשון של חג בלולבו של חבירו אלא אם כן נתנו לו במתנה\u0004 ממש, שאז שוב אינו של חבירו אלא שלו.","\u0003ומעשה ברבן גמליאל ור' יהושע ור' אלעזר בן עזריה ור' עקיבא שהיו באין\u0004 (נוסעים) \u0003בספינה\u0004 בימי חג הסוכות, \u0003ולא היה לולב אלא לרבן גמליאל בלבד, שלקחו\u0004 (קנאו) \u0003באלף זוז. נטלו רבן גמליאל ויצא בו\u0004 ידי חובה, \u0003ונתנו לר' יהושע במתנה. נטלו ר' יהושע ויצא בו, ונתנו לר' אלעזר בן עזריה במתנה, נטלו ר' אלעזר בן עזריה ויצא בו ונתנו במתנה לר' עקיבא, נטלו ר' עקיבא ויצא בו והחזירו לרבן גמליאל.\u0004","על מעשה זה שואלים: \u0003למה לי למימר\u0004 \u0005[מדוע היה לו לומר]\u0006 את סוף המעשה ש\u0003החזירו\u0004 ר' עקיבא לרבן גמליאל? שהרי לעיקר הענין די לנו בסיפור כיצד יצאו ידי חובתם במתנה. ומשיבים: \u0003מלתא אגב אורחיה קמשמע לן\u0004 \u0005[דבר בדרך אגב השמיע לנו]\u0006 כי \u0003מתנה על מנת להחזיר — שמה מתנה.\u0004 שאף על פי שמראש היתנה שמתנה זו תוחזר אליו, כיון שנותן אותה לפי שעה במתנה — הרי זו קרויה מתנה גמורה.","וכעין זה \u0003אמר רבא;\u0004 האומר לחבירו: \u0003\"הא לך אתרוג זה על מנת שתחזירהו לי\"\u0004 ו\u0003נטלו\u0004 זה \u0003ויצא בו,\u0004 אם \u0003החזירו\u0004 לאחר מכן לנותן \u0003— יצא\u0004 בו ידי חובה, \u0003לא החזירו — לא יצא,\u0004 שכיון שלא קיים את התנאי, נמצא שלא היתה לו זכות במתנה.","ושואלים עוד: \u0003למה לי למימר\u0004 \u0005[לומר]\u0006 ולספר בלולב זה \u0003שלקחו\u0004 רבן גמליאל \u0003באלף זוז?\u0004 ומשיבים: \u0003להודיעך כמה מצות חביבות עליהן,\u0004 ששילם סכום עצום זה לקנות בו לולב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר בר\u0004 \u0005[בנו]\u0006 של \u0003אמימר לרב אשי: אבא צלויי קא מצלי ביה\u0004 \u0005[אבי היה מתפלל בו]\u0006 בלולב, שהיה מחזיק את המינים בידו בשעת התפילה, מתוך חיבת המצוה. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 בני הישיבה\u0005]\u0006 והלא שנינו: \u0003לא יאחז אדם תפילין בידו\u0004 או \u0003ספר תורה בחיקו ויתפלל\u0004 באותה שעה. ואם יש תפילין או ספר תורה בידו, \u0003לא ישתין בהן מים ולא יישן בהן לא שינת קבע ולא שינת עראי.\u0004","\u0003ואמר שמואל:\u0004 המחזיק בשעת תפילתו \u0003סכין,\u0004 או \u0003קערה\u0004 מלאה, או \u0003ככר\u0004 לחם, או \u0003מעות — הרי אלו כיוצא בהן.\u0004 שמאחר שחושש שמא יפלו מידו, הרי הם מפריעים לו בשעת התפלה ואין מכוון לבו כראוי בתפילה. ולפי זה, מדוע אם כן אין אומרים כך גם בענין הלולב? ומשיבים: \u0003התם לאו\u0004 \u0005[שם לא]\u0006 עניינים של \u0003מצוה נינהו\u0004 \u0005[הם],\u0006 בניגוד לתפילתו, ומתוך שענין אחר הם, לכן \u0003טריד בהו\u0004 \u0005[\u0006והריהו \u0005טרוד בהם],\u0006 ואינו מפנה דעתו להתפלל כראוי. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בלולב ושאר המינים \u0003מצוה נינהו\u0004 \u0005[הם]\u0006 וגם תפילתו מצוה היא ודבר אחד הם, לכך \u0003לא טריד בהו\u0004 \u0005[אינו טרוד בהם].\u0006","ומביאים ראיה למנהג זה, שכן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' אלעזר בר צדוק אומר: כך היה מנהגן של אנשי ירושלים\u0004 בימי הסוכות, היה \u0003אדם יוצא מביתו — ולולבו בידו.\u0004 וכשהוא \u0003הולך לבית הכנסת — לולבו בידו.\u0004 וכן כשהוא \u0003קורא קריאת שמע ומתפלל — ולולבו בידו.\u0004 וכאשר היה \u0003קורא בתורה,\u0004 או \u0003נושא את כפיו\u0004 ככהן לברכת כהנים, שאינו יכול להחזיק את הלולב — \u0003מניחו על גבי קרקע. הולך לבקר חולים,\u0004 או \u0003לנחם אבלים — לולבו בידו. נכנס לבית המדרש\u0004 ללמוד — היה \u0003משגר\u0004 \u0005[שולח]\u0006 \u0003לולבו ביד בנו,\u0004 או \u0003ביד עבדו\u0004 או \u0003ביד שלוחו\u0004 הביתה.","אגב כך שואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בסיפור כל הפרטים הללו, שעניינם אחד? ומסבירים: \u0003להודיעך כמה היו זריזין במצות\u0004 ומחבבין אותן.","במשנה נאמר ש\u0003ר' יוסי אומר\u0004 שאם חל \u0003יום טוב\u0004 ראשון בשבת והוציא בו את הלולב לרשות הרבים בשגגה — הרי זה פטור מן הקרבן. \u0003אמר אביי:\u0004"],["\u0003לא שנו\u0004 שפטור \u0003אלא\u0004 כשעדיין \u0003לא יצא בו\u0004 ידי חובה, \u0003אבל\u0004 אם כבר \u0003יצא בו\u0004 ידי חובה ומטלטלו אחר כך — הרי זה \u0003חייב\u0004 עליו. ותוהים: כיצד יתכן שיטלטלו ולא יצא בו? \u0003הא מדאגבהיה נפק ביה\u0004 \u0005[הרי\u0006 בעצם \u0005משהגביהו\u0006 ולקחו כבר \u0005יצא בו],\u0006 שהרי יוצא ידי חובה בהגבהה בלבד! \u0003אמר אביי:\u0004 כאן מדובר \u0003כשהפכו,\u0004 שהגביהו הפוך, ואין יוצא ידי חובה אלא כאשר אוחזו כדרך גידולו.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר באופן \u0003שלא הפכו,\u0004 ו\u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]:\u0006 \u0003כגון שהוציאו בכלי,\u0004 ומשום כך לא יצא בו. ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר\u0004 כי \u0003לקיחה על ידי דבר אחר שמה לקיחה!\u0004 ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא כשנוטלו על ידי דבר אחר ב\u0003דרך כבוד,\u0004 כגון שעוטפו ומקשטו \u0003אבל\u0004 אם נטלו \u0003דרך בזיון,\u0004 כגון זו שמכניס את המינים לכלי והם מיטלטלים בתוכו — אין זו דרך לקיחה ראויה.","\u0003אמר רב הונא: אומר היה ר' יוסי עולת העוף שנמצאת בין אגפיים\u0004 באחת מפינות המזבח, \u0003וכסבור חטאת העוף היא\u0004 ולא עולה \u0003ואכלה,\u0004 שהרי חטאת העוף נאכלת לכהנים — \u0003פטור\u0004 ואין אומרים שמעל הואיל ונהנה מקדשי המזבח בשגגה. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב הונא בכך — שהטועה \u0003בדבר מצוה\u0004 — \u0003פטור, היינו הך\u0004 \u0005[הוא הוא],\u0006 שאמר ר' יוסי במפורש ומה חידש רב הונא?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 בענין לולב ש\u0003טעה בדבר מצוה פטור — היינו דעבד\u0004 \u0005[הריהו שעשה]\u0006 בכל זאת \u0003מצוה\u0004 בלולב זה ולכן נפטר. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שטעה בעולת העוף ש\u0003טעה בדבר מצוה ולא עבד\u0004 \u0005[עשה]\u0006 \u0003מצוה — אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה פטור מקרבן על שגגה זו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב הונא שבכל זאת פטור.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003ר' יוסי אומר: השוחט את\u0004 קרבן \u0003התמיד שאינו מבוקר כהלכתו\u0004 מן המומים \u0003בשבת,\u0004 ונמצא בו מום ואין זה איפוא קרבן, ונמצא שחילל שבת בשחיטה לריק — הרי זה \u0003חייב חטאת\u0004 על ששגג בשחיטה, \u0003וצריך\u0004 להביא קרבן \u0003תמיד אחר\u0004 כשר. הרי שאפילו טעה בדבר מצוה חייב חטאת!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בר מינה דההיא\u0004 \u0005[חוץ ממנה מאותה\u0006 ברייתא\u0005],\u0006 שאין להביא משם ראיה. \u0003דהא אתמר עלה\u0004 \u0005[שהרי\u0006 כבר \u0005נאמר עליה]\u0006 על ברייתא זו \u0003אמר רב שמואל בר חתאי אמר רב המנונא סבא אמר רב יצחק בר אשיאן אמר רב הונא אמר רב:\u0004 כאן מדובר \u0003כגון שהביאו\u0004 את השה הזה \u0003מלשכה\u0004 שהיו בה טלאים \u0003שאינן מבוקרין,\u0004 שמתחילה לא היה צריך ליטול מאותה לישכה. שאין התמיד נלקח אלא מבין הטלאים המבוקרים, וכיון שעשה שגגה זו באופן שאין לומר שהוא בשל היותו טרוד במצוה, לכן אף שאכן היה עסוק במצוה — אינו פטור מקרבן.","\u0003מקבלת אשה\u0004 את הלולב \u0003מיד בנה,\u0004 או \u0003מיד בעלה ומחזירתו למים\u0004 שהיה עומד בהם ביום \u0003השבת,\u0004 כדי שלא יתייבש. \u0003ר' יהודה אומר: בשבת מחזירין\u0004 את הלולב למים, ו\u0003ביום טוב\u0004 אף \u0003מוסיפין\u0004 מים רעננים לכלי בו מונח הלולב כדי שלא יכמשו, \u0003וב\u0004חול ה\u0003מועד\u0004 אף \u0003מחליפין\u0004 את המים.","ועוד אמרו: \u0003קטן היודע לנענע\u0004 לולבו — הרי זה \u0003חייב בלולב,\u0004 משום חינוך.","על האמור במשנה שאשה מקבלת את הלולב תוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 ומובן מאליו\u0005]\u0006 ומדוע לא תעשה כן? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הואיל ואשה לאו\u0004 \u0005[לא]\u0006 \u0003בת חיובא\u0004 \u0005[חובת]\u0006 ארבעת המינים \u0003היא,\u0004 שהרי היא מצות עשה שהזמן גרמה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא תקבל\u0004 את הלולב, שמא לגביה טלטולו הוא כטילטול מוקצה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","שנינו במשנה: \u0003קטן היודע לנענע\u0004 חייב בלולב. ובכלל \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קטן היודע לנענע\u0004 לולבו — \u0003חייב בלולב,\u0004 יודע \u0003להתעטף\u0004 בטלית — \u0003חייב בציצית,\u0004 יודע \u0003לשמור תפילין\u0004 בנקיות גופו — \u0003אביו לוקח\u0004 (קונה) \u0003לו תפילין, יודע לדבר —\u0004 מיד \u0003אביו לומדו\u0004 (מלמדו) \u0003תורה וקריאת שמע.\u0004","ושואלים: \u0003תורה מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 כלומר, מה היא תורה שיכול ללמד לילד שרק עכשיו החל לדבר? \u0003אמר רב המנונא:\u0004 הכוונה שמלמד אותו לומר את הפסוק \u0003\"תורה צוה לנו משה מורשה קהלת יעקב\"\u0004 (דברים לג, ד), שיש בו הדגשת הקשר בין ישראל לתורה, והוא הקרוי בקיצור \"תורה\". ומוסיפים לשאול: \u0003וקריאת שמע מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 ומשיבים: \u0003פסוק ראשון\u0004 של קריאת שמע בלבד.","ועוד אמרו חכמים: תינוק \u0003היודע לשמור גופו\u0004 שלא יטמא — \u0003אוכלין על גופו טהרות,\u0004 שאם נגע בטהרות אוכלין מהן, ואין חוששין שמא היה טמא וטימאן. ותינוק היודע \u0003לשמור את ידיו\u0004 לבל תיטמאנה — \u0003אוכלין על ידיו טהרות\u0004 ומה שנגע בידיו אינו מוחזק כטמא. תינוק \u0003היודע לישאל,\u0004 שאפשר לשאול אותו ולברר במה נגע, כלל הוא שאם היתה הטומאה \u0003ברשות היחיד\u0004 ונשאל אם נגע בה והשיב כי אינו יודע — הרי \u0003ספיקו\u0004 (ספק אם נטמא) — \u0003טמא.\u0004 ואם היתה ספק טומאתו \u0003ברשות הרבים — ספיקו טהור.\u0004 ותינוק כהן \u0003היודע לפרוס כפיו\u0004 בברכת כהנים — \u0003חולקין לו תרומה\u0004 כשאר הכהנים \u0003בבית הגרנות.\u0004"],["\u0003היודע\u0004 כבר \u0003לשחוט,\u0004 כלומר: את מלאכת השחיטה — \u0003אוכלין משחיטתו,\u0004 אף על פי שאינו בקי בהלכות שחיטה. \u0003אמר רב הונא: והוא שגדול עומד על גביו\u0004 ומשגיח שאכן הוא שוחט כהלכה.","קטן ש\u0003יכול לאכול כזית דגן\u0004 — \u0003מרחיקין מצואתו וממימי רגליו ארבע אמות,\u0004 לצורך תפילה וקריאת שמע. שתינוק היכול כבר לאכול מאכלי דגן צואתו ומי רגליו מסריחים כשל גדול, ולא קודם לכן. \u0003אמר רב חסדא: והוא שיכול לאכול\u0004 כזית זה \u0003בכדי\u0004 הזמן של \u0003אכילת פרס.\u0004 אבל אם צריך לזמן מרובה יותר — עדיין אין צורך להרחיק. \u0003אמר רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ייבא: ובגדול, אף על פי שאינו יכול לאכול בכדי אכילת פרס\u0004 — מרחיקים מצואתו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויוסיף דעת יוסיף מכאוב\"\u0004 (קהלת א, יח), לומר, שלפי גודלו של אדם נוספים לו גם חסרונות. קטן \u0003היכול לאכול כזית צלי\u0004 — \u0003שוחטין עליו את הפסח\u0004 שמצרפים אותו לחשבון בני החבורה הנמנית על הפסח, \u0003שנאמר: \"איש לפי אכלו\u0004 תכוסו על השה\u0003\"\u0004 (שמות יב, ד). \u0003ר' יהודה אומר:\u0004 אין די בבירור יכולתו לאכול, כדי להכלילו כאחד מבני החבורה, אלא הדבר הקובע לענין זה הוא \u0003עד שיכול לברר אכילה,\u0004 כלומר: שיודע גם מה לאכול. \u0003כיצד\u0004 נקרא מברר אכילה? ילד \u0003שנותנין לו צרור\u0004 (אבן) — \u0003וזורקו, אגוז\u0004 — \u0003ונוטלו,\u0004 הרי זה ראוי להצטרף למנין האוכלים. מנין הימים בהם נוטלים \u0003לולב, ו\u0004כן הקפת המזבח ב\u0003ערבה,\u0004 הם \u0003ששה\u0004 או \u0003שבעה\u0004 ימים, שהדבר תלוי באיזה מימי החג חלה שבת באותה שנה. החיוב לגמור את \u0003ההלל והשמחה\u0004 (אכילת בשר שלמים) — \u0003שמונה\u0004 ימים. כלומר: בכל ימי חג הסוכות ובשמיני עצרת. חובת ישיבה ב\u0003סוכה וניסוך המים\u0004 על המזבח — \u0003שבעה\u0004 ימים. \u0003החליל\u0004 שמנגנים בו לשמחת החג במקדש — \u0003חמשה\u0004 או \u0003ששה\u0004 ימים.","","","","ומסבירים את הדברים: \u0003לולב שבעה כיצד?\u0004 אם \u0003יום טוב הראשון של חג חל להיות בשבת,\u0004 כיון שביום טוב הראשון חובת נטילת לולב היא מן התורה — הריהו דוחה את השבת וניטל אף בה. נמצא שנוטלים את ה\u0003לולב\u0004 באותה שנה \u0003שבעה\u0004 ימים. \u0003ושאר כל הימים\u0004 בשנים אחרות, כששבת חלה באחד מימי החג האחרים, ימי נטילת לולב הם \u0003ששה\u0004 בלבד, שאין נוטלים את הלולב בשבת בתוך החג.","הקפת המזבח ב\u0003ערבה שבעה\u0004 ימים, \u0003כיצד? יום השביעי של ערבה\u0004 (יום הושענא רבא) \u0003שחל להיות בשבת,\u0004 ומכיון שביום זה הרי זו מצוה מן התורה \u0003—\u0004 הריהי דוחה את השבת, ונמצא שמקיימים אז מצות \u0003ערבה שבעה\u0004 ימים. \u0003ושאר כל הימים,\u0004 אם יום שביעי של סוכות חל באחד משאר ימי השבוע, ושבת היא באחד מימי החג האחרים — מצוה זו רק \u0003ששה.\u0004","\u0003מצות לולב, כיצד\u0004 מקיימים אותה בזמן הבית, כשחל יום טוב ראשון \u0003בשבת? יום טוב הראשון של חג שחל להיות בשבת מוליכין\u0004 הכל \u0003את לולביהן\u0004 מבעוד יום \u0003להר הבית והחזנין\u0004 (השמשים) \u0003מקבלין מהן וסודרין\u0004 (מסדרים) \u0003אותן\u0004 את הלולבים \u0003על גבי איצטבא, והזקנים מניחין את\u0004 הלולבים \u0003שלהן בלשכה,\u0004 שלאלה ניתנה רשות מיוחדת להניחם שם, מתוך החשש שמא יפגעו בעת שידחפו כל הציבור ליטול איש את לולבו. \u0003ומלמדין אותם\u0004 את כל הבאים \u0003לומר: כל מי שמגיע לולבי לידו — הרי הוא לו במתנה,\u0004 שיש לחשוש שמא למחר יקבלו בחלקם לולב שאינו שלהם, וביום טוב הראשון הלא אין אדם יוצא ידי חובתו בשל אחר.","\u0003למחר\u0004 היו כולם \u0003משכימין ובאין\u0004 לבית המקדש, \u0003והחזנין\u0004 (השמשים) היו \u0003זורקין אותם\u0004 את הלולבים \u0003לפניהם, והן\u0004 הבאים למקדש בתוך המהומה היו \u0003מחטפין\u0004 את הלולבין זה מזה \u0003ו\u0004נמצאים \u0003מכין איש את חבירו. וכשראו בית דין שבאו לידי סכנה התקינו שיהא כל אחד ואחד נוטל בביתו.\u0004","על עצם ההלכה שאין נוטלים לולב בשבת שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 ייאסר הדבר? הלא הגבהת הלולב \u0003טלטול בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 ולכל היותר יש בו איסור מוקצה מדברי סופרים, וכיון שמצות לולב מן התורה, אם כן \u0003ולידחי\u0004 \u0005[ושידחה]\u0006 את ה\u0003שבת\u0004 באיסור קל כזה! \u0003אמר רבה:\u0004 איסור זה משום \u0003גזרה\u0004 הוא \u0003שמא יטלנו בידו\u0004 בשבת \u0003וילך אצל בקי\u0004 כדי \u0003ללמוד\u0004 כיצד לנענע או כיצד לברך עליו,"],["\u0003ויעבירנו ארבע אמות ברשות הרבים\u0004 ועובר על איסור חמור מן התורה. ומעירים: \u0003והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 של \u0003שופר\u0004 שאין תוקעים בו בשבת, \u0003והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 שאין קוראים את ה\u0003מגילה\u0004 כשחל פורים בשבת.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003יום ראשון נמי\u0004 \u0005[גם כן]\u0006 לא יטול את הלולב, מפני חשש זה! ומשיבים: \u0003ראשון, הא תקינו ליה רבנן\u0004 \u0005[הרי תיקנו לו חכמים]\u0006 תקנה שינענע את המינים \u0003בביתו,\u0004 וכיון שאסרו עליו להוציאם לא יבוא להוציאם אף לצורך לימוד. ושואלים: \u0003התינח\u0004 \u0005[נניח\u0006 דבר \u0005זה]\u0006 ל\u0003אחר\u0004 ה\u0003תקנה\u0004 שתיקנו שיטלנו בביתו, אולם \u0003קודם\u0004 ה\u0003תקנה מאי איכא למימר\u0004 \u0005[מה יש לומר,\u0006 להסביר\u0005],\u0006 מדוע התירו כלל ליטול את הלולב, הלא יש לחשוש כאמור!","\u0003אלא\u0004 יש לדחות את הטעם שאמרנו, ולהסביר כי יום \u0003ראשון דאיתיה\u0004 \u0005[ישנו,\u0006 מצותו\u0005]\u0006 \u0003מן התורה\u0004 גם \u0003בגבולין\u0004 ולא רק במקדש, לכן \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 והשאירו את המצוה במקומה בין במקדש בין בגבולים, אולם \u0003הנך דליתנהו\u0004 \u0005[אותם\u0006 ימים \u0005שאינם]\u0006 \u0003מן התורה בגבולין,\u0004 אלא רק משום זכר למקדש — \u0003גזרו בהו רבנן\u0004 \u0005[גזרו בהם חכמים].\u0006","ומקשים: \u0003אי הכי,\u0004 \u0005[אם כך]\u0006 שביום טוב ראשון אף בגבולים מצוה היא מן התורה, אם כן \u0003האידנא נמי\u0004 \u0005[היום גם כן]\u0006 ניטול לולב ביום ראשון של חג שחל להיות בשבת! ומשיבים: \u0003אנן לא ידעינן בקיבועא דירחא\u0004 \u0005[אנו לא יודעים בקביעת החודש]\u0006 מתי קבעוהו בית דין, ושמא מה שאנו חושבים כיום הראשון אכן אינו היום הראשון, ואין לעבור על גזירת חכמים במקום שאין בו מצוה מן התורה. ומקשים עוד: \u0003אינהו\u0004 \u0005[הם],\u0006 בני ארץ ישראל, \u0003דידעי בקיבועא דירחא\u0004 \u0005[שיודעים בקביעת החודש]\u0006 ומקדשים את החודש על פי הראיה, \u0003לידחו\u0004 \u0005[שידחו]\u0006 אף בזמן הזה!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך הוא גם כן]\u0006 וכך אכן נוהגים שם. \u0003דתנן חדא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה \u0005אחת]:\u0006 \u0003ביום טוב הראשון של חג שחל להיות בשבת כל העם מוליכין את לולביהן להר הבית, ותנן אידך\u0004 \u0005[ו\u0006לעומת זאת \u0005שנינו\u0006 במשנה \u0005אחרת]:\u0006 מוליכין לולביהם \u0003לבית הכנסת.\u0004 ומשינוי הלשון \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003כאן\u0004 שמוליכים להר הבית — \u0003בזמן שבית המקדש קיים, כאן\u0004 שמוליכים לבית הכנסת — \u0003בזמן שאין בית המקדש קיים.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","כיון שהוזכר הדבר, שואלים לגופו, \u0003דאיתיה\u0004 \u0005[שישנה]\u0006 מצות לולב \u0003מן התורה\u0004 גם \u0003בגבולין\u0004 ביום הראשון \u0003מנא לן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005];\u0006 נאמר: \u0003\"ולקחתם\u0004 לכם ביום הראשון פרי עץ הדר...\u0003\"\u0004 (ויקרא כג, מ), ודורשים: \"ולקחתם\" — לשון רבים \u0003שתהא לקיחה ביד כל אחד ואחד,\u0004 שאין אדם מוציא את חבירו בלקיחתו.","\u0003\"לכם\"\u0004 משמעו — \u0003משלכם, להוציא\u0004 (למעט) \u0003את\u0004 הלולב \u0003השאול ואת הגזול. \"ביום\",\u0004 בא להדגיש ולומר שמצוה ליטול אותו בכל יום מימי החג \u0003ואפילו\u0004 אם חל \u0003בשבת.\u0004 ומה שנאמר \u0003\"ראשון\"\u0004 ולא פירט היכן חובת הנטילה, בא ללמד כי \u0003אפילו\u0004 חובה זו חלה בכל מקום ואף \u0003בגבולין, \"הראשון\"\u0004 בהדגשה ובהבלטה — הרי זה מצמצם ו\u0003מלמד שאינו דוחה אלא יום טוב הראשון בלבד.\u0004 ומעתה דנים קצת בלשונה של ברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003\"ביום\"\u0004 — \u0003ואפילו בשבת.\u0004 ויש לשאול: \u0003מכדי\u0004 \u0005[הלא]\u0006 \u0003טלטול בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 זה, מה שנוטל את המינים, וכי \u0003איצטריך קרא למישרי\u0004 \u0005[הוצרך הכתוב להתיר]\u0006 את ה\u0003טלטול?\u0004 והרי איסור זה עצמו אינו מן התורה אלא מדברי חכמים בלבד! \u0003אמר רבא: לא נצרכא\u0004 הלכה זו \u0003אלא למכשירי לולב,\u0004 כלומר: לדברים שיש לעשות כדי להכשיר את הלולב למצוה, כגון קציצתו מן העץ, שבא הכתוב להתיר לעשות זאת בשבת, \u0003ואליבא דהאי תנא\u0004 \u0005[וכשיטת תנא זה]\u0006 המתיר אפילו בשבת, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לולב וכל מכשיריו דוחין את השבת,\u0004 אלו \u0003דברי ר' אליעזר.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003ר' אליעזר — אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ביום\",\u0004 ומשמע שישנה לחובה זו בכל יום, \u0003ואפילו בשבת.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 שנאמר \u0003\"ביום\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריכים\u0006 הם \u0005אותו]\u0006 להודיענו שמצות נטילת לולב היא דווקא \u0003ביום ולא בלילה.\u0004 ושואלים: \u0003ור' אליעזר, ביום ולא בלילה מנא ליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: \u0003נפקא ליה מסיפא דקרא\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו\u0006 הדבר \u0005מסופו של\u0006 אותו \u0005כתוב],\u0006 שנאמר: \u0003\"ושמחתם לפני ה' אלהיכם שבעת ימים\"\u0004 (ויקרא כג,מ) — מכאן שחובה נטילת לולב היא דווקא ב\u0003ימים ולא\u0004 ב\u0003לילות.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מדוע לא ילמדו אף הם מפסוק זה? ומשיבים: \u0003אי מהתם הוה אמינא\u0004 \u0005[אם משם\u0006 בלבד, \u0005הייתי אומר]:\u0006 \u0003לילף\u0004 \u0005[שנלמד]\u0006 כעין גזירה שווה \u0003\"ימים\" \"ימים\" מסוכה, מה להלן\u0004 בסוכה \u0003\"ימים\"\u0004 שנאמר, משמעו \u0003ואפילו\u0004 ב\u0003לילות, אף כאן\u0004 בלולב \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר: \u0003\"ימים\" ואפילו לילות.\u0004","ושואלים: \u0003וסוכה גופה מנא לן\u0004 \u0005[מניין לנו]\u0006 שמצותה אף בלילה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים];\u0006 נאמר: \u0003\"בסכות תשבו שבעת ימים\"\u0004 (ויקרא כג, מב), ודרשו חכמים: \u0003\"ימים\"\u0004 — \u0003ואפילו לילות.\u0004 וממשיך התנא בדיון \u0003אתה אומר ימים ואפילו לילות, או אינו אלא ימים ולא לילות? ודין הוא,\u0004 לכאורה יש סברה מסייעת לכך, \u0003נאמר כאן \"ימים\" ונאמר בלולב \"ימים\", מה להלן\u0004 בלולב — \u0003\"ימים\" ולא לילות, אף כאן\u0004 בסוכה \u0003\"ימים\" ולא לילות.\u0004 זה צד אחד בדיון.","\u0003או כלך\u0004 \u0005[לך]\u0006 \u0003לדרך זו\u0004 ותאמר להיפך: \u0003נאמר כאן\u0004 בסוכה \u0003\"ימים\" ונאמר במלואים \"ימים\"\u0004 (\"ופתח אהל מועד תשבו יומם ולילה שבעת ימים\". ויקרא ח, לב). \u0003מה להלן\u0004 בפרשת המילואים \u0003\"ימים\"\u0004 שאמר הכתוב, הכוונה \u0003ואפילו לילות\u0004 — \u0003אף כאן\u0004 בסוכה \u0003\"ימים\"\u0004 שנאמר, הכוונה \u0003ואפילו לילות.\u0004 ויש איפוא אפשרות להטות לשני הצדדים.","ומעתה נדון בדבר: \u0003נראה למי דומה\u0004 מצות סוכה יותר; \u0003דנין דבר שמצותו כל היום מדבר שמצותו כל היום,\u0004 כלומר מצות סוכה ממצות מילואים שאף מצותה בכל משך היום, \u0003ואל יוכיח דבר\u0004 כלולב \u0003שמצותו שעה אחת,\u0004 שהרי משנטלו שוב אינו חייב ליטלו כל אותו היום. \u0003או כלך לדרך זו\u0004 ותוכל לטעון להיפך: \u0003דנין דבר שמצותו לדורות\u0004 כסוכה \u0003מדבר שמצותו לדורות\u0004 כלולב, \u0003ואל יוכיחו מלואים שאין נוהגין לדורות\u0004 והיו מצוה לשעתה בלבד.","ואם כן, מצד הסברה בלבד אין מקום להכריע כאן, \u0003תלמוד לומר\u0004 מן הכתוב:"],["\u0003\"תשבו\", \"תשבו\" לגזרה שוה; נאמר כאן\u0004 בסוכות \u0003\"תשבו\"\u0004 (ויקרא כג, מב), \u0003ונאמר במלואים \"תשבו\"\u0004 (ויקרא ח, לה) \u0003מה להלן\u0004 במילואים \u0003\"ימים\"\u0004 שנאמר, הכוונה \u0003ואפילו לילות, אף כאן\u0004 בסוכה \u0003\"ימים\"\u0004 שנאמר, הכוונה \u0003ואפילו לילות.\u0004","שנינו במשנה שמצוות \u0003ערבה\u0004 מתקיימת לעתים \u0003שבעה\u0004 ימים. \u0003כיצד?\u0004 כשחל יום הושענא רבא שהוא יום שביעי של סוכות בשבת. ושואלים: \u0003ערבה בשביעי מאי טעמא דחיא\u0004 \u0005[מה טעם דוחה]\u0006 את ה\u0003שבת? אמר ר' יוחנן: כדי לפרסמה שהיא מן התורה,\u0004 שהרי לא נכתבה מצוותה במפורש בתורה, וצריכה פרסום. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003לולב נמי לידחי\u0004 \u0005[גם כן ידחה]\u0006 שבת, אף כשהיא חלה בבאחד משאר ימי החג ולא דווקא ביום הראשון \u0003כדי לפרסמו שהוא מן התורה\u0004 כל שבעה ימים, שהרי אף זה לא נתפרש!","ומשיבים: \u0003לולב\u0004 הלא גזרו בו \u0003גזרה משום\u0004 החשש אותו הזכיר \u0003רבה\u0004 (לעיל סוכה מב, ב), שמא יטלנו בידו וילך ללמוד דיניו אצל הבקי ויבוא לטלטלו ברשות הרבים. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ב\u0003ערבה נמי\u0004 \u0005[גם כן]\u0006 \u0003נגזור,\u0004 מתוך אותו חשש! ומשיבים: יש להבדיל בין הדברים, כי \u0003ערבה — שלוחי בית דין מייתי לה\u0004 \u0005[מביאים אותה]\u0006 לכהנים והכהנים הם שעושים מצותה במקדש ושלוחי בית דין נזהרים להכינה מבעוד יום ולא יבואו לטלטל במקום האסור. ולעומת זאת \u0003לולב לכל\u0004 אדם \u0003מסור\u0004 ויש מקום לגזור שמא יטעה בכך.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבערבה סומכים אנו על שלוחי בית דין, מדוע אם כן אין מצות ערבה דוחה את השבת אלא בשביעי בלבד? \u0003כל יומא נמי לידחי\u0004 \u0005[בכל יום\u0006 מימי החג \u0005גם כן תדחה]\u0006 מצות ערבה את השבת! ומשיבים: אם היו עושים כן \u0003אתי לפקפוקי\u0004 \u0005[יבואו לפקפק,\u0006 לזלזל\u0005]\u0006 \u0003ב\u0004מצות \u0003לולב,\u0004 שהרי בניגוד למצות ערבה, מצות לולב אינה דוחה את השבת אלא ביום אחד בלבד. ושואלים מצד אחר: \u0003ולידחי\u0004 \u0005[ושתדחה]\u0006 מצות ערבה רק \u0003ביום טוב ראשון\u0004 כפי שדוחה מצות לולב! ומשיבים: \u0003לא מוכחא מלתא\u0004 \u0005[אין מוכח הדבר]\u0006 אז בפרסום מצות ערבה, כי \u0003אמרי\u0004 \u0005[אומרים]\u0006 בני אדם: \u0003לולב הוא דקא דחי\u0004 \u0005[שדוחה]\u0006 את השבת, וכיון שהותר בלולב הותר גם בערבה.","ומקשים: אם כן \u0003ולידחי בחד מהנך\u0004 \u0005[ושידחה באחד מאלה]\u0006 מימי חול המועד, ומדוע דווקא בשביעי? ומשיבים: \u0003כיון דקא מפקת לה\u0004 \u0005[שאתה מוציא אותה]\u0006 מן היום ה\u0003ראשון, אוקמה\u0004 \u0005[העמד אותה]\u0006 על היום ה\u0003שביעי\u0004 שאף הוא יום מיוחד בימי חג הסוכות, ולא בשאר ימי חול המועד שאין בהם יחוד.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחשובה כל כך מצוה זו \u0003האידנא נמי לידחי\u0004 \u0005[בזמן הזה,\u0006 שאין בית המקדש קיים, \u0005גם כן תדחה]\u0006 מצות ערבה ביום השביעי של החג את השבת! ומשיבים: \u0003אנן לא ידעינן בקיבועא דירחא\u0004 \u0005[אנחנו אין אנו יודעים בקביעת החודש]\u0006 ויתכן שהיום בו חל היום השביעי של החג לחשבוננו, בטעות יסודו, ומפני חשש זה איננו יכולים לזלזל בכבוד השבת.","ומקשים: \u0003אינהו דידעי בקיבועא דירחא לידחי\u0004 \u0005[הם\u0006 בני ארץ ישראל \u0005שיודעים בקביעת החודש שידחו]\u0006 את השבת! \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003בר הדיא\u0004 מארץ ישראל לבבל \u0003אמר:\u0004 שאלה זו אינה מציאותית, כי \u0003לא איקלע\u0004 \u0005[הזדמן]\u0006 יום שביעי של סוכות לחול בשבת, שכך היו מתקנים את סדר עיבור השנה. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין וכל\u0004 שאר \u0003נחותי\u0004 \u0005[\u0006השליחים \u0005היורדים]\u0006 מארץ ישראל לבבל, ואלה שהלכו מבבל לארץ ישראל ושבו מאוחר יותר למקומם \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ו\u0004עם כל זה \u0003לא דחי\u0004 \u0005[אינו דוחה]\u0006 את השבת.","ואומרים: \u0003ואלא קשיא\u0004 \u0005[\u0006לפיכך \u0005הרי זה קשה]\u0006 מדוע אין מצות ערבה ביום השביעי דוחה את השבת אף בזמן הזה? \u0003אמר רב יוסף: מאן לימא לן\u0004 \u0005[מי יאמר לנו]\u0006 שמצות \u0003ערבה בנטילה\u0004 ובהקפה כמו הלולב, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בזקיפה\u0004 ליד המזבח בלבד, וכיון שאין מזבח, אינה דוחה בזמן הזה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003לולב וערבה ששה ושבעה. מאי לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן כי מצות ערבה \u0003כ\u0004מצות \u0003לולב; מה לולב\u0004 מצותו \u0003בנטילה — אף ערבה\u0004 מצותה \u0003בנטילה\u0004 ולא בזקיפה! ענה לו: \u0003מידי אריא\u0004 \u0005[וכי הדברים שייכים זה לזה]\u0006 בהכרח? \u0003הא כדאיתיה והא כדאיתיה\u0004 \u0005[זה\u0006 הלולב \u0005כמות שהוא,\u0006 בנטילה, \u0005וזה\u0006 הערבה \u0005כמות שהוא,\u0006 בזקיפה\u0005],\u0006 ואין איפוא ללמוד מזה לזה בסדר עשייתם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממקום אחר, ששנינו: \u0003בכל יום מקיפין את המזבח פעם אחת, ואותו היום\u0004 (הושענא רבא) \u0003שבע פעמים. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שמקיפים \u0003בערבה?\u0004 והרי שמצות ערבה בנטילה ולא בזקיפה! ענה לו: \u0003לא,\u0004 הכוונה היא שמקיפים \u0003בלולב.\u0004 הקשה אביי: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב נחמן אמר אמר רבה בר אבוה: בערבה\u0004 מקיפין! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: \u0003הוא אמר לך בערבה,\u0004 אולם גם הוא אמורא כמותי ואני חולק עליו \u0003ואנא אמינא\u0004 \u0005[ואני אומר]\u0006 שמקיפין \u0003בלולב\u0004 ולא בערבה. \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים אחרים בדבר; \u0003ר' אלעזר אומר:\u0004 מקיפים את המזבח \u0003בלולב. רב שמואל בן נתן אמר ר' חנינא:\u0004 מקיפים \u0003בערבה. וכן אמר רב נחמן אמר רבה בר אבוה:\u0004 מקיפים \u0003בערבה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר בר חנה: בר אוריא\u0004 \u0005[בן תורה]\u0006 \u0003תא ואימא לך מלתא מעליתא דהוה אמר אבוך\u0004 \u0005[בוא ואומר לך דבר מעולה שהיה אומר אביך]\u0006 רבה בר בר חנה. \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל היום\u0004 מימי חג הסוכות \u0003מקיפין את המזבח פעם אחת, ואותו היום,\u0004 היום השביעי של החג, \u0003מקיפין את המזבח שבע פעמים, הכי אמר אבוך משמיה\u0004 \u0005[כך אמר אביך משמו]\u0006 של \u0003ר' אלעזר:\u0004 מקיפין אותו \u0003בלולב.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי לרב יוסף מתוספתא, ששנו בה: \u0003לולב דוחה את השבת בתחלתו\u0004 ביום הראשון של החג \u0003וערבה\u0004 דוחה \u0003בסופו\u0004 של החג, ביום השביעי. \u0003פעם אחת חל שביעי של ערבה להיות בשבת, והביאו מרביות\u0004 (ענפים) \u0003של ערבה מערב שבת והניחום בעזרה\u0004 כדי להשתמש בהם בשבת. \u0003והכירו בהן בייתוסין\u0004 שהיו במקדש, והם חלקו על חכמים שיש מצוה בערבה ביום השביעי, \u0003ונטלום וכבשום\u0004 את ענפי הערבה \u0003תחת אבנים,\u0004 כדי שייאסר על חכמים לטלטלם בשבת משום איסור מוקצה.","\u0003למחר הכירו בהן עמי הארץ\u0004 שענפי הערבה מונחים מתחת לאבנים, והם היו מחזיקים בדברי חכמים, וכיון שלא היו בקיאים בדקדוקי מצוות \u0003ושמטום מתחת האבנים, והביאום הכהנים וזקפום בצידי המזבח. לפי שאין\u0004 ה\u0003בייתוסין מודים שחיבוט ערבה דוחה את השבת.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 למד אתה שערבה \u0003בנטילה היא,\u0004 שהרי מדובר בחיבוט ערבה ולא רק בזקיפתה. מעירים: אכן \u0003תיובתא\u0004 \u0005[קושיא חמורה\u0006 היא\u0005]\u0006 לדברי רב יוסף.","כיון שכך חוזרים אנו לבעיה ראשונה \u0003ואלא נדחו\u0004 \u0005[שידחו]\u0006 משום מצות ערבה אף ביום שביעי שחל בשבת! ומשיבים: \u0003כיון דאנן\u0004 \u0005[שאנו]\u0006 בגולה \u0003לא דחינן\u0004 \u0005[איננו דוחים]\u0006 את השבת, משום זה \u0003אינהו נמי לא דחו\u0004 \u0005[הם גם כן אינם דוחים].\u0006 ומקשים: והאם כך נוהגים בארץ ישראל? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003יום טוב הראשון\u0004 של סוכות, \u0003דלדידן\u0004 \u0005[שעבורנו\u0006 בגולה\u0005]\u0006 \u0003לא דחי\u0004 \u0005[אינו דוחה]\u0006 את השבת \u0003ולדידהו דחי\u0004 \u0005[ועבורם,\u0006 בני ארץ ישראל \u0005דוחה]\u0006 את השבת במצוות לולב!"],["\u0003אמרי\u0004 \u0005[אומרים]:\u0006 באמת \u0003לדידהו נמי לא דחי\u0004 \u0005[להם,\u0006 לבני ארץ ישראל \u0005גם כן אינו דוחה]\u0006 את השבת, ולא כפי שאמרנו. ושואלים: \u0003ואלא קשיא הני תרתי\u0004 \u0005[קשה\u0006 מה ההבדל שבין \u0005שני\u0006 מקורות \u0005אלה];\u0006 \u0003דתנא חדא\u0004 \u0005[ששנה\u0006 במקום \u0005אחד]\u0006 \u0003כל העם מוליכין את לולביהן\u0004 בשבת \u0003להר הבית ותניא אידך\u0004 \u0005[ושנינו\u0006 בברייתא \u0005אחרת]\u0006 שמוליכים \u0003לבית הכנסת, ומתרצינן\u0004 \u0005[ואנו מתרצים]\u0006 קושי זה באמרנו: \u0003כאן\u0004 שאמרנו שמוליכים לולביהם להר הבית \u0003—\u0004 הרי זה \u0003בזמן שבית המקדש קיים, כאן\u0004 שאמרנו שמוליכים לולביהם לבית הכנסת — הרי זה \u0003בזמן שאין בית המקדש קיים.\u0004 הרי שאף משחרב בית המקדש, היו בני ארץ ישראל מקיימים מצוות לולב אף בשבת (אם כי בבית הכנסת ולא כבעת עמוד המקדש על מכונו) ונמצאת שבת נדחית על ידם!","ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003בזמן שבית המקדש קיים\u0004 דווקא, \u0003ולא קשיא\u0004 \u0005[ואינו קשה]\u0006 משינוי הלשון; כי בשתי הברייתות מדובר בבני ארץ ישראל בזמן שבית המקדש קיים, \u0003כאן\u0004 שאמרנו שמוליכים למקדש — מדובר באנשים הסמוכים ל\u0003מקדש, כאן\u0004 שאמרנו כי מוליכים לבית הכנסת, מדובר \u0003בגבולין\u0004 בשאר מקומות בארץ ישראל, שהיו יודעים אז בדיוק זמן קביעת החודש. אבל משחרב בית המקדש, שוב אין מצות לולב דוחה את השבת לא בחוץ לארץ ולא בארץ ישראל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003לולב, דעבדינן ליה\u0004 \u0005[שעושים אנו אותו]\u0006 גם בימינו \u0003שבעה\u0004 ימים \u0003זכר למקדש, ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003ערבה דלא עבדינן ליה\u0004 \u0005[שאין אנו עושים אותה]\u0006 \u0003שבעה\u0004 ימים \u0003זכר למקדש? אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003הואיל ואדם יוצא ידי חובתו בערבה שבלולב\u0004 ואין צורך בזכרון נוסף. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: אין הדבר מספיק, שהרי \u0003ההוא משום לולב הוא דקא עביד ליה\u0004 \u0005[שעושה זאת],\u0006 שנוטל את הערבה בין מיני הלולב, \u0003וכי תימא דקא מגבה ליה והדר מגבה ליה\u0004 \u0005[ואם תאמר שהוא מגביה אותה וחוזר ומגביה אותה],\u0006 פעם אחת למצוות ארבעת המינים ופעם שניה לזכר ערבה שבמקדש, \u0003והא מעשים בכל יום דלא קא עבדינן הכי\u0004 \u0005[שאין אנו עושים כך]\u0006 ואין מגביהים פעמיים!","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לולב\u0004 שמצותו \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003עבדינן\u0004 \u0005[עושים אנו]\u0006 גם בימינו \u0003שבעה\u0004 ימים \u0003זכר למקדש, ערבה\u0004 שמצותה \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 בלבד — \u0003לא עבדינן לה\u0004 \u0005[אין עושים אותה]\u0006 \u0003שבעה זכר למקדש.\u0004","ושואלים: \u0003למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 אמר רבא דברים אלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003ל\u0004שיטת \u0003אבא שאול\u0004 אמר זאת, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003\"ערבי נחל\" כתיב\u0004 \u0005[נאמר]\u0006 בלשון רבים והן \u0003שתים, אחת ללולב ואחת למקדש\u0004 ואם כן לדעתו הדבר מפורש בתורה. \u0003אי לרבנן\u0004 \u0005[אם ל\u0006דעת \u0005חכמים],\u0006 הלא \u0003הלכתא גמירי לה\u0004 \u0005[בהלכה\u0006 למשה מסיני \u0005למדו אותה],\u0006 ש\u0003אמר ר' אסי אמר ר' יוחנן משום ר' נחוניא איש בקעת בית חורתן: עשר נטיעות\u0004 הנטועות בסדר מסויים בתוך שדה בית סאה, שבגללן מותר לחרוש שדה סמוך לשנת השמיטה, על אף שבדרך כלל יש להוסיף מן החול על הקודש, וכן מצות \u0003ערבה\u0004 שבמקדש \u0003וניסוך המים\u0004 על המזבח בחג הסוכות, הם \u0003הלכה למשה מסיני.\u0004","\u0003אלא\u0004 יש לדחות תירוץ זה, ולומר בסגנון אחר: \u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לולב דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003עיקר מן התורה,\u0004 שהרי מצותו כתובה במפורש — \u0003בגבולין עבדינן ליה\u0004 \u0005[עושים אנו אותו]\u0006 \u0003שבעה\u0004 ימים \u0003זכר למקדש,\u0004 אבל \u0003ערבה דלית לה\u0004 \u0005[שאין לה]\u0006 \u0003עיקר מן התורה,\u0004 שאין מצוותו כתובה במפורש — \u0003בגבולין לא עבדינן\u0004 \u0005[אין אנו עושים]\u0006 \u0003שבעה\u0004 ימים \u0003זכר למקדש.\u0004","בענין זה של הערבה במקדש \u0003אמר ריש לקיש: כהנים בעלי מומין נכנסין בין האולם ולמזבח\u0004 על אף שכרגיל אסור להם להכנס לשם מפני מומם, \u0003כדי לצאת בערבה\u0004 שהם מקיפים את המזבח בערבות, וממילא מגיעים גם בין האולם ולמזבח. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: מי אמרה\u0004 להלכה זו? ותוהים: על דברי ר' יוחנן: מה מקום לשאלה \u0003מי אמרה?\u0004 מדוע נראה ר' יוחנן כמפקפק בדבר, \u0003הא איהו\u0004 \u0005[הרי הוא\u0006 עצמו\u0005]\u0006 \u0003אמר\u0004 זאת! ש\u0003אמר ר' אסי אמר ר' יוחנן משום ר' נחוניא איש בקעת בית חורתן: עשר נטיעות, ערבה, וניסוך המים\u0004 הם \u0003הלכה למשה מסיני.\u0004","\u0003אלא\u0004 זו היתה תמיהתו של ר' יוחנן: \u0003מי אמרה\u0004 שמצותה \u0003בנטילה,\u0004 כלומר: שהכהנים מחזיקים ערבות בידם ומקיפים את המזבח, \u0003דלמא\u0004 \u0005[שמא]\u0006 מצותה \u0003בזקיפה\u0004 בלבד, שכהן אחד מעמיד את ענפי הערבה סמוך למזבח ודי בכך! ועוד: \u0003מי אמרה\u0004 שמצותה אף \u0003בבעלי מומין דלמא\u0004 \u0005[שמא]\u0006 רק \u0003בתמימים!\u0004","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו \u0003ר' יוחנן ור' יהושע בן לוי, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: ערבה יסוד נביאים\u0004 שהנביאים חגי זכריה ומלאכי הם שתיקנו וקבעו מצוה זו של ערבה במקדש כחובה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: ערבה מנהג נביאים\u0004 היא, שאין זו מצוה קבועה שתיקנו נביאים, אלא מנהג עתיק שנהגו בו הנביאים והנהיגו אף את העם במצוה זו. ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 הבעיה שלא היתה ברורה לנו תחילה, ונקבע כי \u0003ר' יוחנן הוא\u0004 ש\u0003אמר\u0004 כי \u0003יסוד נביאים\u0004 היא, ש\u0003אמר ר' אבהו אמר ר' יוחנן: ערבה יסוד נביאים הוא.\u0004 ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שכך היא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אבהו: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן משום ר' נחוניא איש בקעת בית חורתן: עשר נטיעות, ערבה, וניסוך המים הלכה למשה סיני\u0004 הם, וכיצד ייחס אותה לנביאים? \u0003\"אשתומם כשעה חדא\"\u0004 \u0005[תהה על דבר זה כשעה אחת]\u0006 ולאחר שהרהר בדבר \u0003ואמר\u0004 שיש להסביר לדברי ר' יוחנן כי אכן מצות ערבה הלכה למשה מסיני היא, אלא ש\u0003שכחום\u0004 במשך הדורות \u0003וחזרו ויסדום.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: דלכון\u0004 \u0005[שלכם]\u0006 כלומר: חכמי בבל, \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003דלהון\u0004 \u0005[שלהם],\u0006 של חכמים \u0003היא\u0004 תקנה זו, ואיננה לא הלכה למשה מסיני, ולא יסוד נביאים, אלא מנהג מדברי חכמים בלבד! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006"],["\u0003כאן במקדש\u0004 — היא הלכה למשה מסיני \u0003כאן בגבולין\u0004 — יסוד נביאים היא.","\u0003אמר ר' אמי: ערבה\u0004 שנוטלים למצות ערבה, \u0003צריכה שיעור, ואינה ניטלת אלא בפני עצמה\u0004 ולא עם הלולב, \u0003ואין אדם יוצא ידי חובתו\u0004 למצות ערבה \u0003בערבה שבלולב.\u0004 ותוהים: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 כי הערבה \u0003אינה ניטלת אלא בפני עצמה, פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו ש\u0003אין אדם יוצא\u0004 ידי חובתו \u0003בערבה שבלולב!\u0004","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דלא אגבהיה\u0004 \u0005[במקום שלא הגביה]\u0006 את הלולב למצות ארבעת המינים \u0003והדר אגבהיה\u0004 \u0005[וחזר והגביהו]\u0006 בשנית לשם מצות ערבה, \u0003אבל\u0004 אם \u0003אגבהיה והדר אגבהיה\u0004 \u0005[הגביהו וחזר והגביהו]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכך \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף אם הגביה את הלולב פעם נוספת במיוחד כדי לצאת ידי חובת מצות ערבה — אינו יוצא, אלא צריך ליטול ערבה בפני עצמה. \u0003ורב חסדא אמר ר' יצחק: אדם יוצא ידי חובתו בערבה שבלולב ביום טוב הראשון של חג.\u0004","כיון שאמרנו שערבה צריכה שיעור, שואלים: \u0003וכמה\u0004 צריך להיות \u0003שיעורה? אמר רב נחמן: שלשה בדי עלין לחין,\u0004 כלומר: שלושה ענפים שיש בכל אחד עלים לחים ולא יבשים. \u0003ורב ששת אמר: אפילו עלה אחד ובד אחד.\u0004 ותוהים על הלשון: \u0003עלה אחד ובד אחד סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005],\u0006 שיאחוז בידו עלה אחד לחוד וענף לחוד?! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003אפילו עלה אחד בבד אחד\u0004 יוצא בו ידי חובה.","מסופר: \u0003אמר\u0004 החכם \u0003אייבו\u0004 (אבי האמורא רב): \u0003הוה קאימנא\u0004 \u0005[הייתי עומד]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אלעזר בר צדוק ואייתי ההוא גברא\u0004 \u0005[והביא אדם אחד]\u0006 \u0003ערבה קמיה\u0004 \u0005[לפניו]\u0006 לקיים בה את המצוה, \u0003שקיל, חביט חביט, ולא בריך\u0004 \u0005[לקח, חבט\u0006 בה \u0005חבוט, ולא ברך]\u0006 עליה. משמע: \u0003קסבר\u0004 \u0005[סבר]\u0006 כי מצות ערבה \u0003מנהג נביאים הוא\u0004 ולכן אין מברכים עליו, כפי שאין מברכים על מנהגים אחרים. וכגון זה מסופר: \u0003אייבו וחזקיה בני ברתיה\u0004 \u0005[בני בתו]\u0006 של \u0003רב אייתו\u0004 \u0005[הביאו]\u0006 \u0003ערבה לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב\u0004 למצוה, \u0003חביט חביט ולא בריך\u0004 \u0005[חבט\u0006 בה \u0005חבוט ולא ברך],\u0006 משמע כי \u0003קא סבר\u0004 \u0005[סבור\u0006 אף \u0005הוא]\u0006 כי \u0003מנהג נביאים הוא.\u0004","כיון שהבאנו את דברי אייבו במה שלמד מר' אלעזר בר' צדוק, מביאים הלכה נוספת שנמסרה בדרך זו; \u0003אמר אייבו הוה קאימנא קמיה\u0004 \u0005[עמדתי לפני]\u0006 \u0003ר' אלעזר בר' צדוק, אתא לקמיה ההוא גברא\u0004 \u0005[בא לפניו אדם אחד]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם; \u0003קרייתא\u0004 \u0005[כפרים]\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי, כרמיא\u0004 \u0005[כרמים]\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי, זיתיא\u0004 \u0005[זיתים]\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי, ואתו בני קרייתא\u0004 \u0005[ובאים בני הכפרים]\u0006 \u0003ומקשקשין בכרמיא\u0004 \u0005[ומעדרים בכרמים]\u0006 בשנת השמיטה \u0003ואוכלין בזיתיא\u0004 \u0005[מן הזיתים]\u0006 הללו — \u0003אריך או לא אריך\u0004 \u0005[ראוי או אינו ראוי]\u0006 להניח למהלך זה של הדברים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר בר' צדוק לאותו אדם: \u0003לא אריך\u0004 \u0005[אינו ראוי].\u0006 \u0003הוה קא שביק ליה ואזיל\u0004 \u0005[עזבו\u0006 אותו אדם \u0005והלך].\u0006 \u0003אמר\u0004 ר' אלעזר בר' צדוק: \u0003כדו הויתי דיירי בארעא הדא ארבעים שנין\u0004 \u0005[כבר הייתי חי בארץ זו ארבעים שנה],\u0006 \u0003ולא חמיתי בר אינש מהלך בארחן דתקנן כדין\u0004 \u0005[ראיתי עוד אדם הולך בדרך הישר כמו זה].\u0006 \u0003הדר ואתא\u0004 \u0005[חזר\u0006 אותו אדם \u0005ובא]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי מיעבד\u0004 \u0005[מה אעשה]\u0006 לתקן את ענין העידור של הכרמים? \u0003אמר ליה: אפקר זיתיא לחשוכיא, ותן פריטיא לקשקושי כרמים\u0004 \u0005[הפקר את הזיתים לעניים, ותן פרוטות\u0006 לעובדים בשכרם \u0005שיעדרו את הכרמים].\u0006","לגופו של הענין תוהים: \u0003וקשקושי מי שרי\u0004 \u0005[ועידור האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"והשביעת תשמטנה ונטשתה\"\u0004 (שמות כג, יא) ודרשו: \u0003\"תשמטנה\" — מלקשקש, \"ונטשתה\" — מלסקל\u0004 את אבניה, הרי שהקשקוש אסור! \u0003אמר רב עוקבא בר חמא: תרי קשקושי הוו\u0004 \u0005[שני\u0006 מיני \u0005עידור הם];\u0006 \u0003חד סתומי פילי\u0004 \u0005[אחד לסתום סדקים]\u0006 בקרקע \u0003וחד אברויי אילני\u0004 \u0005[ואחד להבריא\u0006 ולהועיל \u0005לאילנות].\u0006 \u0003אברויי אילני\u0004 \u0005[להבריא את האילנות]\u0006 — \u0003אסור\u0004 בשביעית, אולם \u0003סתומי פילי\u0004 \u0005[לסתום את הסדקים]\u0006 — \u0003שרי\u0004 \u0005[מותר]\u0006 שאינו נעשה לגידול הנטיעות אלא למנוע את מיתת האילנות.","ועוד מדברי תורה שנמסרו באופן זה: \u0003אמר אייבו משום ר' אלעזר בר' צדוק: אל יהלך אדם בערבי שבתות יותר מ\u0004מהלך \u0003שלש פרסאות\u0004 אלא ישבות בהקדם, כדי שיהא בטוח שיש עימו סעודה מתאימה לשבת. \u0003אמר רב כהנא: לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 שלא ילך מרחק כזה \u0003לביתיה\u0004 \u0005[אל ביתו]\u0006 \u0003אבל\u0004 אם הולך \u0003לאושפיזיה\u0004 \u0005[לבית מלונו]\u0006 \u0003אמאי דנקיט סמיך\u0004 \u0005[על מה שהוא לוקח בידו הוא סומך],\u0006 שכיון שאינו יודע אם ימצא שם מאכל, הריהו מביא בידו כדי הצורך.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בלשון אחרת; \u0003אמר רב כהנא: לא נצרכא\u0004 הלכה זו שלא ילך אדם מהלך שלוש פרסאות בערב שבת דווקא להולך למקום זר, \u0003אלא אפילו לביתו\u0004 לא ילך, שמא לא ימצא כדי הצורך. \u0003אמר רב כהנא: בדידי הוה עובדא\u0004 \u0005[בי עצמי היה מעשה]\u0006 שהלכתי מהלך כזה בערב שבת לכיוון ביתי \u0003ואפילו כסא דהרסנא\u0004 \u0005[דגים קטנים מטוגנים]\u0006 \u0003לא אשכחי\u0004 \u0005[מצאתי]\u0006 בבית. ללמדך שצריך אדם לדאוג להכין צרכי שבת מבעוד יום.","שנינו במשנה \u0003מצות לולב\u0004 בשבת \u0003כיצד?\u0004 ומבואר, כיצד מסדרים את לולביהם על גבי האיצטבא שבבית המקדש. \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן\u0004 בנוסח זה: \u0003סודרים\u0004 היו את הלולבים \u0003על גג האיצטבא\u0004 שבמקדש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן:"],["\u0003וכי לייבשן הוא צריך\u0004 שמניחים אותם על הגג? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 וכך תגרוס: \u0003על גב האיצטבא,\u0004 מתחת לגג ובמקום המיועד לכך. \u0003אמר רחבא אמר רב יהודה: הר הבית סטיו כפול היה\u0004 שדרת עמודים כפולה היתה, \u0003סטיו לפנים מסטיו\u0004 שדרה לפנים משדרה והיה מקום להניח שם הלולבים.","\u0003מצות ערבה כיצד? מקום היה למטה מירושלים ונקרא \"מוצא\",\u0004 והיו \u0003יורדין לשם ומלקטין משם מורביות\u0004 (ענפים) \u0003של ערבה, ובאין וזוקפין אותן בצדי המזבח וראשיהן\u0004 היו \u0003כפופין על גבי המזבח,\u0004 ובאותה שעה \u0003תקעו והריעו ותקעו\u0004 בשופרות. \u0003בכל יום מקיפין את המזבח פעם אחת ואומרים: \"אנא ה' הושיעה נא, אנא ה' הצליחה נא\"\u0004 (תהלים קיח, כה). \u0003ר' יהודה אומר:\u0004 אומרים היו: \u0003\"אני והו\u0004 (אחד משמות ה') \u0003הושיעה נא\". ואותו היום\u0004 בשביעי של סוכות (הושענא רבה) היו \u0003מקיפין את המזבח שבע פעמים. בשעת פטירתן\u0004 (פרידתן ויציאתן) משם \u0003מה היו אומרים: יופי לך מזבח, יופי לך מזבח! ר' אלעזר אומר\u0004 כך היו אומרים: \u0003ליה\u0004 לה' \u0003ולך מזבח, ליה\u0004 לה' \u0003ולך מזבח.\u0004","ומעירים: \u0003כמעשהו בחול כך\u0004 היה \u0003מעשהו בשבת\u0004 לענין זקיפה, \u0003אלא שהיו מלקטין אותן\u0004 את הענפים \u0003מערב\u0004 שבת \u0003ומניחין אותן בגיגיות של זהב, כדי שלא יכמושו\u0004 (יתייבשו). \u0003ר' יוחנן בן ברוקה אומר:\u0004 מנהג מיוחד היה ביום זה, \u0003חריות\u0004 (ענפים) \u0003של דקל היו מביאין\u0004 לבית המקדש \u0003וחובטין אותן בקרקע בצדי המזבח, ואותו היום\u0004 שביעי של סוכות \u0003נקרא\u0004 יום \u0003חבוט חריות. מיד\u0004 לאחר שקיימו מצוות נטילת לולב ביום האחרון של חג הסוכות היו הגדולים הולכין למקום ה\u0003תינוקות\u0004 ו\u0003שומטין את לולביהן\u0004 מתוך ידיהם \u0003ואוכלין\u0004 את \u0003אתרוגיהן\u0004 של הקטנים, כביטוי לחדוה יתירה.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \"מוצא\" שאמרו במשנה — \u0003מקום קלניא\u0004 \u0005[מושבת חיילים\u0006 רומאים\u0005]\u0006 \u0003הוה\u0004 \u0005[היה]\u0006 ושואלים: \u0003ותנא דידן מאי טעמא קרי ליה\u0004 \u0005[והתנא שלנו מה טעם קרא לו]\u0006 \u0003\"מוצא\"?\u0004 ומשיבים: \u0003איידי דמיפק מכרגא דמלכא קרי ליה\u0004 \u0005[כיון שהוא\u0006 פטור \u0005ומוצא ממסי המלך\u0006 היו \u0005קוראים לו]\u0006 \u0003\"מוצא\".\u0004","שנינו במשנה שלאחר שהיו מלקטים ענפי ערבה, היו \u0003באין וזוקפין אותן בצידי המזבח. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003רבות\u0004 היו, והיו \u0003ארוכות וגבוהות אחד עשר אמה, כדי שיהו גוחות\u0004 (נשענות ונכפפות) \u0003על המזבח אמה.\u0004","\u0003אמר מרימר משום מר זוטרא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003על היסוד\u0004 של המזבח \u0003מנח להו\u0004 \u0005[היה מניח אותם]\u0006 ולא בקרקע, \u0003דאי סלקא דעתך אארעא מנח להו\u0004 \u0005[שאם עולה על דעתך\u0006 לומר \u0005שעל קרקע\u0006 העזרה \u0005מניח אותם],\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 שנינו לגבי מבנה המזבח: \u0003עלה אמה\u0004 בגובה \u0003וכנס אמה\u0004 ברוחב — \u0003זהו יסוד\u0004 המזבח. שוב \u0003עלה חמש\u0004 אמות בגובה \u0003וכנס אמה — זהו\u0004 ה\u0003סובב. עלה שלש\u0004 אמות נוספות — \u0003זהו מקום הקרנות.\u0004 נמצא אם כן, שגובהו הכולל של המזבח תשע אמות, ואם כן, שתהיינה הערבות הללו \u0003גוחות\u0004 (נשענות ונכפפות) \u0003על גבי המזבח היכי משכחת לה\u0004 \u0005[היאך יכול אתה למצוא אותה]\u0006 ובודאי מתוך שהיו הערבות צריכות לעמוד מעט באלכסון מפני הכניסות של היסוד והסובב כלפי פנים, ואם כן אין גובהן מספיק שתהיינה עוד נכפפות מלמעלה ונשענות על גבי המזבח! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי על ה\u0003יסוד מנח להו\u0004 \u0005[היה מניח אותם]\u0006 ובכך היתה נוספת לגובהם אמה זו של היסוד. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003אמר ר' אבהו: מאי קראה\u0004 \u0005[מה הכתוב]\u0006 המרמז על כך; \u0003שנאמר: \"אסרו חג בעבתים עד קרנות המזבח\"\u0004 (תהלים קיח, כז), לומר שבאילנות (\"עבותים\") היו מקיפים (\"אוסרים\") אף את קרנות המזבח, ודבר זה אינו שייך אלא באופן האמור. ועוד \u0003אמר ר' אבהו אמר ר' אלעזר: כל הנוטל לולב באגודו והדס בעבותו — מעלה עליו הכתוב כאילו בנה מזבח והקריב עליו קרבן, שנאמר:\u0004"],["\u0003\"אסרו חג בעבתים עד קרנות המזבח\",\u0004 שהוא רמז לאגודות שאוגדים את הלולב (\"אסרו חג\") וההדס (\"עבותים\"). \u0003אמר ר' ירמיה משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחי, ור' יוחנן\u0004 אמר דבר זה \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון המחוזי\u0004 שהוא אמרו \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוחנן המכותי: כל העושה איסור\u0004 (אגודה, תוספת) \u0003לחג\u0004 ביום שלאחריו \u0003באכילה ושתיה — מעלה עליו\u0004 מחשיב לו \u0003הכתוב כאילו בנה מזבח והקריב עליו קרבן, שנאמר: \"אסרו חג בעבתים עד קרנות המזבח\".\u0004","כיון שהזכרנו דברים שאמר ר' ירמיה משום ר' שמעון בן יוחאי, מביאים עוד דברים שנמסרו לנו בדרך זו. \u0003אמר חזקיה אמר ר' ירמיה משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחאי: כל המצות כולן אין אדם יוצא בהן אלא דרך גדילתן\u0004 כגון בנטילת לולב, שצריך להחזיקו כשקצהו התחתון פונה כלפי מטה, וכפי \u0003שנאמר\u0004 בענין קרשי המשכן: \u0003\"עצי שטים עמדים\"\u0004 (שמות כו, טו), להדגיש שאותם עצי השיטים אשר בנו בהם את המשכן היו עומדין בו כדרך גדילתם, ולא העמידום באופן אחר.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך];\u0006 נאמר: \u0003\"עצי שטים עמדים\" —\u0004 לומר \u0003שעומדים\u0004 במשכן \u0003דרך גדילתן\u0004 בטבע. \u0003דבר אחר: \"עומדין\"\u0004 פירושו \u0003שמעמידין את ציפוין,\u0004 כלומר שעצי השיטים היו מחזיקים את ציפוי הזהב שעליהם שהיה מחוזק במסמרים ונסמך על העץ. \u0003דבר אחר:\u0004 מה פירוש \u0003\"עומדין\"\u0004 — \u0003שמא תאמר אבד סיברם\u0004 (תקוותם) \u0003ובטל סכויין\u0004 לאחר שנחרב המשכן, ושוב לא ישמשו בקדושה, \u0003תלמוד לומר: \"עצי שטים עמדים\" — שעומדים לעולם ולעולמי עולמים\u0004 ועוד יתגלו לנו.","ועוד מסרו: \u0003ואמר חזקיה אמר ר' ירמיה משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחאי: יכול אני לפטור את כל העולם כולו מן הדין מיום שנבראתי עד עתה,\u0004 שבצדקתו ויסוריו הוא משמש הצדקה עבור העולם כולו \u0003ואילמלי\u0004 ואם יהיה \u0003אליעזר בני עמי\u0004 ויחשבו זכויותינו יחד, נוכל לפטור את העולם \u0003מיום שנברא העולם ועד עכשיו, ואילמלי\u0004 ואם יהיה המלך הצדיק \u0003יותם בן עוזיהו עמנו —\u0004 נוכל לפטור \u0003מיום שנברא העולם עד סופו\u0004 שצדקתם של אלה שקולה כנגד מעשי כל הדורות. והיא מצדיקה את קיומו של העולם.","\u0003ואמר חזקיה אמר ר' ירמיה משום ר' שמעון בן יוחאי: ראיתי בני עלייה\u0004 אנשי המעלה, הצדיקים האמיתיים \u0003והן מועטין, אם אלף הן — אני ובני מהן, אם מאה הם — אני ובני מהן, אם שנים הן — אני ובני הן.\u0004 ושואלים: \u0003ומי זוטרי כולי האי\u0004 \u0005[והאם מעטים הם כל כך]\u0006 בני העליה? והרי \u0003אמר רבא: תמני סרי אלפי דרא הוה דקמיה קודשא בריך הוא\u0004 \u0005[שמונה עשרה אלף הם בשורה שלפני הקדוש ברוך הוא],\u0006 \u0003שנאמר: \"סביב שמנה עשר אלף\"\u0004 (יחזקאל מח, לה), משמע שרבים הם הצדיקים העומדים במעלה! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 המספר המועט הוא של אלו \u0003דמסתכלי\u0004 \u0005[המסתכלים]\u0006 \u0003באספקלריא המאירה,\u0004 שבודאי מעטים הם, \u0003הא\u0004 \u0005[זה]\u0006 המספר הגדול הוא של אלו \u0003דלא מסתכלי\u0004 \u0005[שאינם מסתכלים]\u0006 \u0003באספקלריא המאירה\u0004 ורואים פני שכינה בהסתר פנים.","ועדיין שואלים: \u0003ודמסתכלי\u0004 \u0005[והמסתכלים]\u0006 \u0003באספקלריא המאירה, מי זוטרי כולי האי\u0004 \u0005[האם מעטים הם כל כך]?\u0006 \u0003והא\u0004 \u0005[הרי]\u0006 \u0003אמר אביי: לא פחות עלמא מתלתין ושיתא צדיקי דמקבלי אפי שכינה בכל יום\u0004 \u0005[אין העולם פחות\u0006 בכל דור \u0005משלשים וששה צדיקים המקבלים פני שכינה בכל יום],\u0006 \u0003שנאמר: \"אשרי כל חוכי לו\"\u0004 (ישעיה ל, יח) \u0003\"לו\" בגימטריא תלתין ושיתא הוו\u0004 \u0005[שלושים ושישה הם]\u0006 משמע שבכל דור יש לפחות שלשים וששה צדיקים גמורים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא דעיילי בבר\u0004 \u0005[אלו\u0006 שמרובים יותר הם \u0005הנכנסים\u0006 בבקשת \u0005רשות]\u0006 \u0003הא דעיילי בלא בר\u0004 \u0005[אלו שנכנסים בלא\u0006 בקשת \u0005רשות],\u0006 ואלה ששערי שמים פתוחים להם תמיד הם מעטים ביותר.","במשנה נאמר ש\u0003בשעת פטירתן\u0004 מן המזבח לאחר שהקיפוהו, היו משבחים ואומרים כמה דברים לגבי שבח המזבח ותהילה לה'. ותוהים: \u0003והא קא\u0004 \u0005[והרי על ידי כך]\u0006 \u0003משתתף שם שמים ודבר אחר\u0004 (המזבח). \u0003ו\u0004הרי \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל המשתף שם שמים ודבר אחר\u0004 כל שהוא \u0003נעקר מן העולם, שנאמר: \"\u0004זובח לאלהים יחרם \u0003בלתי לה' לבדו\"\u0004 (שמות כב, יט), להדגיש כי שום דבר אין לשתפו עם שם שמים! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לפרש את דברי שבחם: \u0003ליה אנחנו מודים\u0004 שהוא רבוננו \u0003ולך\u0004 (המזבח) \u0003אנחנו משבחים,\u0004 שאתה חביב לפניו לכפר עלינו, \u0003ליה אנחנו מודים ולך אנו מקלסין\u0004 (מהללים) ובאופן זה אין משתפים את המזבח עם ה' במדרגה אחת כלל.","שנינו במשנה: \u0003כמעשהו\u0004 בענין מצות הערבה \u0003בחול\u0004 כך מעשהו בשבת. ולדעת ר' יוחנן בן ברוקה היו ביום השביעי מביאים ענפי דקל (חריות). \u0003אמר רב הונא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוחנן בן ברוקה —\u0004 שנאמר: \"ולקחתם לכם ביום הראשון פרי עץ הדר \u0003כפת\u0004 תמרים\" (ויקרא כג, מ), \"כפות\" לשון רבים והם \u0003שנים: אחת ללולב ואחת למזבח. ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם סבורים כן \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003\"כפת\" כתיב\u0004 \u0005[נכתב]\u0006 והכתיב החסר בא ללמדנו שדי בכפת תמרים אחת והיא הלולב.","\u0003ר' לוי אומר:\u0004 טעמו של ר' יוחנן בן ברוקה אינו מן הכתובים אלא מנהג זה בא להראות שבח ישראל שהם \u0003כתמר, מה תמר זה אין לו אלא לב אחד\u0004 לפי שגזע התמר אינו מתפצל לענפים ומתמר ועולה למעלה \u0003אף ישראל אין להם אלא לב אחד — לאביהם שבשמים.\u0004","\u0003אמר רב יהודה אמר שמואל: לולב\u0004 מצותו \u0003שבעה\u0004 ימים ולכן מברכים עליו בכל יום מימי החג, ו\u0003סוכה\u0004 מצותה \u0003יום אחד\u0004 ולכן אין מברכים על ישיבתה, אלא ביום הראשון בלבד. \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 ומסבירים פשר דברים אלה: \u0003לולב דמפסקי\u0004 \u0005[שבו מופסקים]\u0006 ה\u0003לילות\u0004 מן ה\u0003ימים,\u0004 שהרי בלילה אין מצוה בלולב, אם כן \u0003כל יומא\u0004 \u0005[כל יום]\u0006 \u0003מצוה באפיה נפשיה\u0004 \u0005[בפני עצמה]\u0006 \u0003הוא\u0004 ונמצא שיש שבעה ימים מחולקים לקיום מצות לולב, ואילו \u0003סוכה דלא מפסקי\u0004 \u0005[שאין מופסקים בה]\u0006 ה\u0003לילות\u0004 מן ה\u0003ימים,\u0004 שמצות סוכה בלילה כביום, \u0003כולהו\u0004 \u0005[כל]\u0006 \u0003שבעה\u0004 ימים של החג \u0003כחד יומא אריכא דמו\u0004 \u0005[כיום אחד ארוך\u0006 הם \u0005נחשבים].\u0006","\u0003ורבה בר בר חנה אמר ר' יוחנן:\u0004 מצות \u0003סוכה שבעה\u0004 ימים ובכל יום מברך על ישיבתה, \u0003ולולב\u0004 מצותו \u0003יום אחד\u0004 בלבד, ולכן אינו מברך עליו אלא ביום הראשון בלבד. \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 כך יש להבין: \u0003סוכה דאורייתא\u0004 \u0005[\u0006שהיא \u0005מן התורה]\u0006 כל שבעת ימי החג — מברכים עליה כל \u0003שבעה,\u0004 ואילו \u0003לולב\u0004 שפרט ליום הראשון החובה ליטלו היא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 שתיקנו שיטלוהו כל שבעה לזכרון המקדש, \u0003סגי ליה\u0004 \u0005[די לו]\u0006 שיברכו עליו \u0003בחד יומא\u0004 \u0005[ביום אחד]\u0006 בלבד, ורק תקנת חכמים היא שיטלוהו שבעה ימים לזכרון המקדש.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אחד זה\u0004 סוכה \u0003ואחד זה\u0004 לולב, מברכים עליהם כל \u0003שבעה. אמר רב יוסף: נקוט\u0004 \u0005[החזק]\u0006 בזו שאמר \u0003רבה בר בר חנה בידך\u0004 \u0005[בידך]\u0006 \u0003דכולהו אמוראי\u0004 \u0005[שכל האמוראים]\u0006 שמסרו את דברי ר' יוחנן \u0003קיימי כוותיה\u0004 \u0005[מחזיקים כשיטתו]\u0006 \u0003בסוכה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בתוספתא:"],["\u0003העושה לולב לעצמו\u0004 (אבל לא לאחרים) בערב החג, \u0003אומר\u0004 בשעת עשייה: \u0003\"ברוך... שהחיינו וקיימנו והגיענו לזמן הזה\". נטלו לצאת בו\u0004 בתוך החג \u0003אומר: \"ברוך... אשר קדשנו במצותיו וצונו על נטילת לולב\". ואף על פי שבירך עליו\u0004 ברכה זו \u0003ביום ראשון — חוזר ומברך\u0004 עליו אותה ברכה \u0003כל שבעה\u0004 בזמן שנוטלו. \u0003העושה סוכה לעצמו אומר: \"ברוך... שהחיינו וקיימנו\u0004 והגיענו לזמן הזה \u0003\"\u0004. \u0003נכנס לישב בה אומר: \"\u0004ברוך... \u0003אשר קדשנו במצותיו וצונו לישב בסוכה\", וכיון שבירך יום ראשון שוב אינו מברך\u0004 בשאר הימים, שכל הימים נחשבים כיחידה אחת.","ומעתה \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003לולב\u0004 שבברייתא זו שמברכך עליו כל שבעה, על הדין שאמר רבה בר בר חנה בשם ר' יוחנן ב\u0003לולב\u0004 שמברך עליו יום ראשון בלבד, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003סוכה\u0004 שבברייתא זו שמברך עליה יום אחד בלבד, על הדין שאמר ר' יוחנן ב\u0003סוכה\u0004 שמברך עליה כל שבעה!","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי מדין \u0003לולב\u0004 על דין \u0003לולב לא קשיא\u0004 \u0005[קשה],\u0006 כי ניתן לומר: \u0003כאן\u0004 בברייתא שאמרו מברך עליו בכל יום הרי זה \u0003בזמן שבית המקדש קיים\u0004 שהרי מצותו במקדש כל שבעה, \u0003וכאן\u0004 שאמר ר' יוחנן שאינו מברך על הלולב אלא יום אחד בלבד, הוא \u0003בזמן שאין בית המקדש קיים. אלא\u0004 מדין \u0003סוכה\u0004 על דין \u0003סוכה קשיא\u0004 \u0005[קשה],\u0006 שלדברי ר' יוחנן משמע כי ישיבה בסוכה בשבעת ימי החג היא שבע מצות נפרדות, ומברייתא זו נראה שאינה אלא מצוה אחת בלבד!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 ולא בדין זה בלבד אלא בבעיה כוללת יותר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תפילין, כל זמן,\u0004 כלומר: כל פעם \u0003שמניחן — מברך עליהן\u0004 מחדש, אלו \u0003דברי רבי. וחכמים אומרים: אינו מברך אלא\u0004 פעם אחת ביום, ב\u0003שחרית בלבד.\u0004 ונראה כי אף בסוכה נחלקו אם מברך בכל פעם שבא לקיים את המצוה, או שמברך בפעם הראשונה שחלה עליו המצוה, ושוב אינו מוסיף לברך.","בענין תפילין \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בהלכה; \u0003אביי אמר: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כ\u0004שיטת \u0003רבי, ורבא אמר: הלכתא כרבנן\u0004 \u0005[הלכה כ\u0006שיטת \u0005חכמים],\u0006 שאין מברך אלא שחרית. \u0003אמר רב מרי ברה דבת\u0004 \u0005[בנה של בתו]\u0006 של \u0003שמואל: חזינא ליה לרבא דלא עביד כשמעתיה\u0004 \u0005[ראיתי את רבא שאינו נוהג כשיטתו]\u0006 שמברכים רק פעם אחת, \u0003אלא מקדים וקאי ועייל\u0004 \u0005[ועומד ונכנס]\u0006 \u0003לבית הכסא ונפיק ומשי ידיה\u0004 \u0005[ויוצא ורוחץ ידיו]\u0006 \u0003ומנח\u0004 \u0005[ומניח]\u0006 \u0003תפילין ומברך\u0004 עליהן, \u0003וכי איצטריך זמנא אחרינא\u0004 \u0005[וכאשר הוא נזקק פעם אחרת]\u0006 לצרכיו \u0003עייל\u0004 \u0005[הריהו נכנס]\u0006 \u0003לבית הכסא ונפיק ומשי ידיה\u0004 \u0005[ויוצא ורוחץ ידיו]\u0006 \u0003ומנח\u0004 \u0005[ומניח]\u0006 \u0003תפילין ומברך, ואנן נמי\u0004 \u0005[ואנחנו גם כן]\u0006 בדין סוכה \u0003כ\u0004שיטת \u0003רבי עבדינן\u0004 \u0005[אנו עושים],\u0006 \u0003ומברכין כל שבעה\u0004 ימים.","ועוד בענין תפילין \u0003אמר מר זוטרא: חזינא ליה\u0004 \u0005[ראיתי]\u0006 את \u0003רב פפי, דכל אימת דמנח\u0004 \u0005[שבכל פעם\u0006 שהיה \u0005מניח]\u0006 \u0003תפילין\u0004 היה \u0003מברך\u0004 ברכה חדשה. \u0003רבנן דבי\u0004 \u0005[חכמים של בית\u0006 מדרשו\u0005]\u0006 של \u0003רב אשי, כל אימת דמשמשי בהו מברכי\u0004 \u0005[כל פעם שהיו ממשמשים בהם\u0006 בתפילין \u0005היו מברכים].\u0006","א \u0003אמר רב יהודה אמר שמואל: מצות לולב\u0004 לענין ברכה, היא \u0003כל שבעה\u0004 ימים של החג. \u0003ור' יהושע בן לוי אמר: יום ראשון\u0004 של החג — \u0003מצות לולב\u0004 מן התורה וצריכה ברכה. \u0003מכאן ואילך —\u0004 אינה אלא \u0003מצות זקנים,\u0004 כלומר: תקנת חכמים היא, זכר למקדש ואינה צריכה ברכה. \u0003ור' יצחק אמר: כל יומא\u0004 \u0005[יום]\u0006 מחג הסוכות \u0003מצות זקנים.\u0004 ותוהים: \u0003ואפילו יום ראשון?! והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 שמצות נטילת לולב ב\u0003יום\u0004 ה\u0003ראשון\u0004 היא \u0003דאורייתא\u0004 \u0005[מן התורה]!\u0006 ומתקנים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מיום ראשון.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש \u0005—\u0006 \u0003היינו\u0004 \u0005[הרי זו\u0006 בדיוק\u0005]\u0006 שיטתו של \u0003ר' יהושע בן לוי!\u0004 ומתרצים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן בלשון: \u0003וכן אמר ר' יצחק,\u0004 כדברי ר' יהושע בן לוי.","ומעירים, \u0003ואף רב סבר: כל שבעה מצות לולב\u0004 וחובה לברך עליה כל שבעת הימים, אף על פי שחוץ מן היום הראשון אינה מן התורה. ש\u0003אמר ר' חייא בר אשי אמר רב\u0004 בענין דומה: \u0003המדליק נר של חנוכה,\u0004 אף על פי שאינו אלא מדברי סופרים — \u0003צריך לברך. ר' ירמיה אמר: הרואה נר של חנוכה,\u0004 אף על פי שלא הדליק בעצמו — \u0003צריך לברך.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מברך? אמר רב יהודה: ביום הראשון המדליק מברך שלש\u0004 ברכות (\"להדליק נר של חנוכה\", \"שעשה נסים\", \"שהחיינו\"); ואילו \u0003הרואה\u0004 אינו \u0003מברך\u0004 אלא \u0003שתים\u0004 (\"שעשה נסים\", \"שהחיינו\"), \u0003מכאן ואילך,\u0004 מיום השני והלאה, \u0003המדליק\u0004 את הנרות \u0003מברך שתים\u0004 (\"להדליק נר של חנוכה\", \"שעשה נסים\"), \u0003והרואה מברך אחת\u0004 (\"שעשה נסים\").","\u0003ומאי\u0004 \u0005[ומה]\u0006 הוא נוסח הברכה ש\u0003מברך\u0004 על הדלקת הנרות: \u0003\"ברוך... אשר קדשנו במצותיו וצונו להדליק נר של חנוכה\".\u0004 על לשון הברכה שואלים: \u0003והיכן צונו\u0004 דבר זה? שהרי הדלקת נרות חנוכה ודאי לא נצטוינו עליה בתורה! ומשיבים: ממה שנאמר: \"ובאת אל הכהנים הלוים ואל השופט אשר יהיה בימים ההם ודרשת והגידו לך את דבר המשפט. ועשית על פי הדבר אשר יגידו לך מן המקום ההוא אשר יבחר ה' ושמרת לעשות ככל אשר יורוך. על פי התורה אשר יורוך ועל המשפט אשר יאמרו לך תעשה \u0003לא תסור\u0004 מן הדבר אשר יגידו לך ימין ושמאל\" (דברים יז, ט-יא). \u0003ורב נחמן בר יצחק אמר\u0004 שלמדים את הדבר ממה שנאמר \u0003\"שאל אביך ויגדך\u0004 זקניך ויאמרו לך\u0003\"\u0004 (דברים לב, ז), וכל המקיים דברי חכמים — מקיים מצוות אלה שבתורה.","ומבררים: \u0003מאי\u0004 \u0005[מה,\u0006 איזה ברכה\u0005]\u0006 הריהו \u0003ממעט\u0004 מיום שני של חנוכה והלאה? — ממעט ברכת \u0003זמן\u0004 (\"שהחיינו\") שאומרים רק פעם ביום הראשון. ושואלים: \u0003אימא ממעט\u0004 \u0005[אמור שימעט]\u0006 את ברכת ה\u0003נס\u0004 \"שעשה נסים\")? ומשיבים הלא \u0003נס כל יומא איתיה\u0004 \u0005[בכל יום ישנו].\u0006 על כל פנים מדברי רב למדנו שמברכים גם על מצוה שמדברי חכמים בלבד וכן אם כן הדין גם בלולב כל שבעה. \u0003רב נחמן בר יצחק מתני לה בהדיא\u0004 \u0005[היה שונה\u0006 הלכה \u0005זו במישרין]\u0006 ולא הוצרך ללמדה בעקיפין מדבר אחר, ש\u0003אמר רב: כל שבעה מצות לולב\u0004 לענין ברכה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003העושה סוכה לעצמו, אומר: \"ברוך... שהחיינו\u0004 וקיימנו והגיענו לזמן הזה\u0003\". נכנס לישב בה, אומר: \"ברוך... אשר קדשנו\u0004 במצוותיו וציונו לישב בסוכה\u0003\". היתה\u0004 הסוכה \u0003עשויה\u0004 כבר \u0003ועומדת\u0004 מקודם, שלא נעשתה לשם מצוה, \u0003אם יכול לחדש בה דבר\u0004 בבניינה לשם מצות סוכה, הריהו \u0003מברך\u0004 \"שהחיינו\", \u0003ואם לאו — לכשיכנס לישב בה\u0004 בסוכות \u0003מברך שתים:\u0004 \"לישב בסוכה\", ו\"שהחיינו\". \u0003אמר רב אשי: חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רב כהנא דקאמר להו לכולהו אכסא דקדושא\u0004 \u0005[שהיה אומר את כולן\u0006 את כל הברכות הללו \u0005על כוס הקידוש];\u0006 \"שהחיינו\" ו\"לישב בסוכה\".","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היו לפניו מצות הרבה, אומר: ברוך... אשר קדשנו במצותיו וצונו על המצות. ר' יהודה אומר: מברך על כל אחת ואחת בפני עצמה. אמר ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חנינא בר פפא: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' יהודה. ואמר ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חנינא בר פפא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ברוך ה' יום יום\"\u0004 (תהלים סח, כ), ועל לשון הכתוב יש לשאול \u0003וכי ביום\u0004 בלבד \u0003מברכין אותו, ובלילה אין מברכין אותו?\u0004 ואם כן, מה משמעות לשון \"יום יום\"? \u0003אלא בא\u0004 הכתוב \u0003לומר לך: בכל יום ויום תן לו מעין ברכותיו,\u0004 שבכל יום מימות החול יש לברך בנוסח המתאים לימות החול, אם נתחדש דבר ביום זה (כגון שהוא שבת, או חג, או נתחדשה בו מצוה) יש לברכו בברכה אשר נוסחה מתאים לאותו יום או מאורע, \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 — \u0003בכל דבר ודבר תן לו מעין ברכותיו\u0004 המיוחדות לו, ואל תצרף את הברכות כולן.","כיון שהזכרנו שלשלת מסורת זו, מביאים עוד ממה ש\u0003אמר ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חנינא בר פפא: בא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם; מדת בשר ודם — כלי ריקן\u0004"],["\u0003מחזיק\u0004 (מכיל) את מה ששמים בו, ואילו כלי \u0003מלא\u0004 — \u0003אינו מחזיק,\u0004 שאי אפשר להוסיף על תוכנו. \u0003אבל מדת הקדוש ברוך הוא\u0004 הפוכה מזו: כלי \u0003מלא,\u0004 כלומר: אדם שיודע ולמד — \u0003מחזיק\u0004 תוכן נוסף, ואילו כלי \u0003ריקן\u0004 אדם שתוכנו ריק — \u0003אינו מחזיק, שנאמר: \"והיה אם שמוע תשמע\"\u0004 (דברים כח, א) לומר: \u0003\"אם שמוע\",\u0004 כלומר, אם שמעת כבר — \u0003\"תשמע\"\u0004 גם בעתיד. \u0003ואם לאו — לא תשמע\u0004 אף בעתיד. \u0003דבר אחר: \"אם שמוע\" בישן\u0004 כלומר: שאתה חוזר על לימודך בעבר \u0003— \"תשמע\"\u0004 גם \u0003בחדש, \"ואם יפנה לבבך\"\u0004 מלחזור על מה שלמדת בעבר (דברים ל, יז) — \u0003שוב \"\u0004ו\u0003לא תשמע\"\u0004 יותר ללמוד ולהבין בעתיד (דברים ל, יז).","שנינו במשנה כי \u0003מיד\u0004 לאחר נטילת הלולב, היו ה\u0003תינוקות\u0004 שומטין את לולביהם ואוכלים אתרוגיהם. \u0003אמר ר' יוחנן: אתרוג בשביעי\u0004 של חג הסוכות — \u0003אסור\u0004 ליהנות ממנו, וביום \u0003השמיני — מותר. סוכה\u0004 — \u0003אפילו\u0004 ביום \u0003השמיני, אסורה\u0004 בהנאה. \u0003וריש לקיש אמר: אתרוג אפילו בשביעי\u0004 מיד לאחר קיום המצוה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מותר.\u0004","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה נחלקו]\u0006 מה הוא יסוד מחלוקתם? \u0003מר\u0004 \u0005[חכם זה,\u0006 ריש לקיש\u0005]\u0006 \u0003סבר: למצותה אתקצאי\u0004 \u0005[הוקצתה]\u0006 הסוכה או ארבעת המינים וכיון שכבר קיים את המצוה ממילא בטל איסור הנאה, ואין איפוא מניעה הלכתית באכילת האתרוג. \u0003ומר\u0004 \u0005[וחכם זה\u0006 ר' יוחנן\u0005]\u0006 \u0003סבר: לכולי יומא אתקצאי\u0004 \u0005[לכל היום הוקצתה]\u0006 ולכן אסור האתרוג בהנאה בכל היום השביעי, אף לאחר שקיים מצוותו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 ממה ששנינו במשנתנו: \u0003מיד תינוקות שומטין את לולביהן ואוכלין\u0004 את \u0003אתרוגיהן. מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003הוא הדין לגדולים,\u0004 שאף הם מותרין בכך, והרי שמותר האתרוג בהנאה מיד לאחר קיום המצוה! ודחה ר' יוחנן: \u0003לא, תינוקות דוקא\u0004 אמרו, שלא היו חייבים מן התורה במצות לולב ולא הוקצה לולבם למצוה ממש, אבל גדולים שחייבים במצוה מן התורה, הוקצה לולבם למצוה ולכך אסורים באכילתו.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בסגנון אחר: \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש;\u0004 שנינו: \u0003מיד תינוקות שומטין את לולביהן ואוכלין\u0004 את \u0003אתרוגיהן.\u0004 ומלשון המשנה נדייק כי רק \u0003תינוקות אין\u0004 \u0005[כך],\u0006 אבל \u0003גדולים לא,\u0004 משמע שלגדולים אסור! והשיב ריש לקיש: \u0003הוא הדין אפילו גדולים\u0004 מותרים לאכול אתרוגיהם, \u0003והאי דקתני\u0004 \u0005[ומה ששנה]\u0006 \u0003תינוקות\u0004 — \u0003אורחא דמלתא קתני\u0004 \u0005[מנהג הדברים שנה],\u0006 שהתינוקות משתעשעים בכך, אבל מותר גם לגדולים.","\u0003אמר ליה רב פפא לאביי: לר' יוחנן\u0004 המחלק בין אתרוג לסוכה לענין היתר הנאה ביום השמיני, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 ה\u0003סוכה מאי שנא\u0004 \u0005[\u0006ו\u0005במה שונה]\u0006 ה\u0003אתרוג?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 זה טעם ההבדל, \u0003סוכה דחזיא\u0004 \u0005[שהיא ראויה]\u0006 אף \u0003ל\u0004שעת \u0003בין השמשות\u0004 של סוף יום השביעי, \u0003דאי איתרמי ליה סעודתא בעי מיתב בגוה ומיכל בגוה\u0004 \u0005[שאם תזדמן לו סעודה\u0006 בסוף היום \u0005צריך לשבת בתוכה ולאכול בתוכה],\u0006 ולכך \u0003אתקצאי\u0004 \u0005[הוקצתה]\u0006 למצוה \u0003לבין השמשות, ומיגו דאתקצאי\u0004 \u0005[ומתוך שהוקצה]\u0006 \u0003לבין השמשות אתקצאי לכולי יומא דשמיני\u0004 \u0005[הוקצתה גם כן לכל יום השמיני],\u0006 שהרי בין השמשות הוא ספק התחלת היום השמיני, וכיון שנאסר בתחילתו שוב אין דרך להתירו. ואילו \u0003אתרוג דלא חזי\u0004 \u0005[שאינו ראוי]\u0006 \u0003לבין השמשות,\u0004 שהרי כבר עשו בו מצותו — \u0003לא אתקצאי\u0004 \u0005[הוקצה]\u0006 \u0003לבין השמשות,\u0004 וכיון שלא הוקצה אז, \u0003לא אתקצאי\u0004 \u0005[הוקצה]\u0006 \u0003לכולי יומא דשמיני\u0004 \u0005[לכל היום השמיני].\u0006","\u0003ולוי אמר\u0004 דעה אחרת: \u0003אתרוג אפילו בשמיני אסור, ואבוה\u0004 \u0005[ואביו]\u0006 של \u0003שמואל אמר: אתרוג בשביעי — אסור, בשמיני — מותר.\u0004 ומעירים: בסופו של דבר \u0003קם אבוה\u0004 \u0005[עמד אביו]\u0006 של \u0003שמואל בשיטתיה\u0004 \u0005[בשיטתו]\u0006 של \u0003לוי,\u0004 שחזר מדבריו וקיבל את דברי לוי, ו\u0003קם\u0004 \u0005[ועמד]\u0006 \u0003ר' זירא בשיטתיה דאבוה\u0004 \u0005[בשיטתו של אביו]\u0006 של \u0003שמואל.\u0004 ש\u0003אמר ר' זירא: אתרוג\u0004 אף על פי \u0003שנפסלה\u0004 מכל טעם שהוא — \u0003אסור לאוכלה כל שבעה,\u0004 שכן הוקצה האתרוג למצוה עד סוף החג.","\u0003אמר ר' זירא: לא ליקני איניש הושענא לינוקא ביומא טבא קמא\u0004 \u0005[שלא יקנה אדם\u0006 במתנה \u0005את ארבעת המינים לתינוק ביום טוב הראשון].\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 כיון \u0003דינוקא מקנא קני אקנויי לא מקני\u0004 \u0005[שהתינוק לקנות קונה,\u0006 אבל \u0005להקנות אינו מקנה],\u0006 שיכול הקטן לזכות בדבר הניתן לו, אבל אין בו דעת מבחינה הלכתית ומשפטית כדי להקנות. ואם נותן לתינוק לפני שיצא בו, גם אם התינוק מקנה לו בחזרה את הלולב, הרי \u0003אשתכח דקא נפיק\u0004 \u0005[נמצא שהוא יוצא]\u0006 \u0003בלולב שאינו שלו.\u0004","אגב כך \u0003אמר ר' זירא: לא לימא איניש לינוקא \"דיהיבנא לך מידי\" ולא יהיב ליה\u0004 \u0005[יאמר אדם לתינוק \"אתן לך דבר\" ואינו נותן לו],\u0006 \u0003משום דאתי לאגמוריה שיקרא\u0004 \u0005[שעשוי\u0006 על ידי כך \u0005ללמדו שקר],\u0006 \u0003שנאמר: \"למדו לשונם דבר שקר\"\u0004 (ירמיה ט, ד) וצריך להזהר שלא להרגיל ילד לומר דבר ולחזור בו.","עתה שבים למחלוקתם של ר' יוחנן וריש לקיש בענין היתר הנאה באתרוג ביום השביעי, ומעירים: \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 זו של \u0003ר' יוחנן ור' שמעון בן לקיש,\u0004 נחלקו גם אמוראים אחרים. \u0003דאיתמר\u0004 \u0005[שנאמר],\u0006 שנחלקו בבעיה הבאה: \u0003הפריש שבעה אתרוגין\u0004 שונים \u0003לשבעה ימים\u0004 של החג, \u0003אמר רב: כל אחת ואחת יוצא בה ואוכלה לאלתר\u0004 \u0005[מיד],\u0006 \u0003ורב אסי אמר: כל אחת ואחת יוצא בה ואוכלה למחר.\u0004 ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה נחלקו]\u0006 מה יסוד מחלוקתם? \u0003מר\u0004 \u0005[חכם\u0006 זה, רב\u0005]\u0006 \u0003סבר: למצותה אתקצאי\u0004 \u0005[הוקצתה]\u0006 ומיד עם סיום קיום המצוה אין בכך איסור הנאה. \u0003ומר\u0004 \u0005[וחכם זה\u0006 רב אסי\u0005]\u0006 \u0003סבר: לכולי יומא אתקצאי\u0004 \u0005[לכל היום הוקצתה],\u0006 ולכך אף לאחר קיום המצוה, עדיין האתרוג אסור בהנאה עד סוף היום.","ושואלים: \u0003ואנן דאית לן תרי יומי\u0004 \u0005[ואנו\u0006 בחוץ לארץ \u0005שיש לנו שני ימים\u0006 של חג\u0005]\u0006 ראשון ואחרון ויום שמיני של חג אף הוא ספק שביעי, וחייב במצוות חג הסוכות, \u0003היכי עבדינן\u0004 \u0005[כיצד אנו עושים]\u0006 לענין היתר הנאה? \u0003אמר אביי: שמיני\u0004 של חג שהוא \u0003ספק שביעי\u0004 — \u0003אסור,\u0004 שהרי מספק עדיין יש בו מקדושת חג הסוכות, ואילו ביום ה\u0003תשיעי\u0004 שהוא \u0003ספק שמיני —\u0004 בודאי \u0003מותר. מרימר אמר: אפילו שמיני\u0004 שהוא \u0003ספק שביעי — מותר,\u0004 שכיון שהוא גם יום ראשון של שמיני עצרת אין אומרים שחלה עליו מספק קדושת חג הסוכות.","ומעירים: \u0003בסורא עבדי\u0004 \u0005[היו עושים]\u0006 \u0003כ\u0004דעת \u0003מרימר,\u0004 שביום השמיני מיד היו מורים היתר הנאה באתרוג, \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי עביד\u0004 \u0005[היה עושה]\u0006 \u0003כ\u0004שיטת \u0003אביי\u0004 בענין זה. ומעירים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כאביי.\u0004","כיון שהזכרנו את בעיית שמיני עצרת שהוא ספק שביעי של חג הסוכות בחוץ לארץ, \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 יום ה\u0003שמיני\u0004 של חג הסוכות שהוא בחוץ לארץ \u0003ספק שביעי,\u0004 נוהגים בו כאילו היה יום ה\u0003שביעי\u0004 לענין \u0003סוכה\u0004 ויום \u0003שמיני\u0004 לענין \u0003ברכה\u0004 שמזכירים בברכה ובתפילה שהוא יום שמיני עצרת. \u0003ור' יוחנן אמר: שמיני לזה ולזה.\u0004 ומסבירים: \u0003מיתב כולי עלמא לא פליגי דיתבינן\u0004 \u0005[לשבת\u0006 בסוכה \u0005הכל אינם חולקים שיושבים],\u0006 שגם לדעת ר' יוחנן יש לשבת בסוכה בשמיני ספק שביעי, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה"],["\u0003לברוכי\u0004 \u0005[ל\u0006ענין \u0005לברך]\u0006 על הישיבה בסוכה. \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר\u0004 שיום שמיני דינו \u0003כשביעי לסוכה — ברוכי נמי מברכינן\u0004 \u0005[לברך גם כן מברכים אנו]\u0006 \"לישב בסוכה\", אולם \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר\u0004 כי יום זה נחשב כ\u0003שמיני לזה ולזה,\u0004 לסוכה ולברכה — \u0003ברוכי לא מברכינן\u0004 \u0005[לברך אינו מברך].\u0006 \u0003אמר רב יוסף: נקוט\u0004 \u0005[החזק]\u0006 בהלכה זו של \u0003ר' יוחנן בידך\u0004 שאין מברכים \"לישב בסוכה\" בחוץ לארץ ביום השמיני, ונהג כן להלכה, שכן \u0003רב הונא בר ביזנא וכל גדולי הדור איקלעו\u0004 \u0005[נזדמנו]\u0006 \u0003בסוכה בשמיני\u0004 שהוא \u0003ספק שביעי, מיתב הוו יתבי\u0004 \u0005[לשבת היו יושבים]\u0006 בסוכה, אך \u0003ברוכי לא בריכי\u0004 \u0005[לברך לא ברכו].\u0006","ושואלים: \u0003ודלמא סבירא להו כמאן\u0004 \u0005[ושמא סבורים הם כמי]\u0006 ש\u0003אמר: כיון שבירך יום טוב ראשון שוב אינו מברך,\u0004 ושמא מטעם זה לא ברכו ולא מפני שהוא יום השמיני? ומשיבים: \u0003גמירי דמאפר אתו\u0004 \u0005[למודים אנו\u0006 במסורת \u0005שמן השדה\u0006 הם \u0005באו],\u0006 ששהו במרעה עם בהמותיהם ולא ישבו בסוכה כל ימות החג.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בנוסח אחר: \u0003ברוכי\u0004 \u0005[לברך] —\u0006 \u0003כולי עלמא לא פליגי דלא מברכינן\u0004 \u0005[הכל אינם חולקים שאין מברכים],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה לענין \u0003למיתב\u0004 \u0005[לשבת]\u0006 בסוכה. \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר\u0004 כי יום השמיני הוא \u0003כשבעה לסוכה\u0004 — \u0003מיתב יתבינן\u0004 \u0005[לשבת יושבים אנו],\u0006 \u0003ולמאן\u0004 \u0005[ול\u0006דעת \u0005מי]\u0006 ש\u0003אמר\u0004 כי יום השמיני הוא כ\u0003שמיני לזה ולזה — מיתב נמי לא יתבינן\u0004 \u0005[לשבת גם כן אין אנו יושבים].\u0006 \u0003אמר רב יוסף: נקוט\u0004 \u0005[החזק]\u0006 בדבריו של \u0003ר' יוחנן בידך\u0004 \u0005[בידך],\u0006 \u0003דמרא דשמעתא מני\u0004 \u0005[שבעלה של הלכה\u0006 זו \u0005מי הוא],\u0006 כלומר מי הוא שהביא עיקרה של הלכה זו — \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת,\u0004 והוא עצמו \u0003בשמיני ספק שביעי לבר\u0004 [מחוץ] ל\u0003סוכה יתיב\u0004 \u0005[היה יושב].\u0006 ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]\u0006 למעשה: \u0003מיתב יתבינן\u0004 \u0005[לשבת יושבים אנו]\u0006 בסוכה בשמיני ספק שביעי, אולם \u0003ברוכי לא מברכינן\u0004 \u0005[לברך\u0006 \"לישב בסוכה\", \u0005אין אנו מברכים].\u0006","\u0003אמר ר' יוחנן: אומרים זמן\u0004 (ברכת \"שהחיינו\") ביום ה\u0003שמיני של חג\u0004 הסוכות, שהוא חג בפני עצמו, \u0003ואין אומרים זמן בשביעי של פסח,\u0004 שאינו חג בפני עצמו.","\u0003ואמר ר' לוי בר חמא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' חמא בר חנינא: תדע\u0004 שהיום השמיני של חג הסוכות הוא חג בפני עצמו וראוי לפיכך לברכה לעצמו, \u0003שהרי חלוק\u0004 הוא \u0003בשלושה דברים\u0004 משבעת ימי חג הסוכות, ואלו הם: \u0003בסוכה\u0004 — שאין יושבים בו, וב\u0003לולב\u0004 — שאין נוטלים בו, וב\u0003ניסוך המים\u0004 — שאין מנסכים בו עוד. ומעירים: ואף לדעת \u0003ר' יהודה\u0004 ש\u0003אמר: בלוג היה מנסך\u0004 את המים \u0003כל שמונה\u0004 ימים ומשמע אף בשמיני של חג, \u0003הרי\u0004 עדיין \u0003חלוק\u0004 היום השמיני לפחות \u0003בשני דברים\u0004 מן הימים הקודמים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003שביעי של פסח נמי\u0004 \u0005[גם כן]\u0006 \u0003הרי חלוק\u0004 מיום החג הראשון של פסח לענין חובת \u0003אכילת מצה.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003לילה הראשונה\u0004 של פסח — \u0003חובה\u0004 היא לאכול מצה, \u0003מכאן ואילך — רשות.\u0004 אם רוצה — אוכל מצה, ואם לאו — אוכל מה שירצה, ובלבד שלא יאכל חמץ. ותוהים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 היום האחרון \u0003מלילה\u0004 הראשון הוא \u0003חלוק\u0004 בדינו, אולם אף \u0003מיום\u0004 הראשון עצמו \u0003אינו חלוק,\u0004 שהרי אף ביום הראשון אין חובת אכילת מצה, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בשמיני של חג \u0003אפילו מיום נמי\u0004 \u0005[גם כן]\u0006 \u0003חלוק.\u0004","\u0003רבינא אמר\u0004 טעם אחר: \u0003זה,\u0004 שמיני של חג \u0003חלוק משלפניו\u0004 אף מהיום שלפניו, שהרי שונים דיני שמיני של חג מהשביעי בו, \u0003וזה\u0004 שביעי של פסח \u0003חלוק משלפני פניו\u0004 מן היום הראשון בלבד, ואילו משלפניו שהוא היום השישי אינו חלוק כלל.","\u0003רב פפא אמר\u0004 טעם אחר: \u0003הכא כתיב\u0004 \u0005[כאן\u0006 בשמיני עצרת \u0005נאמר]\u0006 \u0003\"פר\",\u0004 שלמוסף יום השמיני אין מקריבים אלא פר אחד (במדבר כט, לו), \u0003התם כתיב\u0004 \u0005[שם\u0006 בימי חג הסוכות \u0005נאמר]\u0006 \u0003\"פרים\",\u0004 שבכל ימי חג הסוכות מקריבים למוסף פרים רבים בסדר יורד, כשביום הראשון קרבים שלושה עשר פרים ובכל יום פוחת והולך עד שביום השביעי קרבים שבעה פרים בלבד, ואם אכן היה היום השמיני המשכו של חג הסוכות, היו צריכים להיות קרבים בו ששה פרים, ומתוך שנשתנה דינו ואין קרב בו אלא פר אחד, הרי שאינו אלא חג לעצמו.","\u0003רב נחמן בר יצחק אמר: הכא\u0004 \u0005[כאן]\u0006 בשמיני של חג \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ביום\u0004 השמיני עצרת תהיה לכם כל מלאכת עבודה לא תעשו\u0003\"\u0004 (במדבר כט, לה), לומר שהוא ענין חדש לעצמו, ואילו \u0003התם\u0004 \u0005[שם]\u0006 בשאר ימים \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וביום\"\u0004 (השני, השלישי... השביעי) ב-ו' החיבור, משמע שכל שבעת הימים הראשונים שייכים זה לזה.","\u0003רב אשי אמר\u0004 טעם אחר: \u0003הכא\u0004 \u0005[כאן]\u0006 בשמיני של חג \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"\u0004מנחתם ונסכיהם לפר לאיל ולכבשים במספרם \u0003כמשפט\"\u0004 (במדבר כט, לז), ואילו \u0003התם\u0004 \u0005[שם]\u0006 בימי סוכות \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"\u0004מנחתם ונסכיהם לפרים לאילים ולכבשים במספרם \u0003כמשפטם\"\u0004 (במדבר כט, לד), משמע: כמשפטם של שאר הימים, ללמד שכל שבעת הימים מתייחסים וקשורים זה לזה.","ומעירים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 לר' יוחנן בשיטתו בענין חיוב ברכת \"שהחיינו\" ביום השמיני, ממה ששנינו: \u0003הפרים האילים והכבשים\u0004 שמביאים בחג, כולם \u0003מעכבין זה את זה,\u0004 שכולם נחשבים כקרבן אחד, ואם חסר אחד מן המינים אין מקריבים את השאר לחוד. \u0003ור' יהודה אומר: פרים אין מעכבין זה את זה שהרי מתמעטין והולכין\u0004 מיום ליום, שהרי ביום הראשון מקריבים שלושה עשר פרים ומספרם מתמעט והולך עד לשבעה ביום השביעי. ומתוך שלא הקפיד הכתוב שיהיה מספרם זהה בכל הימים, אף לא הקפיד שיבואו כולם כאחד.","\u0003אמרו לו:\u0004 מכאן אין להוכיח, \u0003והלא כולן\u0004 אף הכבשים ואילים \u0003מתמעטין והולכין בשמיני,\u0004 שכן בכל הימים מקריבים שני אילים וארבעה עשר כבשים ואילו בשמיני מקריבים איל אחד ושבעה כבשים בלבד! \u0003אמר להן: שמיני רגל\u0004 (חג) \u0003בפני עצמו הוא\u0004 ואינו קשור לשבעת ימי הסוכות. \u0003שכשם ששבעת ימי החג טעונין קרבן\u0004 מיוחד \u0003ושיר\u0004 מיוחד של חג המושר בפי הלויים \u0003וברכה\u0004 מיוחדת ויש בהם מצוה של \u0003לינה\u0004 בירושלים במוצאי החג, \u0003אף שמיני טעון קרבן\u0004 מיוחד שאינו מסדר קרבנות החג \u0003ושיר\u0004 לעצמו \u0003וברכה\u0004 המיוחדת לו \u0003ולינה.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 שברכה זו היא ברכת \u0003זמן\u0004 (\"שהחיינו\")? ודוחים: \u0003לא,\u0004 הכוונה היא ל\u0003ברכת המזון ותפלה\u0004 שמזכירים בהם במפורש \"יום שמיני עצרת\" שלא כנוסח המקובל בשאר ימי חג הסוכות, ואין איפוא להוכיח מכאן.","ואומרים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 שזה פירוש הדברים בברייתא, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 שהכוונה היתה לברכת \"שהחיינו\", ברכה זו של \u0003זמן\u0004 (\"שהחיינו\") \u0003כל שבעה מי איכא\u0004 \u0005[האם יש]?\u0006 שהרי אין מברכים \"שהחיינו\" אלא ביום הראשון בלבד! ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]\u0006 ואין להוכיח מכך דבר, שכן אפשר לומר: \u0003דאי לא בריך האידנא\u0004 \u0005[שאם לא ברך עכשיו]\u0006 ביום הראשון — \u0003מברך למחר, או ליומא אחרינא\u0004 \u0005[ליום אחר]\u0006 בכל יום אחר מימי חג הסוכות, שכל עוד לא ברך \"שהחיינו\", עדיין חלה עליו חובה זו בכל אחד מימי החג.","ושואלים: אולם כיצד ייתכן שיוכל לברך \"שהחיינו\" בכל יום מימי חג סוכות, הלא \u0003מכל מקום כוס\u0004 יין \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לצרף ברכת \"שהחיינו\" לברכה על הכוס, ודבר זה אינו מצוי תמיד בימי חול המועד! ומאחר ולא השתמשו חכמים בנימוק זה \u0003לימא מסייע ליה\u0004 \u0005[האם לומר שהדבר מסייע לו]\u0006 \u0003ל\u0004דעת \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן: זמן\u0004 (ברכת \"שהחיינו\") \u0003אומרו אפילו בשוק\u0004 ואינו זקוק לצרפו לענין אחר. \u0003דאי אמרת בעינן\u0004 \u0005[שאם אומר אתה\u0006 ש\u0005צריכים אנו]\u0006 \u0003כוס\u0004 לברכה זו — \u0003כוס\u0004 של יין האם \u0003כל יומא מי איכא\u0004 \u0005[בכל יום היא מצויה]\u0006 שיוכל לברך בכל יום מימי חול המועד? ודוחים: מכאן אין ראיה, \u0003דלמא דאיקלע ליה\u0004 \u0005[שמא שנזדמנה לו]\u0006 \u0003כוס\u0004 של יין, שהרי אין מדובר בדרך קיום המצוה לכתחילה, אלא באפשרות בלבד.","ביחס לדברי ר' יהודה כי כשם שקיימת חובה להשאר ללון בירושלים במוצאי יום טוב ראשון של סוכות, כך קיימת חובה זו גם לגבי מוצאי שמיני עצרת, שואלים : \u0003ו\u0004כי \u0003סבר ר' יהודה\u0004 כי מוצאי \u0003שמיני\u0004 של חג \u0003טעון לינה\u0004 בירושלים? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר: מנין לפסח שני,\u0004 שבו מקריב את הפסח מי שהיה טמא בפסח ראשון ולא יכול היה להקריבו, \u0003שאינו טעון לינה\u0004 אחריו — \u0003שנאמר\u0004 בפסח ראשון: \u0003\"ופנית בבקר והלכת לאהליך\"\u0004 (דברים טז, ז) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך: \u0003\"ששת ימים תאכל מצות\"\u0004 (דברים טז, ח) ומסמיכות הפסוקים הוא למד: \u0003את שטעון ששה\u0004 ימים לאחריו — \u0003טעון לינה,\u0004 אולם \u0003את שאינו טעון ששה\u0004 ימים \u0003— אינו טעון לינה. למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא ר' יהודה? \u0003לאו למעוטי נמי\u0004 \u0005[האם לא למעט גם כן]\u0006 את \u0003שמיני של חג\u0004 שאין ששה ימים של חג לאחריו?","ודוחים: \u0003לא,\u0004 כוונתו היתה \u0003למעוטי\u0004 \u0005[למעט]\u0006 את \u0003פסח שני דכוותיה\u0004 \u0005[\u0006שהוא \u0005כמותו]\u0006 של פסח ראשון לענין קרבנו ובא ללמד שכיון שאין בו ששה ימי חג לאחריו, אין בו חובת לינה. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר שאין ר' יהודה בא למעט אלא את פסח שני, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הביכורים טעונין קרבן,\u0004 שיביא בנוסף להם אף קרבן שלמים \u0003ושיר\u0004 מיוחד למעמד זה המושר בפי הלויים \u0003ותנופה ולינה. מאן שמעת ליה\u0004 \u0005[\u0006מ\u0005מי שמעת אותו]\u0006 ש\u0003אמר\u0004 שיש מצות \u0003תנופה\u0004 בביכורים — \u0003ר' יהודה\u0004 הוא \u0003הו‍דה וקאמר\u0004 \u0005[ואמר]\u0006 בכל זאת \u0003טעון לינה,\u0004 משמע שלא בא ר' יהודה לשלול חובת לינה אלא מפסח שני.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בשיטת ר' יהודה בביכורים: \u0003ר' יהודה אומר:\u0004 נאמר בביכורים \u0003\"והנחתו\u0004 לפני ה' אלהיך\u0003\"\u0004 (דברים כו, י), \"והנחתו\" שנאמר — \u0003זו תנופה\u0004 שמניפים את טנא הביכורים לפני המזבח. \u0003אתה אומר זו תנופה, או אינו אלא\u0004 זו \u0003הנחה ממש\u0004 סמוך למזבח. \u0003כשהוא אומר\u0004 \"ולקח הכהן הטנא מידיך \u0003והניחו\u0004 לפני מזבח ה' אלהיך\" (דברים כו, ד) \u0003הרי הנחה אמורה, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 במה שאמר הכתוב \u0003\"והנחתו\" — זו תנופה.\u0004","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 הברייתא המחייבת לינה בביכורים אינה כשיטת ר' יהודה אלא כשיטת \u0003ר' אליעזר בן יעקב היא,\u0004 שאף הוא סבור שיש תנופה בביכורים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005];\u0006 נאמר: \u0003\"ולקח הכהן הטנא מידך\"\u0004 (דברים כו, ד) — \u0003לימד על הבכורים שטעונין תנופה,\u0004 אלו \u0003דברי ר' אליעזר בן יעקב.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר בן יעקב,\u0004 כיצד למד הוא מצוות תנופה ממילים אלה? ומשיבים: \u0003אתיא\u0004 \u0005[בא]\u0006 נלמד הדבר בגזירה שוה \u0003\"יד\" \"יד\" משלמים, כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בביכורים: \u0003\"ולקח הכהן הטנא מידך\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בשלמים: \u0003\"ידיו תביאינה את אשי ה'\u0004 את החלב על החזה יביאנו את החזה להניף אותו תנופה לפני ה'\u0003\"\u0004 (ויקרא ז, ל).","ועוד נלמד מהשוואת הכתובים: \u0003מה כאן\u0004 בבכורים — המניף הוא \u0003כהן, אף להלן\u0004 בשלמים — \u0003כהן\u0004 מניף, שהרי עוד טרם הנפה נאמר \"ולקח הכהן\", \u0003ומה להלן\u0004 בשלמים — \u0003בעלים\u0004 מניפים, \u0003אף כאן\u0004 בביכורים — \u0003בעלים\u0004 מניפים. \u0003הא כיצד\u0004 מקיימים שיניפו גם כהן וגם הבעלים? הבעלים מניחים ידם מתחת לשלמים או לביכורים ו\u0003כהן מניח ידו תחת יד בעלים ומניף,\u0004 ומכל מקום למדנו שגם ר' אליעזר בן יעקב מחייב תנופה בביכורים. ואין ראיה חותכת לדברים קודמים.","דיון זה לא הגיע לכלל סיכום סופי ולכן שואלים \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על הבעיה בברכת \"שהחיינו\" בשמיני של חג? ומשיבים: \u0003רב נחמן אמר: אומרים זמן בשמיני של חג. ורב ששת אמר: אין אומרים זמן בשמיני של חג.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 למעשה: \u0003אומרים זמן בשמיני של חג.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן,\u0004 ששנינו: \u0003שמיני\u0004"],["\u0003רגל בפני עצמו\u0004 הוא \u0003לענין\u0004 ששה דברים שסימנם \u0003פז\"ר קש\"ב.\u0004 והן: שהיה לו \u0003פייס\u0004 (גורל) \u0003בפני עצמו,\u0004 שלקרבנות חג הסוכות היה סידור מיוחד לחלקם בין כל עשרים וארבעה משמרות הכהנים ואילו בשמיני עושים הכהנים פייס מיוחד עבור הקרבנות שמקריבים ביום זה. וכן יש לו \u0003זמן (\u0004ברכת \"שהחיינו\") \u0003בפני עצמו.\u0004 והוא \u0003רגל בפני עצמו,\u0004 שאין חלות בו מצוות חג הסוכות. ומביאים בו \u0003קרבן בפני עצמו,\u0004 שאין קרבנות יום השמיני על פי סדר קרבנות חג הסוכות. ו\u0003שירה\u0004 ששרים הלווים על הקרבן, בשמיני היא כשיר \u0003בפני עצמו,\u0004 שאינו כשיר הקרבנות בסוכות. \u0003וברכה בפני עצמו\u0004 שמזכירים בכל הברכות והתפילות יום שמיני עצרת.","במשנה זו מפרטים את האמור במשנה הראשונה בפרק. החובה לגמור את \u0003ההלל והשמחה\u0004 (הבאת קרבנות שלמי שמחה ואכילתם) בחג הסוכות הם תמיד \u0003שמונה\u0004 ימים, ומבארים \u0003כיצד\u0004 עניינו — \u0003מלמד שחייב אדם\u0004 באמירת \u0003הלל ובשמחה ובכבוד יום טוב האחרון של חג כשאר כל ימות החג.\u0004","שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שחייבים בשמיני בשמחת החג — \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים];\u0006 נאמר בחג הסוכות, \u0003\"והיית אך שמח\"\u0004 (דברים טז, טו) ולמדים מכאן: \u0003לרבות לילי יום טוב האחרון,\u0004 שאף בהם קיימת חובת השמחה, באכילת בשר שלמים שהוקרבו מאתמול. ושואלים: \u0003או אינו אלא יום טוב הראשון\u0004 הוא שבא פסוק זה לרבות? ועל כך משיבים: \u0003כשהוא אומר \"אך\"\u0004 הרי זו לשון מיעוט, ו\u0003חלק\u0004 לילה זה משאר ימי החג.","ושואלים עוד: \u0003ומה ראית לרבות לילי יום טוב האחרון ולהוציא לילי יום טוב הראשון\u0004 לענין שמחה, שלא יוקרבו שלמי שמחה בערב החג ויאכלום למחרת? ומשיבים: \u0003מרבה אני לילי יום טוב האחרון שיש שמחה לפניו\u0004 ביום הקודם, ומסתבר שהכוונה שתהא השמחה נמשכת והולכת, \u0003ומוציא אני\u0004 את \u0003לילי יום טוב הראשון שאין שמחה לפניו,\u0004 שאין חובה להקריב בערב החג קרבנות מיוחדים.","מצות \u0003סוכה שבעה\u0004 ימים. \u0003כיצד\u0004 מקיימים שיהו אלה שבעה ימים שלמים, \u0003גמר מלאכול\u0004 ביום השביעי \u0003לא יתיר את סוכתו\u0004 מיד, לפי שחובת הסוכה קיימת עד סוף היום השביעי. \u0003אבל\u0004 בכל זאת \u0003מוריד את הכלים\u0004 מן הסוכה \u0003מן המנחה ולמעלה מפני כבוד יום טוב האחרון של חג\u0004 שצריך שיהיו לו כלים בביתו ביום זה.","ושואלים: \u0003אין לו כלים להוריד מהו,\u0004 מה יעשה? ותוהים: \u0003אין לו כלים?! אלא כי אשתמש במאי אשתמש\u0004 \u0005[כאשר השתמש\u0006 ואכל במשך החג \u0005במה השתמש]?\u0006 \u0003אלא\u0004 כך יש לשאול: \u0003אין לו מקום להוריד כליו\u0004 שאין יכול לסדר הכל בדירתו בו ביום וחייב להמשיך לאכול בסוכה \u0003מהו?\u0004 מה יעשה כדי להדגיש שאינו אוכל בסוכה לשם מצות סוכה אלא משום נוחיותו ולא יעבור על \"בל תוסיף\"? \u0003רב חייא בר רב אמר: פוחת בה ארבעה\u0004 שמוריד מסכך הסוכה ארבעה טפחים ופוסל את הסוכה בכך. \u0003ור' יהושע בן לוי אמר: מדליק בה את הנר\u0004 דבר שאסור לעשות בסוכה בימי החג.","ומעירים: \u0003ולא פליגי\u0004 \u0005[נחלקו]\u0006 בהלכה, אלא \u0003הא לן\u0004 \u0005[זה לנו]\u0006 לאנשי חוץ לארץ \u0003והא להו\u0004 \u0005[וזה להם]\u0006 לבני ארץ ישראל, שבני ארץ ישראל פוחתים מן הסוכה, משום שכבר עבר זמן חיובה, אבל בני חוץ לארץ היושבים בסוכה גם בשמיני משום ספק שביעי צריכים לעשות בה דבר אחר להיכר.","ושואלים: \u0003הא תינח\u0004 \u0005[זה נוח]\u0006 אם היתה זו \u0003סוכה קטנה\u0004 שהרי אמרנו (לעיל סוכה כט, א) שבסוכה קטנה אין מדליקין את הנר, אולם אם היתה זו \u0003סוכה גדולה\u0004 שאין איסור להדליק בה נר \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 מה עושים כדי להבחין שאינו יושב בה משום החג? ומשיבים: \u0003דמעייל\u0004 \u0005[שמכניס]\u0006 \u0003בה מאני מיכלא\u0004 \u0005[כלי אוכל]\u0006 קדירות שבישלו בהן אוכל. ש\u0003אמר רבא: מאני מיכלא\u0004 \u0005[כלי אוכל] —\u0006 \u0003בר ממטללתא\u0004 \u0005[חוץ לסוכה],\u0006 \u0003מאני משתיא\u0004 \u0005[כלי שתיה]\u0006 \u0003— במטללתא\u0004 \u0005[ב\u0006תוך \u0005הסוכה],\u0006 ומתוך שמכניס בסוכה כלי אוכל, הרי זה סימן שאין זו סוכה של מצוה.","\u0003ניסוך המים\u0004 שהיה בחג במקדש \u0003כיצד\u0004 היה נעשה? \u0003צלוחית\u0004 (קנקן) \u0003של זהב מחזקת\u0004 (המכילה) \u0003שלשה לוגים היה ממלא מן השילוח. הגיעו\u0004 מביאי הצלוחית \u0003לשער המים\u0004 שהוא אחד משערי העזרה (ונקרא כן מפני שהיו מכניסים דרכו את מי הניסוך למקדש), \u0003תקעו והריעו ותקעו\u0004 לאות שמחה. \u0003עלה\u0004 הכהן המנסך \u0003בכבש\u0004 של המזבח \u0003ופנה לשמאלו\u0004 שהיא קרן מערבית דרומית של המזבח, ו\u0003שני ספלים של כסף היו שם\u0004 שלתוכם היה מנסך. \u0003ר' יהודה אומר: של סיד היו, אלא שהיו מושחרין פניהם מפני היין\u0004 ולכן היו דומים לכסף. ואותם ספלים \u0003מנוקבין\u0004 היו סמוך לשוליהם"],["\u0003כמין שני חוטמין דקין\u0004 (בליטות נקובות קטנות) \u0003אחד מעובה\u0004 יותר לניסוך היין \u0003ואחד דק\u0004 לניסוך המים, \u0003כדי שיהו שניהם\u0004 המים והיין שכרגיל אינם נוזלים במהירות שווה, בכל זאת \u0003כלים בבת אחת.\u0004 ומלכתחילה היה הספל שב\u0003מערבו\u0004 של המזבח \u0003של מים,\u0004 וזה שב\u0003מזרחו\u0004 היה \u0003של יין,\u0004 אולם אם \u0003עירה\u0004 צלוחית \u0003של מים לתוך\u0004 ספל \u0003של יין ושל יין לתוך של מים — יצא\u0004 שאין מקום הניסוך מעכב.","\u0003ר' יהודה אומר:\u0004 לא בצלוחית גדולה זו היה מנסך אלא \u0003בלוג היה מנסך\u0004 את המים, וכן שניסוך זה היה \u0003כל שמונה\u0004 ימים של חג ולא שבעה ימים בלבד. \u0003ולמנסך אומר לו\u0004 הממונה: \u0003הגבה ידך,\u0004 שיראו הכל כיצד אתה מנסך כראוי לתוך הספל. \u0003שפעם אחד נסך\u0004 צדוקי \u0003אחד\u0004 בכוונה \u0003על גבי רגליו\u0004 לפי שלא הודה בניסוך המים, ומתוך זעם \u0003רגמוהו כל העם באתרוגיהן.\u0004","\u0003כמעשהו\u0004 של הניסוך \u0003בחול כך מעשהו בשבת, אלא\u0004 שלא היו שואבים בשבת מים מן השילוח, אלא \u0003היה ממלא מערב שבת חבית של זהב שאינה מקודשת\u0004 בקדושת כלי שרת \u0003מן השילוח ומניחה בלשכה\u0004 וממנה היו מביאים את המים. אם \u0003נשפכה\u0004 חבית זו או \u0003נתגלתה\u0004 ויש חשש שמא הטיל בה נחש ארסו וכיוצא בו, \u0003היה ממלא\u0004 את המים לניסוך המים \u0003מן הכיור. שהיין והמים\u0004 שהיו \u0003מגולין\u0004 — \u0003פסולין\u0004 הן \u0003לגבי מזבח\u0004 שכיון שאסור לאדם לשתותם, מחשש סכנה, אף אין מנסכים על המזבח דבר שאינו ראוי לאדם.","לגבי המנהגים שנהגו בניסוך המים ובכללם המנהג לתקוע להריע ולתקוע בהגיע המים למקדש, שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]?\u0006 \u0003אמר רב עינא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושאבתם מים בששון\u0004 ממעיני הישועה\u0003\"\u0004 (ישעיה יב, ג), ללמד ששאיבה זו של המים מן המעין היתה, ובשמחה יתירה נעשתה.","אגב הבאת פסוק זה מסופר: \u0003הנהו תרי מיני\u0004 \u0005[אותם שני מינים,\u0006 כופרים\u0005],\u0006 \u0003חד שמיה\u0004 \u0005[אחד\u0006 היה \u0005שמו]\u0006 \u0003ששון וחד שמיה\u0004 \u0005[ואחד\u0006 היה \u0005שמו]\u0006 \u0003שמחה, אמר ליה\u0004 \u0005[לו]\u0006 \u0003ששון לשמחה: אנא עדיפנא מינך\u0004 \u0005[אני עדיף ממך],\u0006 \u0003דכתיב\u0004 \u0005[\u0006כיון \u0005שנאמר]:\u0006 \u0003\"ששון ושמחה ישיגו\u0004 ונסו יגון ואנחה\u0003\"\u0004 (ישעיה לה, י), הרי שמקדימים ששון לפני שמחה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמחה לששון:\u0004 להיפך, \u0003אנא עדיפנא מינך\u0004 \u0005[אני עדיף ממך]\u0006 \u0003דכתיב\u0004 \u0005[\u0006כיון \u0005שנאמר]:\u0006 \u0003\"שמחה וששון ליהודים\"\u0004 (אסתר ח, יז). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ששון לשמחה: חד יומא שבקוך ושויוך פרוונקא\u0004 \u0005[יום אחד יעזבוך ויעשו אותך כשליח],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי בשמחה תצאו\"\u0004 (ישעיה נה, יב), ששמחה היא כשליח ההולך לפני העם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמחה לששון: חד יומא שבקוך ומלו בך מיא\u0004 \u0005[יום אחד יעזבוך וימלאו בך מים],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ושאבתם מים בששון\"\u0004 (ישעיה יב, ג).","כיוצא בזה מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[אותו מין,\u0006 כופר\u0005]\u0006 \u0003דשמיה\u0004 \u0005[ששמו]\u0006 \u0003ששון לר' אבהו: עתידיתו דתמלו\u0004 \u0005[עתידים אתם למלא]\u0006 \u0003לי מים לעלמא דאתי\u0004 \u0005[בעולם הבא],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ושאבתם מים בששון\"\u0004 (ישעיה יב, ג) \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הוה כתיב\u0004 \u0005[אם היה נאמר]\u0006 \u0003\"לששון\"\u0004 — הרי זה \u0003כדקאמרת\u0004 \u0005[כפי שאמרת],\u0006 אולם \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"בששון\"\u0004 כוונתו: \u0003משכיה דההוא גברא משוינן ליה גודא\u0004 \u0005[עורו של אותו אדם\u0006 כלומר עורך שלך \u0005עושים אותו נאד]\u0006 \u0003ומלינן ביה מיא\u0004 \u0005[וממלאים בו מים].\u0006","שנינו במשנה: \u0003עלה בכבש ופנה לשמאלו. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל העולים למזבח עולין דרך ימין\u0004 כלומר פונים ימינה \u0003ומקיפין\u0004 את המזבח \u0003ויורדין דרך שמאל. חוץ מן העולה לשלשה דברים הללו\u0004 המפורטים להלן, \u0003שעולין\u0004 לצורכם \u0003דרך שמאל וחוזרין על העקב\u0004 (באותו כיוון שבאו). \u0003ואלו הן: ניסוך המים, וניסוך היין, ועולת העוף כשרבתה במזרח,\u0004 שכשהיו כהנים מרובים עוסקים בעולות אלה במקומם למזרחו של המזבח, ולא היה שם מקום לכולם, היו הנותרים מולקים אותה במערבו של המזבח.","שנינו במשנה כי לדעת ר' יהודה הספלים לא היו מכסף \u0003אלא\u0004 מסיד, וטעו בהם לחשוב שהם מכסף משום ש\u0003היו משחירין.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לספל המיוחד ל\u0003יין\u0004 ומובן מדוע היה \u0003משחיר\u0004 — מפני היין שבו, אולם \u0003דמיא\u0004 \u0005[\u0006ספל המיוחד \u0005למים]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 היה \u0003משחיר?\u0004 ומשיבים: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 אם \u0003עירה של מים לתוך של יין, ושל יין לתוך של מים — יצא,\u0004 פעמים שהיו מחליפים, ולכן אף הספל \u0003של מים אתי לאשחורי\u0004 \u0005[היה בא,\u0006 עשוי \u0005להשחיר].\u0006","שנינו במשנה שהיו הספלים \u0003מנוקבין כמין שני חוטמין\u0004 דקים אחד עבה ואחד דק. ושואלים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר שמשנתנו]\u0006 כשיטת \u0003ר' יהודה היא ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים];\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יהודה אומר: בלוג היה מנסך כל שמונה\u0004 ימים ולא בשלושה לוגים, ולשיטתו אכן היה הבדל גדול בין כמות היין שהיא שלושה לוגים לבין המים שהם לוג אחד בלבד ולכך היה צריך לעשות ליין נקב עבה יותר. \u0003דאי רבנן\u0004 \u0005[שאם\u0006 כשיטת \u0005חכמים]\u0006 שאף צלוחית המים היתה של שלוש לוגים — אם כן, \u0003כי הדדי נינהו\u0004 \u0005[\u0006הרי זה \u0005כמו זה הם]\u0006 ומדוע עובי הפיות היה שונה?","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 אלא \u0003חמרא סמיך מיא קליש\u0004 \u0005[היין סמיך והמים קלושים,\u0006 דלילים\u0005]\u0006 ולכן היין מתעכב לצאת יותר מן המים, וכדי שיצאו בשווה צריך להרחיב את פי הספל של היין.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר ששיטת המשנה היא כחכמים, \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כשיטת \u0003ר' יהודה,\u0004 אם כן חילוק זה ששנינו במשנה \"מעובה\" ו\"דק\" אינו החילוק בו נוקט ר' יהודה בענין זה במקום אחר, שכן \u0003\"רחב\" ו\"קצר\" אית ליה\u0004 \u0005[יש לו],\u0006 שלשיטתו זה היה ההבדל, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' יהודה אומר: שני קשוואות,\u0004 כלומר: צינורות קטנים \u0003היו שם, אחד של מים ואחד של יין, של יין פיה רחב ושל מים פיה קצר, כדי שיהו שניהם כלין בבת אחת\u0004 משמע שלא היו שם חוטמים אלא מיני צינורות ושוויסות נזילת המים והיין היה נעשה באמצעות הארכת צינור היין. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא, שאין משנתנו כדעת ר' יהודה.","שנינו במשנה כי בין שני הספלים \u0003מערבו\u0004 היה \u0003של מים\u0004 ושהיו אומרים למנסך שיגביה ידו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בצדוקי אחד שניסך\u0004 את המים \u0003על גבי רגליו, ורגמוהו כל העם באתרוגיהן,\u0004 מפני זעמם עליו. \u0003ואותו היום נפגמה קרן המזבח,\u0004 מפני רגימה זו וכל המהומה שאירעה לאחר מכן, \u0003והביאו בול\u0004 (גוש) \u0003של מלח וסתמוהו\u0004 את מקום הפגום \u0003לא מפני שהוכשר לעבודה\u0004 על ידי סתימה זו, \u0003אלא מפני\u0004 הכבוד \u0003שלא יראה\u0004 ה\u0003מזבח פגום.\u0004"],["\u0003שכל מזבח שאין לו לא כבש ולא קרן ולא יסוד ולא ריבוע\u0004 (שלא נעשה כריבוע או שנפגם ריבועו), אם חסר בו אחד מאלה — הריהו \u0003פסול לעבודה. ר' יוסי בר יהודה אומר: אף הסובב\u0004 (הכרכוב) הוא חלק מעכב במזבח.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: שיתין\u0004 שהם הנקבים והחללים שהיו במזבח ומתחתיו, \u0003מששת ימי בראשית נבראו. שנאמר: \"חמוקי ירכיך כמו חלאים מעשה ידי אמן\"\u0004 (שיר השירים ז, ב). ומפרשים בדרך הרמז: \u0003\"חמוקי ירכיך\"\u0004 — \u0003אלו השיתין\u0004 שהם מוסתרים במזבח כחמוקים אלה \u0003\"כמו חלאים\"\u0004 כוונתו — \u0003שמחוללין\u0004 (חלולים) \u0003ויורדין עד התהום. \"מעשה ידי אמן\" — זו מעשה ידי אומנותו של הקדוש ברוך הוא.\u0004 ומעין זה \u0003תנא דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר: \u0003\"בראשית\"\u0004 (בראשית א, א) \u0003אל תיקרי \"בראשית\" אלא \"ברא שית\",\u0004 כלומר: מראשית בריאת העולם נבראו שיתין אלה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יוסי אומר: שיתין\u0004 אלה היו \u0003מחוללין\u0004 (חלולים) \u0003ויורדין עד לתהום. שנאמר: \"אשירה נא לידידי שירת דודי לכרמו כרם היה לידידי בקרן בן שמן. ויעזקהו ויסקלהו ויטעהו שרק ויבן מגדל בתוכו, וגם יקב חצב בו\"\u0004 (ישעיה ה, א-ב), והוא מפרשו כמשל למקדש ולאשר בו: \u0003\"ויטעהו שרק\" — זה בית המקדש, \"ויבן מגדל בתוכו\" — זה מזבח, \"וגם יקב חצב בו\" — אלו השיתין,\u0004 לומר שהן בריאה טבעית מראשית ימי עולם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' אלעזר בר צדוק: לול\u0004 (חלל) \u0003קטן היה בין כבש למזבח במערבו של כבש, ואחת לשבעים שנה פרחי כהונה\u0004 (צעירי הכהנים) היו \u0003יורדין לשם, ומלקטין משם יין קרוש\u0004 משיירי הנסכים, שנתייבשו מימיו \u0003שדומה\u0004 לבסוף לאחר שנקרש \u0003לעיגולי דבילה\u0004 (תאנה יבשה) \u0003ובאין ושורפין אותו בקדושה\u0004 בעזרה, \u0003שנאמר: \"בקדש הסך נסך שכר לה'\"\u0004 (במדבר כח, ז)"],["\u0003כשם שניסוכו בקדושה כך שריפתו בקדושה.\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות]\u0006 כיצד למדים מכתוב זה ענין שריפה שלא נאמר בו? \u0003אמר רבינא: אתיא\u0004 \u0005[בא]\u0006 נלמד הדבר בגזירה שווה \u0003\"קדש\" \"קדש\". כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין נסכים: \u0003\"בקדש הסך נסך\u0004 שכר\" (במדבר כח, ז) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין הנותר מן הקרבנות לאחר זמנם: \u0003\"ושרפת את הנותר באש לא יאכל כי קדש הוא\"\u0004 (שמות כט, לד) ולמדים משם שאף דין הנסכים לבסוף בשריפה.","ומעירים: \u0003כמאן אזלא הא דתנן\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 הלכה \u0005זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נסכים, בתחילה\u0004 לפני שניסכום \u0003מועלין בהן,\u0004 שהן כשאר הקדשים, אולם אם כבר \u0003ירדו לשיתין — אין מועלין בהן\u0004 עוד, לפי שכבר נעשתה מצוותם. \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שכשיטת \u0003ר' אלעזר בר צדוק היא\u0004 שלא היו הנסכים יורדים לתהום אלא ללול ונלקטים ממנו אחת לשבעים שנה! \u0003דאי רבנן\u0004 \u0005[שאם\u0006 כשיטת \u0005חכמים]\u0006 היא, כיצד אפשר למעול בהם? \u0003הא נחתו להו\u0004 \u0005[הרי\u0006 לשיטתם \u0005ירדו להם\u0006 הנסכים\u0005]\u0006 \u0003לתהום\u0004 דרך השיתין, ואין שייכת בהם עוד מעילה!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 אולם כאן מדובר \u0003בדאיקלט\u0004 \u0005[שנקלט]\u0006 קצת מן היין בתוך כלי שתלוהו בתוך השיתין.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 שמועה זו בלשון אחרת: \u0003לימא רבנן\u0004 \u0005[האם נאמר\u0006 שכשיטת \u0005חכמים]\u0006 \u0003היא ולא\u0004 כשיטת \u0003ר' אלעזר בר צדוק? דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' אלעזר\u0004 היא, הרי \u0003אכתי בקדושתייהו קיימי\u0004 \u0005[עדיין בקדושתם\u0006 הם \u0005עומדים],\u0006 שהרי לדעתו צריך לשורפם, ואם כן מן הסתם לשיטתו יש בהם עדיין קדושה ודין מעילה! ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003ר' אלעזר,\u0004 מכל מקום אף לדעתו אין בהם דין מעילה כי \u0003אין לך דבר שנעשתה מצותו ומועלין בו\u0004 לאחר מכן. \u0003אמר ריש לקיש: בזמן שמנסכין יין על גבי\u0004 ה\u0003מזבח, פוקקין את השיתין\u0004 מלמעלה בראש המזבח, כדי שישאר היין על גבי המזבח וייראה גרונו של המזבח כביכול מלא ושהוא שבע. \u0003לקיים מה שנאמר: \"בקדש הסך נסך שכר לה'\".\u0004","ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד למדים מפסוק זה הלכה זו? \u0003אמר רב פפא: \"שכר\" — לשון שתיה,\u0004 וכן \u0003לשון שביעה,\u0004 וכן \u0003לשון שכרות.\u0004 וכדי להדגיש צדדים אלה שבניסוך היין, עשו שיהא היין ממלא את חלל המזבח. \u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כי שבע איניש חמרא\u0004 \u0005[כאשר שבע אדם מן היין] —\u0006 \u0003מגרוניה שבע\u0004 \u0005[מגרונו הוא שבע]\u0006 ממילוי היין בגרון ולא מכניסתו לבטנו, בניגוד לשביעה ממזון. \u0003אמר רבא:\u0004 מכאן נלמד כי \u0003צורבא מרבנן דלא נפישא ליה חמרא, ליגמע גמועי\u0004 \u0005[תלמיד חכם שאין מרובה אצלו יין שיגמע\u0006 אותו \u0005בגמיעות\u0006 גדולות\u0005]\u0006 כך שיתמלא גרונו, שהרי למדנו שבדרך זו רבה ההנאה ממנו. וכן נהג \u0003רבא\u0004 עצמו ש\u0003אכסא דברכתא אגמע גמועי\u0004 \u0005[בכוס של ברכה\u0006 היה \u0005גומע בגמיעות\u0006 גדולות\u0005]\u0006 כדי לכבד ולהדר שתיית יין זו.","כיון שלענין שיתין הובאו מדרשי כתובים משיר השירים מביאים דרשות אחרות על פסוקים אלה. \u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מה יפו פעמיך בנעלים בת נדיב\"\u0004 (שיר השירים ז, ב) — \u0003מה יפו פעמותיהן\u0004 (רגליהם) \u0003של ישראל בשעה שעולין לרגל. \"בת נדיב\"\u0004 — הרי זו \u0003בתו של אברהם אבינו שנקרא נדיב, שנאמר: \"נדיבי עמים נאספו עם אלהי אברהם\"\u0004 (תהלים מז, י), ובהדגשה: \u0003אלהי אברהם ולא אלהי יצחק ויעקב.\u0004 ומדוע מייחסים את ישראל דווקא לאברהם — \u0003אלא אלהי אברהם שהיה תחילה לגרים —\u0004 ולכן אפשר שיאספו אליו נדיבי עמים כולם.","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב ענן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"חמוקי ירכיך\"\u0004 (שיר השירים ז, ב) — \u0003למה נמשלו דברי תורה כירך? לומר לך: מה ירך\u0004 נמצא תמיד \u0003בסתר,\u0004 שמכוסה בגדים, \u0003אף דברי תורה\u0004 יפה להם שייאמרו \u0003בסתר\u0004 ולא בפומבי.","\u0003והיינו\u0004 \u0005[והוא]\u0006 ש\u0003אמר ר' אלעזר, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"הגיד לך אדם מה טוב ומה ה' דורש ממך כי אם עשות משפט ואהבת חסד והצנע לכת עם אלהיך\"\u0004 (מיכה ו, ח). וכך הוא מפרש: \u0003\"עשות משפט\" — זה הדין, \"ואהבת חסד\" — זו גמילות חסדים, \"והצנע לכת עם אלהיך\" — זו הוצאת המת\u0004 שצריכים זרים לטפל בו \u0003והכנסת כלה\u0004 עניה \u0003לחופה\u0004 שראוי לעשותם בלא פרסומת יתירה. \u0003והלא דברים קל וחומר: ומה דברים\u0004 אלה \u0003שדרכן לעשותן בפרהסיא\u0004 שהרי גם בהלוויית המת וגם בחופה באים רבים להשתתף, ובכל זאת \u0003אמרה תורה\u0004 בהם \u0003\"הצנע לכת\", דברים שדרכן לעשותן בצנעא\u0004 (כגון צדקה לעניים) \u0003על אחת כמה וכמה,\u0004 שיש להצטנע בהם.","\u0003אמר ר' אלעזר: גדול העושה צדקה יותר\u0004 מהמקריב \u0003כל\u0004 סוגי \u0003הקרבנות, שנאמר: \"עשה צדקה ומשפט נבחר לה' מזבח\"\u0004 (משלי כא, ג), ובכלל \"זבח\" כל סוגי הקרבנות. \u0003ואמר ר' אלעזר: גדולה גמילות חסדים\u0004 שעוזר לאדם בדבר שהוא זקוק לעזרה \u0003יותר מן הצדקה, שנאמר: \"זרעו לכם לצדקה וקצרו לפי חסד\"\u0004 (הושע י, יב). וכך הלימוד: \u0003אם אדם זורע — ספק אוכל ספק אינו אוכל,\u0004 שמא לא יצמחו הזרעים, ואפילו אם יצמחו שמא ינזקו במחלות וכדומה, \u0003אדם קוצר — ודאי אוכל.\u0004 ומן הכתוב למדנו שהצדקה מתייחסת לזריעה ואילו מעשה החסד מתייחס לקצירה.","\u0003ואמר ר' אלעזר: אין צדקה משתלמת\u0004 לו מן השמים לפי גודל הסכומים שנתן \u0003אלא לפי חסד\u0004 ונדיבות שהיו בצדקה זו, ולפי דרך הנתינה ורוב ההשתדלות וההתבוננות שעשה \u0003בה, שנאמר: \"זרעו לכם לצדקה וקצרו לפי חסד\"\u0004 (הושע י, יב).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בשלשה דברים גדולה גמילות חסדים יותר מן הצדקה: צדקה\u0004 עושה אדם \u0003בממונו\u0004 בלבד, ואילו \u0003גמילות חסדים — בין בגופו\u0004 שעוזר לאחרים, \u0003בין בממונו.\u0004 וכן: \u0003צדקה\u0004 ניתנת רק \u0003לעניים,\u0004 ואילו \u0003גמילות חסדים\u0004 שייכת \u0003בין לעניים בין לעשירים.\u0004 ועוד: \u0003צדקה\u0004 אפשר לעשות רק עם אנשים \u0003חיים,\u0004 ואילו \u0003גמילות חסדים\u0004 יכולה להיעשות \u0003בין לחיים בין למתים.\u0004","\u0003ואמר ר' אלעזר: כל העושה צדקה ומשפט, כאילו מילא\u0004 את כל \u0003העולם כולו חסד. שנאמר: \"אוהב צדקה ומשפט חסד ה' מלאה הארץ\"\u0004 (תהלים לג, ה). \u0003שמא תאמר כל הבא לקפוץ קופץ,\u0004 שלכל אדם ניתנת הזדמנות לעשות חסד אמיתי — \u0003תלמוד לומר: \"מה יקר חסדך אלהים\"\u0004 (תהלים לו, ח), שדבר יקר ונדיר הוא לעשות חסד כראוי. \u0003יכול אף ירא שמים כן\u0004 אין מזדמן לו חסד תמיד — \u0003תלמוד לומר: \"וחסד ה' מעולם ועד עולם על יראיו\"\u0004 (תהלים קג, יז).","\u0003אמר ר' חמא בר פפא: כל אדם שיש עליו חן — בידוע שהוא ירא שמים. שנאמר: \"וחסד ה' מעולם ועד עולם על יראיו\",\u0004 כלומר: כשרואים שיש חן וחסד לאדם, ודאי הוא מיראי ה'. \u0003ואמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"פיה פתחה בחכמה ותורת חסד על לשונה\"\u0004 (משלי לא, כו), \u0003וכי יש תורה של חסד ויש תורה שאינה של חסד? אלא\u0004 כך יש להסביר: \u0003תורה לשמה\u0004 — \u0003זו היא תורה של חסד,\u0004 שהרי לומדה בלב שלם ומרצונו, תורה \u0003שלא לשמה\u0004 — \u0003זו היא תורה שאינה של חסד. איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 כך פירושו: \u0003תורה\u0004 שהוא לומד על מנת \u0003ללמדה\u0004 לאחרים — \u0003זו היא תורה של חסד,\u0004 תורה שלומד \u0003שלא ללמדה\u0004 לאחרים — \u0003זו היא תורה שאינה של חסד.\u0004","שנינו במשנה בענין ניסוך המים כי \u0003כמעשהו בחול\u0004 כך מעשהו בשבת, אלא שבשבת היו מכניסים את המים לחבית שאינה מקודשת. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יעשו כן? \u0003נייתי\u0004 \u0005[שיביא]\u0006 את המים בחבית \u0003מקודשת! אמר זעירי: קסבר\u0004 \u0005[סבר]\u0006 חכם זה \u0003אין שיעור למים\u0004 שצריכים לנסך, \u0003וכלי שרת מקדשין\u0004 מעצמם את תוכנם, אם הוא דבר הראוי להיות קדוש, אפילו \u0003שלא מדעת\u0004 גם אם אינו מתכוון לקדשם."]]};
